const PKEYS = Object.keys(PAL);
/* Cor de desenho de uma paleta: gradiente quando existe, cor chapada quando não.
   Usar sempre isto onde antes se escrevia `p.bar` para pintar. */
function _palPintura(p) { return (p && (p.grad || p.bar)) || '#6366f1'; }
function _palEhPremium(k) { return !!(PAL[k] && PAL[k].premium); }
function _palEhAnimada(k) { return !!(PAL[k] && PAL[k].anim); }
function _palEhVibrante(k) { return !!(PAL[k] && PAL[k].vibrante); }
/* Liga ou desliga as classes que a cor exige. Existe como função porque são
   três lugares que pintam (montar a nota, trocar a cor, desenhar a pasta) e um
   esquecido deixaria a nota parada numa cor só — ou, pior, com o texto apagado
   sobre fundo colorido — sem erro nenhum aparecendo.

   `vibrante` é o que torna o fundo colorido viável. O corpo da nota é branco a
   50%: sobre fundo quase preto isso contrasta bem, sobre fundo colorido some.
   A classe sobe a opacidade dos textos mais apagados. Sem ela só há dois
   caminhos, e os dois ruins — fundo quase preto, ou texto ilegível. */
function _palAplicarClasses(el, key) {
  if (!el) return;
  el.classList.toggle('cor-viva', _palEhAnimada(key));
  el.classList.toggle('vibrante', _palEhVibrante(key));
}
/* Marca a AMOSTRA do seletor. Sem isto, a cor que se move aparece como um
   gradiente parado na hora de escolher — e a pessoa só descobre o que ela faz
   depois de aplicar na nota. */
function _palMarcarAmostra(el, key) {
  if (el && _palEhAnimada(key)) el.classList.add('cor-viva');
}

function _avisarMovimentoReduzido() {
  if (typeof window.matchMedia !== 'function') return;
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  /* A Cor viva fica parada DE PROPÓSITO quando o sistema pede menos movimento
     — e parada é indistinguível de quebrada. Sem este aviso a única saída é
     adivinhar; com ele, o console responde na hora. */
  console.info('[cores] O sistema está pedindo menos movimento, então a cor ' +
    '"Cor viva" fica parada de propósito. No Windows: Configurações → ' +
    'Acessibilidade → Efeitos visuais → Efeitos de animação.');
}
window.addEventListener('DOMContentLoaded', _avisarMovimentoReduzido);

/* Rótulo da cor no idioma do app. As chaves (`indigo`, `gNebulosa`) vão para o
   banco e não mudam; o que muda é só o nome lido. */
function _palRotulo(key) {
  const p = PAL[key];
  if (!p) return key;
  const chave = 'app.pal_' + key;
  return _appText(chave, p.label);
}

