function _appLocale() {
  const shared = window.MyDeskI18n?.getLocale?.();
  if (shared) return shared;
  const language = String(localStorage.getItem('md_lang') || navigator.language || 'pt').toLowerCase();
  if (language.startsWith('en')) return 'en-US';
  if (language.startsWith('es')) return 'es-ES';
  return 'pt-BR';
}

function _appText(key, fallback, vars) {
  return window.MyDeskI18n?.t?.(key, vars, fallback) || fallback || key;
}

// Password helpers — btoa/atob break on non-ASCII, so we use 4-digit hex encoding
function strToHex(s) {
  return Array.from(s).map(c => c.charCodeAt(0).toString(16).padStart(4,'0')).join('');
}
