    renomeou:'renombró la carpeta', pasta:'creó la carpeta', concluiu:'completó',
    status:'cambió el estado de', comentou:'comentó en',
    formulario:'creó el formulario', resposta:'recibió una respuesta en',
    anexou:'adjuntó un archivo en', entrou:'entró al workspace',
