function _crmTodayLocalIso() {
  const agora = new Date();
  return new Date(agora.getTime() - agora.getTimezoneOffset() * 60_000)
    .toISOString().slice(0, 10);
}

function _crmSelectOptions(items, selected, placeholder) {
  return `<option value="">${xe(placeholder)}</option>` + items.map(item =>
    `<option value="${xe(item)}"${item === selected ? ' selected' : ''}>${
      xe(_appText(CRM_PROFILE_OPTION_I18N[item], item))
    }</option>`
  ).join('');
}

/* aoSalvar: quem abriu o cadastro às vezes precisa saber o que foi gravado —
   a importação de respostas, por exemplo, só marca a resposta como aproveitada
   depois que o cliente existe de verdade. Cancelar não chama nada. */
function _openRecordModal(rec, prefill, aoSalvar) {
  const isEdit = !!rec;
  let   data   = rec || prefill || {};

  /* No modelo de recrutamento, o ＋ da faixa cria CANDIDATO: a ficha já abre
     com o modelo "Processo seletivo" escolhido, e com ele os campos e as
     etapas do processo. Sem isto, cada candidato novo nasceria como ficha
     simples e não apareceria no funil — que é o quadro que está na tela. */
  const paraRH = !isEdit && crmModeloRH();
  if (paraRH && !data.template) {
    data = Object.assign({}, data, { template: MD_RH.CHAVE_MODELO });
  }

  // Verificar limite se novo registro
  if (!isEdit) {
    const check = _crmCanCreate();
    if (!check.ok) {
      toast('🔒', _appText('app.itemsLimitReached',
        'Limite de {limit} itens atingido. Faça upgrade!', { limit:check.limit }));
      if (typeof showPremiumModal === 'function') showPremiumModal();
      return;
    }
  }

  const bg  = document.createElement('div');
  bg.className = 'modal-bg';

  const initStatus = data.status || 'pending';
  const privacyLabel = (_activeWs || _activeGroupWs)
    ? _appText('app.sharedParticipants', '👥 Compartilhado com participantes')
    : _appText('app.privateData', '🔒 Dados privados');

  bg.innerHTML = `
    <div class="modal crm-client-modal">
      <div class="crm-client-head">
        <div class="crm-client-head-icon">${isEdit ? '✎' : '+'}</div>
        <div>
          <div class="m-h1">${xe(isEdit
            ? _appText('app.editClient', 'Editar cliente')
            : paraRH
              ? _appText('rh.newCandidate', 'Novo candidato')
              : _appText('app.newClient', 'Novo cliente'))}</div>
          <div class="m-sub">${xe(isEdit
            ? _appText('app.updateClientDesc', 'Atualize o perfil cadastral e financeiro.')
            : paraRH
              ? _appText('rh.newCandidateDesc', 'Dados do candidato, vaga e etapas do processo seletivo.')
              : _appText('app.newClientDesc', 'Centralize dados cadastrais, endereço e cobrança.'))}</div>
        </div>
        <span class="crm-client-private">${privacyLabel}</span>
      </div>

      <div class="crm-client-section-title"><span>01</span> ${xe(_appText('app.personalData', 'Dados pessoais'))}</div>

      <label class="m-lbl" for="crm-m-name">${xe(_appText('app.clientName', 'Nome do cliente'))}</label>
      <input class="m-inp" id="crm-m-name" placeholder="${sanitizeAttr(_appText('app.clientExample', 'Ex.: João Silva'))}" value="${xe(data.name||'')}">

      <!-- Foto da pessoa. Reduzida a 128px e gravada como JPEG antes de ir ao
           banco: o anexo mora em base64 dentro do registro, e uma foto de
           celular sem redimensionar levaria megabytes para mostrar um círculo
           de 34 pixels na tela. -->
      <div class="crm-foto-linha">
        <label class="crm-foto" id="crm-m-foto-alvo" tabindex="0"
               title="${sanitizeAttr(_appText('app.addPhoto', 'Adicionar foto'))}">
          <input type="file" id="crm-m-foto" accept="image/*" hidden>
          <span class="crm-foto-vazia">${xe(_appText('app.photo', 'Foto'))}</span>
        </label>
        <div class="crm-foto-txt">
          <div>${xe(_appText('app.photoHint', 'Clique para escolher uma foto.'))}</div>
          <div class="crm-foto-aviso">${xe(_appText('app.photoLocalWarn',
            'Fica guardada só neste navegador, para não pesar no banco. Em outro aparelho aparece a inicial.'))}</div>
          <button type="button" class="crm-foto-tirar" id="crm-m-foto-tirar">${xe(_appText('app.removePhoto', 'Remover'))}</button>
        </div>
      </div>

      <div class="crm-modal-row">
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-email">${xe(_appText('app.fieldEmail', 'E-mail'))}</label>
          <input type="email" class="crm-modal-inp" id="crm-m-email" maxlength="160"
            autocomplete="off" placeholder="cliente@email.com" value="${xe(data.email||'')}">
        </div>
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-phone">${xe(_appText('app.phone', 'Telefone'))}</label>
          <input type="tel" class="crm-modal-inp" id="crm-m-phone" maxlength="24"
            autocomplete="off" placeholder="(11) 99999-9999" value="${xe(data.phone||'')}">
        </div>
      </div>

      <label class="crm-modal-lbl" for="crm-m-cpf">${xe(_appText('app.cpfOptional', 'CPF/CNPJ (opcional)'))}</label>
      <div class="crm-lookup-row">
        <input class="m-inp" id="crm-m-cpf" inputmode="text" autocomplete="off"
          placeholder="000.000.000-00" maxlength="18" value="${xe(data.cpf||'')}">
        <button type="button" class="crm-lookup-btn" id="crm-m-cnpj-btn" disabled>${xe(_appText('app.checkCnpj', 'Consultar CNPJ'))}</button>
      </div>
      <div class="crm-lookup-feedback" id="crm-m-cnpj-info" aria-live="polite"></div>

      <div class="crm-modal-row">
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-birth">${xe(_appText('app.birthDate', 'Data de nascimento'))}</label>
          <input type="date" class="crm-modal-inp" id="crm-m-birth" min="1900-01-01"
            max="${_crmTodayLocalIso()}" value="${xe(data.birthDate||'')}">
        </div>
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-marital">${xe(_appText('app.maritalStatus', 'Estado civil'))}</label>
          <select class="crm-modal-inp" id="crm-m-marital">
            ${_crmSelectOptions(CRM_MARITAL_STATUS_OPTIONS, data.maritalStatus, _appText('app.select', 'Selecione'))}
          </select>
        </div>
      </div>

      <label class="crm-modal-lbl" for="crm-m-education">${xe(_appText('app.education', 'Escolaridade'))}</label>
      <select class="crm-modal-inp crm-modal-inp-spaced" id="crm-m-education">
        ${_crmSelectOptions(CRM_EDUCATION_OPTIONS, data.education, _appText('app.selectEducation', 'Selecione a escolaridade'))}
      </select>

      <div class="crm-client-section-title"><span>02</span> ${xe(_appText('app.recordTemplate', 'Modelo da ficha'))}</div>

      <label class="crm-modal-lbl" for="crm-m-template">${xe(_appText('app.followUpType', 'Tipo de acompanhamento'))}</label>
      <select class="crm-modal-inp crm-modal-inp-spaced" id="crm-m-template">
        <option value="">${xe(_appText('app.simpleRecord', 'Ficha simples'))}</option>
        ${(window.MD_NICHOS ? MD_NICHOS.lista : []).filter(m => m.key !== 'generico').map(m =>
          `<option value="${xe(m.key)}"${m.key === (data.template || '') ? ' selected' : ''}>${xe(m.ico + ' ' + m.nome + ' · ' + m.tag)}</option>`
        ).join('')}
      </select>
      <div class="crm-tpl-campos" id="crm-m-tpl-campos"></div>
      <div class="crm-tpl-chk" id="crm-m-tpl-chk"></div>

      <div class="crm-client-section-title"><span>03</span> ${xe(_appText('app.serviceBilling', 'Atendimento e cobrança'))}</div>

      <label class="m-lbl" for="crm-m-desc">${xe(_appText('app.descriptionOptional', 'Descrição (opcional)'))}</label>
      <textarea class="m-inp" id="crm-m-desc" rows="2" placeholder="${sanitizeAttr(_appText('app.servicePlaceholder', 'Serviço prestado, projeto, etc.'))}">${xe(data.description||'')}</textarea>

      <div class="crm-modal-row">
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-value">${xe(_appText('app.amountBrl', 'Valor (R$)'))}</label>
          <input type="number" class="crm-modal-inp" id="crm-m-value" min="0" step="0.01"
            placeholder="0,00" value="${data.value||''}">
        </div>
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-due">${xe(_appText('app.dueDate', 'Data de vencimento'))}</label>
          <input type="date" class="crm-modal-inp" id="crm-m-due" value="${data.dueDate||''}"
                 min="1900-01-01" max="2999-12-31" style="color-scheme:dark;">
        </div>
      </div>

      <!-- RECORRENCIA. So aparece em registro NOVO: transformar um contrato
           que ja existe em serie mexeria em parcelas ja pagas, e nao ha
           resposta obvia para o que fazer com elas. -->
      ${isEdit ? (data.serieId ? `<div class="crm-serie-nota">${
          xe(_appText('app.repeatPartOf', 'Parcela {n} de {total} — {como}, ate {ate}', {
            n: data.serieN || 1, total: data.serieDe || 1,
            como: _repeatLabel(data.serieTipo), ate: _crmFmtDate(data.serieAte) }))
        }</div>` : '') : `
      <div class="crm-modal-row">
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-rep">${
            xe(_appText('app.repeatLabel', 'Se repete?'))}</label>
          <select class="crm-modal-inp" id="crm-m-rep">
            ${RECORRENCIA_OPCOES.map(o => `<option value="${o.key}">${
              xe(_appText(o.i18n, o.pt))}</option>`).join('')}
          </select>
        </div>
        <div class="crm-modal-col" id="crm-m-rep-ate-col" style="display:none">
          <label class="crm-modal-lbl" for="crm-m-rep-ate">${
            xe(_appText('app.repeatUntil', 'Ate quando'))}</label>
          <input type="date" class="crm-modal-inp" id="crm-m-rep-ate"
                 min="1900-01-01" max="2999-12-31" style="color-scheme:dark;">
        </div>
      </div>
      <div class="crm-serie-nota" id="crm-m-rep-nota" style="display:none"></div>`}

      <div class="crm-client-section-title"><span>04</span> ${xe(_appText('app.addressSection', 'Endereço'))}</div>

      <label class="crm-modal-lbl" for="crm-m-cep">${xe(_appText('app.cepOptional', 'CEP (opcional)'))}</label>
      <div class="crm-lookup-row">
        <input class="m-inp" id="crm-m-cep" inputmode="numeric" maxlength="9"
          placeholder="00000-000" value="${xe(data.cep||'')}">
        <button type="button" class="crm-lookup-btn" id="crm-m-cep-btn">${xe(_appText('app.searchCep', 'Buscar CEP'))}</button>
      </div>
      <div class="crm-lookup-feedback" id="crm-m-cep-info" aria-live="polite"></div>

      <label class="crm-modal-lbl" for="crm-m-address">${xe(_appText('app.addressOptional', 'Endereço (opcional)'))}</label>
      <input class="m-inp" id="crm-m-address" maxlength="180"
        placeholder="${sanitizeAttr(_appText('app.addressPlaceholder', 'Rua, número e complemento'))}" value="${xe(data.address||'')}">

      <div class="crm-modal-row">
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-neighborhood">${xe(_appText('app.neighborhood', 'Bairro'))}</label>
          <input class="crm-modal-inp" id="crm-m-neighborhood" maxlength="100"
            placeholder="${sanitizeAttr(_appText('app.neighborhood', 'Bairro'))}" value="${xe(data.neighborhood||'')}">
        </div>
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-uf">${xe(_appText('app.state', 'Estado'))}</label>
          <select class="crm-modal-inp" id="crm-m-uf">
            <option value="">${xe(_appText('app.loadingStates', 'Carregando estados…'))}</option>
          </select>
        </div>
        <div class="crm-modal-col">
          <label class="crm-modal-lbl" for="crm-m-city">${xe(_appText('app.city', 'Município'))}</label>
          <select class="crm-modal-inp" id="crm-m-city" disabled>
            <option value="">${xe(_appText('app.selectState', 'Selecione o estado'))}</option>
          </select>
        </div>
      </div>

      <div class="crm-client-section-title"><span>05</span> ${xe(_appText('app.filesAndStatus', 'Arquivos e status'))}</div>

      <div class="crm-modal-lbl" id="crm-m-docs-label">${xe(_appText('app.documentsOptional', 'Documentos (opcional)'))}</div>
      <div class="crm-doc-list" id="crm-m-doc-list"></div>
      <label class="crm-doc-add" for="crm-m-doc-file">
        <input type="file" id="crm-m-doc-file" multiple accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx,.html">
        ${xe(_appText('app.attachDocument', '📎 Anexar documento (CPF, contrato, etc.)'))}
      </label>

      <div class="crm-modal-lbl" id="crm-m-status-label">${xe(_appText('app.paymentStatusLabel', 'Status do pagamento'))}</div>
      <div class="crm-status-select" id="crm-m-status-row" data-total="crm-m-value" role="radiogroup" aria-labelledby="crm-m-status-label">
        <div class="crm-status-opt ${initStatus==='pending'?'sel-pending':''}"
             data-status="pending" data-act="crmStatus" role="radio" aria-checked="${initStatus==='pending'}" tabindex="0">⏳ ${xe(_appText('app.statusPending', 'Pendente'))}</div>
        <div class="crm-status-opt ${initStatus==='partial'?'sel-partial':''}"
             data-status="partial" data-act="crmStatus" role="radio" aria-checked="${initStatus==='partial'}" tabindex="0">◐ ${xe(_appText('app.statusPartial', 'Parcial'))}</div>
        <div class="crm-status-opt ${initStatus==='paid'?'sel-paid':''}"
             data-status="paid" data-act="crmStatus" role="radio" aria-checked="${initStatus==='paid'}" tabindex="0">✅ ${xe(_appText('app.statusPaid', 'Pago'))}</div>
      </div>

      <!-- Só aparece em Parcial: em Pago o campo seria o valor cheio e em
           Pendente seria zero — perguntar nos dois casos é pedir um número
           que o próprio status já dá. -->
      <div id="crm-m-partial-box" data-partial-box style="${initStatus === 'partial' ? '' : 'display:none;'}margin-top:10px;">
        <label class="crm-modal-lbl" for="crm-m-paid">${xe(_appText('app.amountReceived', 'Já recebido (R$)'))}</label>
        <input type="number" class="crm-modal-inp" id="crm-m-paid" data-partial-input min="0" step="0.01"
               placeholder="0,00" value="${data.paidAmount || ''}">
        <div class="crm-partial-hint" data-partial-hint></div>
      </div>

      <div class="m-div"></div>
      <div class="m-btns">
        <button class="m-cancel" id="crm-m-cancel">${xe(_appText('app.cancel', 'Cancelar'))}</button>
        <button class="m-confirm" id="crm-m-confirm">${xe(isEdit
          ? _appText('app.save', 'Salvar')
          : _appText('app.addClientButton', 'Adicionar'))}</button>
      </div>
    </div>`;

  document.body.appendChild(bg);

  // ── Dados brasileiros: CNPJ, CEP e localidades ──
  const cpfInp = bg.querySelector('#crm-m-cpf');
  const cnpjBtn = bg.querySelector('#crm-m-cnpj-btn');
  const cnpjInfo = bg.querySelector('#crm-m-cnpj-info');
  const cepInp = bg.querySelector('#crm-m-cep');
  const cepBtn = bg.querySelector('#crm-m-cep-btn');
  const cepInfo = bg.querySelector('#crm-m-cep-info');
  const addressInp = bg.querySelector('#crm-m-address');
  const neighborhoodInp = bg.querySelector('#crm-m-neighborhood');
  const ufSelect = bg.querySelector('#crm-m-uf');
  const citySelect = bg.querySelector('#crm-m-city');
  let companyData = data.company && typeof data.company === 'object' ? data.company : null;
  let requestedCity = data.city || '';

  const setLookupInfo = (el, message, state) => {
    el.textContent = message || '';
    el.className = 'crm-lookup-feedback' + (state ? ' ' + state : '');
  };
  const loadCities = async (uf, selected) => {
    citySelect.disabled = true;
    citySelect.innerHTML = '<option value="">' +
      xe(_appText('app.loadingCities', 'Carregando municípios…')) + '</option>';
    if (!uf || !window.MyDeskBrasil) {
      citySelect.innerHTML = '<option value="">' +
        xe(_appText('app.selectState', 'Selecione o estado')) + '</option>';
      return;
    }
    try {
      const cities = await MyDeskBrasil.listarMunicipios(uf);
      citySelect.innerHTML = '<option value="">' +
        xe(_appText('app.selectCity', 'Selecione o município')) + '</option>';
      cities.forEach(city => {
        const option = document.createElement('option');
        option.value = city.nome;
        option.textContent = city.nome;
        option.selected = !!selected && city.nome.localeCompare(
          selected, _appLocale(), { sensitivity: 'base' }
        ) === 0;
        citySelect.appendChild(option);
      });
      citySelect.disabled = false;
    } catch (_) {
      citySelect.innerHTML = '<option value="">' +
        xe(_appText('app.citiesUnavailable', 'Municípios indisponíveis')) + '</option>';
    }
  };

  const statesReady = window.MyDeskBrasil
    ? MyDeskBrasil.listarEstados().then(states => {
      ufSelect.innerHTML = '<option value="">' +
        xe(_appText('app.selectState', 'Selecione o estado')) + '</option>';
      states.forEach(state => {
        const option = document.createElement('option');
        option.value = state.sigla;
        option.textContent = state.sigla + ' — ' + state.nome;
        option.selected = state.sigla === String(data.uf || '').toUpperCase();
        ufSelect.appendChild(option);
      });
      if (ufSelect.value) loadCities(ufSelect.value, requestedCity);
    }).catch(() => {
      ufSelect.innerHTML = '<option value="">' +
        xe(_appText('app.statesUnavailable', 'Estados indisponíveis')) + '</option>';
    })
    : Promise.resolve();
  ufSelect.addEventListener('change', () => {
    requestedCity = '';
    loadCities(ufSelect.value, '');
  });

  cpfInp.addEventListener('input', () => {
    cpfInp.value = _formatCpfCnpj(cpfInp.value);
    const clean = cpfInp.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (companyData && clean !== String(companyData.cnpj || '').toUpperCase()) companyData = null;
    cnpjBtn.disabled = !window.MyDeskBrasil || !MyDeskBrasil.validarCnpj(clean);
    if (clean.length < 14) setLookupInfo(cnpjInfo, '');
  });
  cpfInp.dispatchEvent(new Event('input'));

  cnpjBtn.addEventListener('click', async () => {
    cnpjBtn.disabled = true;
    cnpjBtn.textContent = _appText('app.consulting', 'Consultando…');
    setLookupInfo(cnpjInfo, _appText('app.consultingCompany',
      'Consultando dados públicos da empresa…'), 'loading');
    try {
      const company = await MyDeskBrasil.buscarCnpj(cpfInp.value);
      companyData = company;
      const companyName = company.nomeFantasia || company.razaoSocial;
      const nameInput = bg.querySelector('#crm-m-name');
      if (!nameInput.value.trim() && companyName) nameInput.value = companyName;
      if (company.cep) cepInp.value = MyDeskBrasil.formatarCep(company.cep);
      if (company.endereco) addressInp.value = company.endereco;
      if (company.bairro) neighborhoodInp.value = company.bairro;
      if (company.uf) {
        await statesReady;
        ufSelect.value = company.uf;
        requestedCity = company.cidade || '';
        await loadCities(company.uf, requestedCity);
      }
      setLookupInfo(cnpjInfo,
        [company.razaoSocial, company.situacao].filter(Boolean).join(' · ') ||
          _appText('app.companyFound', 'Empresa encontrada.'),
        'success');
    } catch (error) {
      setLookupInfo(cnpjInfo,
        error.message || _appText('app.cnpjNotFound', 'CNPJ não encontrado.'), 'error');
    } finally {
      cnpjBtn.textContent = _appText('app.checkCnpj', 'Consultar CNPJ');
      cnpjBtn.disabled = !MyDeskBrasil.validarCnpj(cpfInp.value);
    }
  });

  const consultCep = async () => {
    const clean = cepInp.value.replace(/\D/g, '');
    if (clean.length !== 8) {
      setLookupInfo(cepInfo, _appText('app.enterCepDigits',
        'Informe os 8 dígitos do CEP.'), 'error');
      return;
    }
    cepBtn.disabled = true;
    cepBtn.textContent = _appText('app.searching', 'Buscando…');
    setLookupInfo(cepInfo, _appText('app.searchingAddress',
      'Buscando endereço…'), 'loading');
    try {
      const address = await MyDeskBrasil.buscarCep(clean);
      cepInp.value = MyDeskBrasil.formatarCep(address.cep);
      if (address.logradouro) addressInp.value = address.logradouro;
      if (address.bairro) neighborhoodInp.value = address.bairro;
      if (address.uf) {
        await statesReady;
        ufSelect.value = address.uf;
        requestedCity = address.cidade || '';
        await loadCities(address.uf, requestedCity);
      }
      setLookupInfo(cepInfo,
        [address.logradouro, address.bairro, address.cidade + '/' + address.uf].filter(Boolean).join(' · '),
        'success');
    } catch (error) {
      setLookupInfo(cepInfo,
        error.message || _appText('app.cepNotFound', 'CEP não encontrado.'), 'error');
    } finally {
      cepBtn.disabled = false;
      cepBtn.textContent = _appText('app.searchCep', 'Buscar CEP');
    }
  };
  cepInp.addEventListener('input', () => {
    cepInp.value = window.MyDeskBrasil
      ? MyDeskBrasil.formatarCep(cepInp.value)
      : cepInp.value.replace(/\D/g, '').slice(0, 8);
    setLookupInfo(cepInfo, '');
  });
  cepInp.addEventListener('blur', () => {
    if (cepInp.value.replace(/\D/g, '').length === 8 && !data.cep) consultCep();
  });
  cepBtn.addEventListener('click', consultCep);
  /* Cadastro novo que já chega com CEP — o caso da resposta de formulário, que
     pergunta o CEP mas não a rua — busca o endereço sozinho. */
  if (!isEdit && data.cep && !data.address) consultCep();

  /* ── Modelo da ficha: campos e etapas que mudam com o nicho ──
     Os valores vivem em `camposAtuais` e `checklistAtual` enquanto o modal
     está aberto, e não nos próprios elementos: trocar de modelo redesenha os
     campos, e ler do DOM na hora de salvar perderia o que foi digitado antes
     da troca. Voltar ao modelo anterior traz de volta o que já estava lá. */
  const tplSel = bg.querySelector('#crm-m-template');
  const tplCampos = bg.querySelector('#crm-m-tpl-campos');
  const tplChk = bg.querySelector('#crm-m-tpl-chk');
  let camposAtuais = Object.assign({}, data.campos || {});
  let checklistAtual = Array.isArray(data.checklist)
    ? data.checklist.map(i => ({ t: i.t, ok: !!i.ok })) : [];

  const desenharModelo = () => {
    const N = window.MD_NICHOS;
    const modelo = N ? N.porChave[tplSel.value] : null;
    tplCampos.innerHTML = '';
    tplChk.innerHTML = '';
    if (!modelo) return;

    modelo.campos.forEach(c => {
      const bloco = document.createElement('div');
      bloco.className = 'crm-tpl-campo';
      const lbl = document.createElement('label');
      lbl.className = 'crm-modal-lbl';
      lbl.textContent = c.ico + ' ' + c.rot;
      bloco.appendChild(lbl);

      const linha = document.createElement('div');
      linha.className = 'crm-tpl-linha';
      const inp = document.createElement(c.tipo === 'longo' ? 'textarea' : 'input');
      inp.className = 'crm-modal-inp';
      if (c.tipo === 'data') inp.type = 'date';
      else if (c.tipo === 'valor') { inp.type = 'number'; inp.step = '0.01'; inp.min = '0'; }
      else if (c.tipo !== 'longo') inp.type = 'text';
      if (c.tipo === 'longo') inp.rows = 2;
      inp.maxLength = c.tipo === 'longo' ? 600 : 160;
      inp.value = camposAtuais[c.k] || '';
      inp.addEventListener('input', () => {
        camposAtuais[c.k] = inp.value;
        // O campo Vaga carrega um vínculo junto do texto — ver sincronizarVagaId.
        if (c.k === 'vaga') sincronizarVagaId(camposAtuais, inp.value);
      });
      linha.appendChild(inp);

      if (c.selo) {
        const sel = document.createElement('select');
        sel.className = 'crm-modal-inp crm-tpl-selo';
        sel.innerHTML = '<option value="">sem etiqueta</option>' +
          c.selo.map(o => `<option value="${xe(o)}"${camposAtuais[c.k + '__selo'] === o ? ' selected' : ''}>${xe(o)}</option>`).join('');
        sel.addEventListener('change', () => { camposAtuais[c.k + '__selo'] = sel.value; });
        linha.appendChild(sel);
      }
      bloco.appendChild(linha);
      tplCampos.appendChild(bloco);
    });

    // As etapas vêm do modelo na primeira vez e depois são do usuário: trocar
    // de modelo não apaga o que ele já marcou ou reescreveu.
    if (!checklistAtual.length && N) checklistAtual = N.checklistInicial(modelo.key);

    const cab = document.createElement('div');
    cab.className = 'crm-modal-lbl';
    cab.textContent = 'Etapas do acompanhamento';
    tplChk.appendChild(cab);

    const lista = document.createElement('div');
    lista.className = 'crm-tpl-chk-lista';
    tplChk.appendChild(lista);

    const redesenharChk = () => {
      lista.innerHTML = '';
      checklistAtual.forEach((item, i) => {
        const li = document.createElement('div');
        li.className = 'crm-tpl-chk-item' + (item.ok ? ' feito' : '');
        const box = document.createElement('button');
        box.type = 'button';
        box.className = 'crm-tpl-chk-box';
        box.textContent = item.ok ? '✓' : '';
        box.addEventListener('click', () => { item.ok = !item.ok; redesenharChk(); });
        const txt = document.createElement('input');
        txt.className = 'crm-tpl-chk-txt';
        txt.value = item.t || '';
        txt.maxLength = 120;
        txt.addEventListener('input', () => { item.t = txt.value; });
        const del = document.createElement('button');
        del.type = 'button';
        del.className = 'crm-tpl-chk-del';
        del.textContent = '✕';
        del.title = 'Remover etapa';
        del.addEventListener('click', () => { checklistAtual.splice(i, 1); redesenharChk(); });
        li.appendChild(box); li.appendChild(txt); li.appendChild(del);
        lista.appendChild(li);
      });
    };

    const add = document.createElement('button');
    add.type = 'button';
    add.className = 'crm-tpl-chk-add';
    add.textContent = '+ Etapa';
    add.addEventListener('click', () => { checklistAtual.push({ t: '', ok: false }); redesenharChk(); });
    tplChk.appendChild(add);
    redesenharChk();
  };

  tplSel.addEventListener('change', desenharModelo);

  /* Palpite pelo texto, só em ficha NOVA e sem modelo escolhido: quem escreve
     "audiência" provavelmente quer o modelo de advocacia. Trocar sozinho o
     modelo de uma ficha existente seria mexer no trabalho alheio. */
  if (!isEdit && !tplSel.value && window.MD_NICHOS) {
    const palpite = MD_NICHOS.sugerir([data.name, data.description].filter(Boolean).join(' '));
    if (palpite) tplSel.value = palpite;
  }
  desenharModelo();

  // ── Documentos anexados (em memória até salvar) ──
  let pendingDocs = (data.documents || []).slice();
  const docListEl = bg.querySelector('#crm-m-doc-list');
  const renderDocList = () => {
    docListEl.innerHTML = pendingDocs.map((d, i) => `
      <div class="crm-doc-item" data-i="${i}">
        <span class="crm-doc-name" title="${sanitizeAttr(_appText('app.clickToView', 'Clique para visualizar'))}">📄 ${xe(d.name)}</span>
        <span class="crm-doc-size">${((d.size||0)/1024).toFixed(0)}KB</span>
        <button type="button" class="crm-doc-del" title="${sanitizeAttr(_appText('app.remove', 'Remover'))}">${iX}</button>
      </div>`).join('');
    docListEl.querySelectorAll('.crm-doc-name').forEach(el => {
      el.addEventListener('click', () => viewDocumentFile(pendingDocs[Number(el.closest('.crm-doc-item').dataset.i)]));
    });
    docListEl.querySelectorAll('.crm-doc-del').forEach(btn => {
      btn.addEventListener('click', () => {
        pendingDocs.splice(Number(btn.closest('.crm-doc-item').dataset.i), 1);
        renderDocList();
      });
    });
  };
  renderDocList();

  bg.querySelector('#crm-m-doc-file').addEventListener('change', async function() {
    for (const f of Array.from(this.files)) {
      const veredito = podeSubirArquivo(f);
      if (!veredito.ok) {
        toast('⚠', veredito.motivo);
        if (veredito.oferecerPremium && typeof showPremiumModal === 'function') showPremiumModal();
        continue;
      }
      if (!safeFileType(f)) { avisarArquivoRecusado(f); continue; }
      const dataUrl = await new Promise((ok, fail) => {
        const fr = new FileReader();
        fr.onload = () => ok(fr.result);
        fr.onerror = fail;
        fr.readAsDataURL(f);
      });
      // Mesmo porteiro da nota: compacta se não couber, recusa se nem assim.
      const pronto = await prepararAnexo(f.name, f.type, f.size, dataUrl);
      if (!pronto.ok) { toast('⚠', pronto.motivo); continue; }
      if (pronto.arquivo.gz) {
        toast('🗜️', _appText('app.fileZipped',
          '"{name}" foi compactado de {from} para {to}. Para abrir, baixe o arquivo.',
          { name: f.name, from: fmtBytes(f.size), to: fmtBytes(pronto.arquivo.sizeGz) }));
      }
      pendingDocs.push(pronto.arquivo);
    }
    this.value = '';
    renderDocList();
  });

  bg.querySelector('#crm-m-cancel').onclick = () => bg.remove();
  bg.addEventListener('click', e => { if (e.target === bg) bg.remove(); });
  bg.querySelectorAll('.crm-status-opt').forEach(option => {
    option.addEventListener('keydown', event => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      selectCRMStatus(option, option.dataset.status);
    });
  });

  /* ── Foto da pessoa ────────────────────────────────────────────────────
     Reduz para 128px e grava como JPEG. A foto vai em base64 dentro do
     registro, e uma foto de celular sem tratar levaria megabytes para
     desenhar um círculo de 34 pixels — o mesmo custo de download que
     passamos a semana cortando. */
  /* A foto vem do IndexedDB. `data.photo` so aparece em registro antigo,
     de quando ela morava no banco — nesse caso ela e adotada e some do
     banco no proximo salvamento. */
  let _fotoAtual = data.photo || '';
  if (rec && rec.id) {
    fotoDoRegistro(rec.id).then(url => {
      if (!url || _fotoAtual) return;
      _fotoAtual = url;
      _pintarFoto();
    });
  }
  const _fotoAlvo = bg.querySelector('#crm-m-foto-alvo');
  const _fotoInp  = bg.querySelector('#crm-m-foto');

  const _pintarFoto = () => {
    if (!_fotoAlvo) return;
    /* RAW, e nao safePhotoUrl: a URL vai para a PROPRIEDADE .src, que nao
       desescapa nada. safePhotoUrl ja aplica sanitizeAttr, que troca "=" por
       "&#x3D;" — e o padding do base64 termina em "=". Escapada, ela chega
       ao navegador com o texto "&#x3D;" no lugar do "=" e a imagem quebra.
       Escape so vale para quem escreve no ATRIBUTO. */
    const url = safePhotoUrlRaw(_fotoAtual);
    _fotoAlvo.innerHTML = url
      ? '<img alt="">'
      : '<span class="crm-foto-vazia">' + xe(_appText('app.photo', 'Foto')) + '</span>';
    if (url) _fotoAlvo.querySelector('img').src = url;
    _fotoAlvo.appendChild(_fotoInp);
  };
  _pintarFoto();

  _fotoAlvo?.addEventListener('click', () => _fotoInp.click());
  _fotoAlvo?.addEventListener('keydown', ev => {
    if (ev.key !== 'Enter' && ev.key !== ' ') return;
    ev.preventDefault(); _fotoInp.click();
  });
  bg.querySelector('#crm-m-foto-tirar')?.addEventListener('click', () => {
    _fotoAtual = ''; _pintarFoto();
  });

  _fotoInp?.addEventListener('change', () => {
    const arq = _fotoInp.files && _fotoInp.files[0];
    if (!arq) return;
    if (!/^image\//.test(arq.type)) {
      toast('⚠', _appText('app.photoNeedsImage', 'Escolha um arquivo de imagem.'));
      return;
    }
    const leitor = new FileReader();
    leitor.onload = () => {
      const img = new Image();
      img.onload = () => {
        /* Recorte quadrado a partir do centro: a foto vira um círculo, e
           esticar um retrato para caber deformaria o rosto. */
        const lado = Math.min(img.width, img.height);
        const cv = document.createElement('canvas');
        cv.width = cv.height = 128;
        const ctx = cv.getContext('2d');
        ctx.drawImage(img, (img.width - lado) / 2, (img.height - lado) / 2,
                      lado, lado, 0, 0, 128, 128);
        _fotoAtual = cv.toDataURL('image/jpeg', 0.82);
        _pintarFoto();
      };
      img.onerror = () => toast('⚠', _appText('app.photoUnreadable',
        'Não consegui ler essa imagem.'));
      img.src = leitor.result;
    };
    leitor.readAsDataURL(arq);
  });

  /* O "falta receber" acompanha os DOIS campos: mudar o total sem recalcular
     deixaria na tela uma conta que já não fecha. */
  /* A PREVIA DIZ QUANTAS PARCELAS VAO NASCER, antes de nascerem. Sem ela, a
     pessoa escolhe "todo mes ate dezembro" e descobre o resultado quando doze
     linhas aparecem na tabela — e aí ja e trabalho apagar. */
  const repSel = bg.querySelector('#crm-m-rep');
  if (repSel) {
    const repAteCol = bg.querySelector('#crm-m-rep-ate-col');
    const repAte = bg.querySelector('#crm-m-rep-ate');
    const repNota = bg.querySelector('#crm-m-rep-nota');
    const repRepintar = () => {
      const tipo = repSel.value;
      repAteCol.style.display = tipo ? '' : 'none';
      if (!tipo) { repNota.style.display = 'none'; return; }
      const inicio = bg.querySelector('#crm-m-due').value;
      const fim = repAte.value;
      repNota.style.display = '';
      if (!inicio) {
        repNota.textContent = _appText('app.repeatNeedsDue',
          'Informe a data de vencimento acima: e dela que sai a primeira parcela.');
        return;
      }
      if (!fim) {
        repNota.textContent = _appText('app.repeatNeedsUntil',
          'Informe ate quando o contrato vai.');
        return;
      }
      const n = _crmContarParcelas(inicio, fim, tipo);
      repNota.textContent = n < 2
        ? _appText('app.repeatTooShort',
            'Neste intervalo cabe uma parcela so — nao ha o que repetir.')
        : _appText('app.repeatWillCreate',
            '{n} parcelas de {valor}, de {de} ate {ate}.', {
              n, valor: fmtBRL(parseFloat(bg.querySelector('#crm-m-value').value) || 0),
              de: _crmFmtDate(inicio),
              ate: _crmFmtDate(_crmSomarPeriodo(inicio, tipo, n - 1)) });
    };
    repSel.addEventListener('change', repRepintar);
    repAte.addEventListener('change', repRepintar);
    bg.querySelector('#crm-m-due').addEventListener('change', repRepintar);
    bg.querySelector('#crm-m-value').addEventListener('input', repRepintar);
  }

  ['#crm-m-value', '#crm-m-paid'].forEach(sel => {
    bg.querySelector(sel)?.addEventListener('input', _crmAtualizarDicaParcial);
  });
  _crmAtualizarDicaParcial();

  bg.querySelector('#crm-m-confirm').onclick = async () => {
    const name  = bg.querySelector('#crm-m-name').value.trim();
    const email = bg.querySelector('#crm-m-email').value.trim();
    const phone = bg.querySelector('#crm-m-phone').value.trim();
    const desc  = bg.querySelector('#crm-m-desc').value.trim();
    const value = parseFloat(bg.querySelector('#crm-m-value').value) || 0;
    const due   = bg.querySelector('#crm-m-due').value;
    const cpf   = cpfInp.value.trim();
    const birthDate = bg.querySelector('#crm-m-birth').value;
    const education = bg.querySelector('#crm-m-education').value;
    const maritalStatus = bg.querySelector('#crm-m-marital').value;
    const cep   = cepInp.value.trim();
    const address = addressInp.value.trim();
    const neighborhood = neighborhoodInp.value.trim();
    const city  = citySelect.value;
    const uf    = ufSelect.value;
    const statusEl = bg.querySelector(
      '.crm-status-opt.sel-paid, .crm-status-opt.sel-pending, .crm-status-opt.sel-partial');
    /* Normaliza aqui, uma vez, em vez de espalhar a regra: parcial de zero é
       pendente, parcial que cobre o total é pago. */
    const pagamento = _crmNormalizarPagamento({
      value,
      status: statusEl ? statusEl.dataset.status : 'pending',
      paidAmount: parseFloat(bg.querySelector('#crm-m-paid')?.value) || 0,
    });
    const status     = pagamento.status;
    const paidAmount = pagamento.paidAmount;

    if (!name) {
      bg.querySelector('#crm-m-name').style.borderColor = 'var(--clr-danger)';
      bg.querySelector('#crm-m-name').focus();
      return;
    }

    const emailEl = bg.querySelector('#crm-m-email');
    if (email && !emailEl.checkValidity()) {
      emailEl.style.borderColor = 'var(--clr-danger)';
      emailEl.focus();
      toast('⚠', _appText('app.checkClientEmail',
        'Confira o e-mail do cliente.'));
      return;
    }

    const documentClean = cpf.toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (documentClean && !window.MyDeskBrasil) {
      cpfInp.style.borderColor = 'var(--clr-danger)';
      cpfInp.focus();
      toast('⚠', _appText('app.brazilValidationUnavailable',
        'A validação brasileira está temporariamente indisponível. Recarregue a página.'));
      return;
    }
    if (documentClean) {
      const validDocument = /^\d{11}$/.test(documentClean)
        ? MyDeskBrasil.validarCpf(documentClean)
        : MyDeskBrasil.validarCnpj(documentClean);
      if (!validDocument) {
        cpfInp.style.borderColor = 'var(--clr-danger)';
        cpfInp.focus();
        toast('⚠', _appText('app.checkCpfCnpj',
          'Confira o CPF ou CNPJ informado.'));
        return;
      }
    }

    const birthEl = bg.querySelector('#crm-m-birth');
    if (birthDate && !birthEl.checkValidity()) {
      birthEl.style.borderColor = 'var(--clr-danger)';
      birthEl.focus();
      toast('⚠', _appText('app.checkBirthDate',
        'Confira a data de nascimento.'));
      return;
    }

    // Ano incompleto (ex.: 0022, digitado sem terminar) não vira vencimento.
    if (due && !/^(19|2\d)\d{2}-/.test(due)) {
      const dueEl = bg.querySelector('#crm-m-due');
      dueEl.style.borderColor = 'var(--clr-danger)';
      dueEl.focus();
      toast('⚠', _appText('app.checkDueYear',
        'Confira o ano do vencimento.'));
      return;
    }

    const btn = bg.querySelector('#crm-m-confirm');
    btn.textContent = _appText('app.saving', 'Salvando…'); btn.disabled = true;

    let saved = null;
    if (isEdit) {
      saved = await updateRecord(rec.id, {
        name, email, phone, description: desc, value, dueDate: due, status, paidAmount, cpf,
        // No banco vai so o marcador; a imagem fica no navegador.
        photo: '', photoLocal: !!_fotoAtual,
        /* Tirar a foto tem de FICAR tirada. Sem apagar este marcador, a foto
           que veio na resposta do formulário seria buscada de novo no próximo
           desenho do cartão e voltaria sozinha, sem nada na tela explicando. */
        fotoResposta: _fotoAtual ? !!(rec && rec.fotoResposta) : false,
        birthDate, education, maritalStatus, cep, address, neighborhood,
        city, uf, company: companyData, documents: pendingDocs,
        template: tplSel.value, campos: camposAtuais,
        checklist: checklistAtual.filter(i => (i.t || '').trim())
      });
      if (saved) toast('✅', _appText('app.clientUpdated', 'Cliente atualizado!'));
    } else {
      saved = await createRecord({
        name, email, phone, description: desc, value, status, paidAmount, dueDate: due, cpf,
        photo: '', photoLocal: !!_fotoAtual,
        birthDate, education, maritalStatus, cep, address, neighborhood,
        city, uf, company: companyData, documents: pendingDocs,
        template: tplSel.value, campos: camposAtuais,
        checklist: checklistAtual.filter(i => (i.t || '').trim())
      });
    }
    /* A imagem vai para o navegador, e nao para o banco. Depois de salvar,
       para so gravar foto de registro que existe de fato. */
    if (saved && saved.id) {
      if (_fotoAtual) await _fotoSalvar(saved.id, _fotoAtual);
      else            await _fotoApagar(saved.id);
      /* E REPINTA AGORA. Só limpar as marcas não bastava: o funil já tinha
         sido redesenhado pelo ouvinte do banco ANTES de a imagem chegar ao
         IndexedDB, e ninguém passava de novo pelos cartões — a foto só
         aparecia na próxima carga da página. Quem acabou de escolher a foto
         precisa vê-la no cartão, não depois de um F5. */
      if (typeof pintarFotosDosCartoes === 'function') {
        document.querySelectorAll('.rh-card .rh-card-av').forEach(
          av => { delete av.dataset.fotoFeita; });
        pintarFotosDosCartoes();
      }
    }

    if (saved) {
      /* As parcelas nascem DEPOIS de a primeira existir, e a partir dela: a
         primeira e o registro que a pessoa acabou de preencher, e recria-la
         aqui seria manter dois lugares montando a mesma coisa. */
      const repTipo = repSel ? repSel.value : '';
      const repFim = repSel ? bg.querySelector('#crm-m-rep-ate').value : '';
      if (!isEdit && repTipo && repFim && saved.dueDate) {
        const criadas = await _crmGerarParcelas(saved, repTipo, repFim);
        if (criadas) {
          toast('🔁', _appText('app.repeatCreated',
            '{n} parcelas criadas.', { n: criadas + 1 }));
        }
      }
      bg.remove();
      if (typeof aoSalvar === 'function') { try { await aoSalvar(saved); } catch (_) {} }
    } else {
      btn.textContent = isEdit
        ? _appText('app.save', 'Salvar')
        : _appText('app.addClientButton', 'Adicionar');
      btn.disabled = false;
    }
  };

  // Focus on name
  setTimeout(() => bg.querySelector('#crm-m-name')?.focus(), 80);
}

/* Serve os DOIS formulários de cliente — o completo e o de criação rápida.
   Eles compartilham a classe .crm-status-select; ancorar num id só faria a
   opção nova funcionar em um e falhar calada no outro. */
function selectCRMStatus(el, status) {
  const row = el.closest('.crm-status-select');
  if (!row) return;
  row.querySelectorAll('.crm-status-opt').forEach(o => {
    o.classList.remove('sel-paid', 'sel-pending', 'sel-partial');
    o.setAttribute('aria-checked', 'false');
  });
  el.classList.add(
    status === 'paid' ? 'sel-paid' : status === 'partial' ? 'sel-partial' : 'sel-pending'
  );
  el.setAttribute('aria-checked', 'true');

  const caixa = row.parentElement?.querySelector('[data-partial-box]');
  if (caixa) caixa.style.display = status === 'partial' ? '' : 'none';
  _crmAtualizarDicaParcial(row);
}

/* Lê o status escolhido em qualquer um dos dois formulários. */
function _crmStatusEscolhido(row) {
  const sel = row?.querySelector(
    '.crm-status-opt.sel-paid, .crm-status-opt.sel-partial, .crm-status-opt.sel-pending');
  return sel ? sel.dataset.status : 'pending';
}

/* A conta que a pessoa quer enxergar enquanto digita: quanto ainda falta.
   Também avisa, ANTES de salvar, quando o número escolhido vai mudar o
   status — 0 volta para Pendente e o total vira Pago. Descobrir isso só
   depois de gravar pareceria que o app ignorou a escolha. */
function _crmAtualizarDicaParcial(row) {
  const linha  = row || document.querySelector('.crm-status-select');
  const escopo = linha?.parentElement;
  const dica   = escopo?.querySelector('[data-partial-hint]');
  if (!dica) return;

  const total = parseFloat(document.getElementById(linha.dataset.total)?.value) || 0;
  const pago  = parseFloat(escopo.querySelector('[data-partial-input]')?.value) || 0;

  const diz = (texto, tipo) => {
    dica.textContent = texto;
    tipo ? dica.setAttribute('data-s', tipo) : dica.removeAttribute('data-s');
  };

  if (total <= 0) {
    return diz(_appText('app.partialNeedsTotal', 'Informe o valor total acima.'), 'warn');
  }
  if (pago <= 0) {
    return diz(_appText('app.partialNeedsAmount',
      'Sem valor recebido, será salvo como Pendente.'), 'warn');
  }
  if (pago >= total) {
    return diz(_appText('app.partialBecomesPaid',
      'Cobre o total — será salvo como Pago.'), 'warn');
  }
  diz(_appText('app.partialRemaining', 'Falta receber {valor}',
    { valor: fmtBRL(total - pago) }), 'ok');
}

/* ─────────────────────────────────────────────
   BOTÃO "CONVERTER EM CLIENTE" nas notas
   Injetado pelo mountNote hook
───────────────────────────────────────────── */
/* ─────────────────────────────────────────────
   BOTÃO CONVERTER — aparece APENAS em notas de cliente
   Notas pessoais NÃO têm botão converter
───────────────────────────────────────────── */
function injectConvertButton(noteEl, noteId) {
  // Notas pessoais não têm opção de converter → sai imediatamente
  const n = notes.find(n => n.id === noteId);
  if (!n || n._isClientNote) return; // cliente já tem bloco próprio, não precisa de botão

  // Evita duplicação
  if (noteEl.querySelector('.n-convert-btn')) return;

  const chipRow = noteEl.querySelector('.n-chip-row');
  if (!chipRow) return;

  const btn = document.createElement('button');
  btn.className = 'n-convert-btn' + (n._crmRecordId ? ' converted' : '');
  btn.textContent = n._crmRecordId ? '✓ Em Clientes' : '💼 → Cliente';
  btn.title = 'Converter esta nota em registro de cliente';

  if (!n._crmRecordId) {
    btn.onclick = (e) => {
      e.stopPropagation();
      convertNoteToRecord(noteId);
    };
  }

  const delBtn = chipRow.querySelector('.n-del');
  if (delBtn) chipRow.insertBefore(btn, delBtn);
  else chipRow.appendChild(btn);
}

/* ─────────────────────────────────────────────
   addNote — cria nota no board sem verificação de plano
   Usado por createClientNote (que já verificou o limite)
───────────────────────────────────────────── */
function addNote(data) {
  const W = window.innerWidth, H = window.innerHeight, TB = 54;
  const x = data.x !== undefined ? data.x : 80  + Math.random() * Math.max(W - 420, 80);
  const y = data.y !== undefined ? data.y : TB + 40 + Math.random() * Math.max(H - TB - 320, 80);
  const n = Object.assign({
    id: Date.now(), color: selClr, title: '', body: '',
    start: '', end: '', reminder: false, remDays: 3,
    status: 'todo', x, y, z: _proximoZ(), files: [],
    _isClientNote: false, _crmRecordId: null
  }, data, { x, y, z: _proximoZ() });
  notes.push(_marcarBoard(n));
  mountNote(n);
  saveNotes();
  syncCount();
  return n;
}
window.addEventListener('load', function crmInit() {

  // ── Wire up client note form submit ──
  const mcOk = document.getElementById('mc-ok');
  if (mcOk) mcOk.addEventListener('click', createClientNote);

  // ── Wire up modal backdrop click ──
  const modalBg = document.getElementById('modal');
  if (modalBg) {
    modalBg.addEventListener('click', e => {
      if (e.target === modalBg) closeModal();
    });
  }

  // ── Patch mountNote ──
  const origMount = window.mountNote;
  if (typeof origMount === 'function') {
    window.mountNote = function(n) {
      // Não montar registros CRM puros como notas no board
      if (n && (n.type === 'client' || String(n.id || '').startsWith('crm_'))) return;
      // Nem o formulário da vaga: ele mora na aba de recrutamento.
      if (_formEhDeVaga(n)) return;
      origMount.call(this, n);
      requestAnimationFrame(() => {
        const el = document.querySelector('.note[data-id="' + n.id + '"]');
        if (!el) return;
        if (n._isClientNote) {
          // Nota de cliente: mostra extras (valor/status), SEM botão converter
          mountClientNoteExtras(el, n.id);
        } else {
          // Nota pessoal: pode ter botão converter (para quem quiser migrar)
          // REMOVIDO conforme solicitado — notas pessoais não têm opção CRM
          // injectConvertButton(el, n.id);
        }
      });
    };
  }

  // ── Patch launchApp ──
  const origLaunch = window.launchApp;
  if (typeof origLaunch === 'function') {
    window.launchApp = async function() {
      await origLaunch.apply(this, arguments);

      // Remover do array `notes` qualquer registro CRM puro
      if (Array.isArray(notes)) {
        for (let i = notes.length - 1; i >= 0; i--) {
          const n = notes[i];
          if (n.type === 'client' || String(n.id || '').startsWith('crm_')) {
            document.querySelector('.note[data-id="' + n.id + '"]')?.remove();
            notes.splice(i, 1);
          }
        }
      }

      // Montar extras nas notas de cliente
      setTimeout(() => {
        if (Array.isArray(notes)) {
          notes.forEach(n => {
            const el = document.querySelector('.note[data-id="' + n.id + '"]');
            if (!el) return;
            if (n._isClientNote) {
              mountClientNoteExtras(el, n.id);
            }
            // Notas pessoais não recebem mais botão converter
          });
        }
        // Carregar registros CRM sempre (para blocos de notas de cliente no board)
        loadRecords();
      }, 500);
    };
  }

  // ── Patch doLogout ──
  const origLogout = window.doLogout;
  if (typeof origLogout === 'function') {
    window.doLogout = function() {
      if (typeof isInCall === 'function' && isInCall()) leaveCall();
      _crmDetachListener();
      _records = [];
      _crmMode = false;
      const btn   = document.getElementById('btn-crm-view');
      const label = document.getElementById('crm-view-label');
      const crmBd = document.getElementById('crm-board');
      const crmDs = document.getElementById('crm-dashboard');
      const crmCh = document.getElementById('crm-charts-row');
      if (btn)   btn.classList.remove('active');
      if (label) label.textContent = _crmRotuloDoPainel();
      const crmVw = document.getElementById('crm-view');
      if (crmVw) crmVw.classList.remove('visible');
      if (crmBd) crmBd.classList.remove('visible');
      if (crmDs) crmDs.classList.remove('visible');
      if (crmCh) crmCh.classList.remove('visible');
      origLogout.apply(this, arguments);
    };
  }
});

/* ===========================================================================
   PAINEL ADMINISTRATIVO -- agora em /admin/
   ===========================================================================
   Ele vivia aqui dentro, como uma sobreposicao montada por cima do quadro de
   notas: cerca de 400 linhas que so rodavam para administrador e que todo
   usuario comum baixava junto com o app. Virou uma pagina propria, com folha
   de estilo e script proprios, em docs/admin/.

   Nada se perdeu no caminho: a leitura de dados e as chamadas de API foram
   reescritas em admin/admin.js, e as rotas continuam sendo as mesmas
   (set-admin, set-plan e a nova admin-users). A seguranca nunca esteve nesta
   camada -- ela vive nas regras do banco e na conferencia da claim dentro de
   cada endpoint.

   Este atalho permanece porque o botao da barra de ferramentas chama por ele.
   A checagem local evita mandar um usuario comum para uma pagina que so lhe
   mostraria "acesso restrito"; a autorizacao de verdade e refeita na /admin/. */
function openAdminPanel() {
  if (!window.authState?.isAdmin) {
    toast('\u{1F6AB}', 'Acesso restrito a administradores.');
    return;
  }
  window.location.href = 'admin/';
}


/* ═══════════════════════════════════════════════════════════════════
   CONVIDE AMIGOS (programa de indicação)
   ═══════════════════════════════════════════════════════════════════
   O código de indicação é o próprio @ do usuário — não precisa gerar nem
   guardar código extra. Quem chega pelo link cria a conta normalmente e o
   login.js grava a aresta em referrals/{codigo}/{uidNovo}.

   O resgate é manual de propósito: liberar Premium automático a partir de
   um contador alimentado pelo próprio cliente seria convite à fraude
   (bastaria criar contas). Automatizar exige validação no servidor.
   ═══════════════════════════════════════════════════════════════════ */
const INVITE_META  = 3;                                        // amigos por recompensa
const INVITE_EMAIL = 'mydesksocial@hotmail.com';

/* O link cai direto no cadastro. Ele apontava para landing.html: quem clicava
   chegava na página de vendas e ainda precisava caçar o botão de criar conta —
   e quem vem por indicação já foi convencido pelo amigo, a venda está feita.
   login.html sem parâmetro abre justamente no formulário de criar conta.

   A base agora sai de location em vez de estar escrita à mão. O endereço fixo
   apontava para a publicação antiga no github.io, que hoje só responde 301
   para mydesk.social — um salto a mais, e um link que envelhece de novo no
   próximo domínio. Assim ele nasce sempre no endereço em que o app está.

   O ?ref= é lido pelo analytics.js, que está carregado no login.html e guarda
   o código por 30 dias; o login.js grava a indicação quando a conta é criada. */
function inviteLink() {
  const base = location.origin + location.pathname.replace(/[^/]*$/, '');
  return base + 'login.html?ref=' + encodeURIComponent(CU?.username || '');
}

async function openInvitePanel() {
  if (!CU?.username) { toast('⚠', _appText('app.loginToInvite', 'Faça login para convidar amigos.')); return; }
  if (window.mdTrack) mdTrack('convite_painel_open');

  const link = inviteLink();
  const msg  = 'Tô usando o MyDesk pra organizar minhas notas e meus clientes — dá uma olhada: ' + link;

  const bg = document.createElement('div');
  bg.className = 'invite-modal-bg';
  bg.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.72);backdrop-filter:blur(6px);' +
    'display:flex;align-items:center;justify-content:center;z-index:9999;padding:20px;';

  bg.innerHTML =
    '<div style="background:#14141c;border:1px solid rgba(255,255,255,.1);border-radius:20px;max-width:460px;' +
    'width:100%;padding:28px;box-shadow:0 30px 80px rgba(0,0,0,.6);font-family:Inter,sans-serif;">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">' +
        '<h3 style="margin:0;font-family:Syne,sans-serif;font-size:1.25rem;color:#f5f5f7;">Convide amigos 💜</h3>' +
        '<button id="inv-close" style="background:none;border:none;color:#94a3b8;font-size:1.4rem;cursor:pointer;line-height:1;">&times;</button>' +
      '</div>' +
      '<p style="margin:0 0 20px;font-size:.85rem;color:rgba(245,245,247,.6);line-height:1.6;">' +
        'A cada <b style="color:#a5b4fc;">' + INVITE_META + ' amigos</b> que criarem conta pelo seu link, ' +
        'você ganha <b style="color:#a5b4fc;">30 dias de Premium</b>. Eles entram direto no plano gratuito — ' +
        'ninguém precisa pagar nada para começar.' +
      '</p>' +
      '<label style="display:block;font-size:.72rem;text-transform:uppercase;letter-spacing:1px;' +
             'color:rgba(245,245,247,.36);margin-bottom:7px;">Seu link</label>' +
      '<div style="display:flex;gap:8px;margin-bottom:14px;">' +
        '<input id="inv-link" readonly value="' + link + '" ' +
               'style="flex:1;min-width:0;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);' +
               'border-radius:10px;padding:11px 13px;font-size:.78rem;color:#f5f5f7;font-family:inherit;">' +
        '<button id="inv-copy" style="background:#fff;color:#0a0a0a;border:none;border-radius:10px;padding:11px 16px;' +
               'font-size:.82rem;font-weight:700;cursor:pointer;font-family:inherit;">Copiar</button>' +
      '</div>' +
      '<div style="display:flex;gap:8px;margin-bottom:22px;">' +
        '<a id="inv-wa" target="_blank" rel="noopener" ' +
           'style="flex:1;text-align:center;background:linear-gradient(135deg,#25d366,#128c7e);color:#fff;' +
           'border-radius:10px;padding:11px;font-size:.82rem;font-weight:600;text-decoration:none;">Enviar no WhatsApp</a>' +
        '<button id="inv-share" style="flex:1;background:rgba(255,255,255,.07);color:#fff;border:1px solid rgba(255,255,255,.12);' +
           'border-radius:10px;padding:11px;font-size:.82rem;font-weight:600;cursor:pointer;font-family:inherit;">Compartilhar…</button>' +
      '</div>' +
      '<div style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:16px;">' +
        '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:9px;">' +
          '<span style="font-size:.82rem;color:rgba(245,245,247,.68);">Amigos que criaram conta</span>' +
          '<b id="inv-count" style="font-family:Syne,sans-serif;font-size:1.2rem;color:#f5f5f7;">…</b>' +
        '</div>' +
        '<div style="height:8px;border-radius:6px;background:rgba(255,255,255,.08);overflow:hidden;">' +
          '<div id="inv-bar" style="height:100%;width:0;border-radius:6px;transition:width .8s cubic-bezier(.16,1,.3,1);' +
               'background:linear-gradient(90deg,#6366f1,#a5b4fc);"></div>' +
        '</div>' +
        '<div id="inv-hint" style="margin-top:10px;font-size:.76rem;color:rgba(245,245,247,.42);"></div>' +
        '<button id="inv-claim" style="display:none;width:100%;margin-top:12px;background:linear-gradient(135deg,#6366f1,#4f46e5);' +
               'color:#fff;border:none;border-radius:10px;padding:11px;font-size:.84rem;font-weight:700;' +
               'cursor:pointer;font-family:inherit;">Resgatar 30 dias de Premium</button>' +
      '</div>' +
    '</div>';

  document.body.appendChild(bg);

  const close = () => bg.remove();
  bg.querySelector('#inv-close').addEventListener('click', close);
  bg.addEventListener('click', e => { if (e.target === bg) close(); });

  bg.querySelector('#inv-wa').href = 'https://wa.me/?text=' + encodeURIComponent(msg);

  bg.querySelector('#inv-copy').addEventListener('click', async () => {
    const btn = bg.querySelector('#inv-copy');
    try {
      await navigator.clipboard.writeText(link);
    } catch (_) {
      const el = bg.querySelector('#inv-link'); el.select(); document.execCommand('copy');
    }
    btn.textContent = 'Copiado!';
    setTimeout(() => { btn.textContent = 'Copiar'; }, 1800);
    if (window.mdTrack) mdTrack('convite_link_copiado');
  });

  bg.querySelector('#inv-share').addEventListener('click', () => {
    if (navigator.share) navigator.share({ title: 'MyDesk', text: msg, url: link }).catch(() => {});
    else bg.querySelector('#inv-copy').click();
    if (window.mdTrack) mdTrack('convite_compartilhar');
  });

  // Contagem de indicações — só o dono do código consegue ler esse nó.
  let total = 0;
  try {
    const list = await fbGet('referrals/' + CU.username);
    total = list ? Object.keys(list).length : 0;
  } catch (e) {
    console.warn('[convite] não foi possível ler referrals:', e && e.message ? e.message : e);
  }

  const premios  = Math.floor(total / INVITE_META);
  const noCiclo  = total % INVITE_META;
  const faltam   = INVITE_META - noCiclo;
  bg.querySelector('#inv-count').textContent = total;
  bg.querySelector('#inv-bar').style.width = (noCiclo / INVITE_META * 100) + '%';
  bg.querySelector('#inv-hint').textContent = total === 0
    ? 'Nenhum ainda — mande o link para quem vive perdendo prazo. 😉'
    : (premios > 0
        ? 'Você já tem ' + premios + ' recompensa' + (premios > 1 ? 's' : '') + ' para resgatar!'
        : 'Falta' + (faltam > 1 ? 'm ' : ' ') + faltam + ' para os seus 30 dias de Premium.');

  if (premios > 0) {
    const claim = bg.querySelector('#inv-claim');
    claim.style.display = 'block';
    claim.addEventListener('click', () => {
      if (window.mdTrack) mdTrack('convite_resgate', { premios });
      const assunto = 'Resgate de indicação — @' + CU.username;
      const corpo   = 'Olá! Indiquei ' + total + ' amigo(s) pelo meu link e gostaria de resgatar ' +
                      premios + ' x 30 dias de Premium.\n\nMeu @: ' + CU.username;
      window.open('mailto:' + INVITE_EMAIL + '?subject=' + encodeURIComponent(assunto) +
                  '&body=' + encodeURIComponent(corpo), '_blank');
    });
  }
}

/* ═══════════════════════════════════════════════════════════════════
   DELEGAÇÃO DE CLIQUES — HTML gerado em tempo de execução
   Estes botões usavam onclick="..." dentro de template string. Atributo
   inline é justamente o que uma Content-Security-Policy sem 'unsafe-inline'
   bloqueia — e é o formato que um XSS armazenado usaria para executar código.
   Agora cada um declara data-act e um único listener no documento despacha.
   ═══════════════════════════════════════════════════════════════════ */
const MD_ACOES = {
  removeExpense: el      => removeExpense(el.dataset.id),
  tileFocus:     el      => _toggleTileFocus(el.closest('.call-tile')?.dataset.key),
  leaveGroupWs:  ()      => leaveGroupWorkspace(true),
  editRecord:    (el, ev) => { ev.stopPropagation(); openEditRecordModal(el.dataset.id); },
  crmStatusMenu: el      => crmMenuDeStatus(el, el.dataset.id),
  crmStatusSerie: el     => crmMenuDeStatusDaSerie(el, el.dataset.id),
  exportCard:    el      => exportClientCard(el.dataset.id),
  delRecord:     el      => confirmDeleteRecord(el.dataset.id),
  crmStatus:     el      => selectCRMStatus(el, el.dataset.status),
  crmPeriodo:    el      => crmTrocarPeriodo(el),
  crmFiltrar:    el      => crmAbrirFiltro(el),
  crmOrdenar:    el      => crmAbrirOrdenacao(el),
  crmAcoesLinha: (el, ev) => { ev.stopPropagation(); crmAbrirAcoesLinha(el); },
  // adminReload / adminClose saíram junto com a sobreposição do painel: os
  // botões que os disparavam viviam no HTML dela, que agora é /admin/.
};

document.addEventListener('click', ev => {
  const el = ev.target.closest('[data-act]');
  if (!el) return;
  const fn = MD_ACOES[el.dataset.act];
  if (fn) fn(el, ev);
});

/* Enter e Espaço em quem se anuncia como botão. Sem isto, `role="button"` com
   tabindex entrega o foco pelo teclado e o acionamento não faz nada — foco
   sem ação é uma promessa que a tela não cumpre, pior do que não ser
   focável. Vale para qualquer data-act, não só para o selo de status. */
document.addEventListener('keydown', ev => {
  if (ev.key !== 'Enter' && ev.key !== ' ') return;
  const el = ev.target?.closest?.('[data-act][role="button"]');
  if (!el) return;
  const fn = MD_ACOES[el.dataset.act];
  if (!fn) return;
  ev.preventDefault();
  fn(el, ev);
});

/* ═══════════════════════════════════════════════════════════════════
   AVISOS DO PERÍODO DE TESTE
   Um na primeira entrada da conta nova ("tem 7 dias com tudo liberado")
   e outro quando o prazo acaba. Cada um aparece uma única vez por conta —
   a marca fica no localStorage, porque é preferência de exibição e não
   deve custar escrita no banco (nem virar campo que o usuário reescreve).
   ═══════════════════════════════════════════════════════════════════ */
function _trialMarcado(chave) {
  try { return localStorage.getItem('md_' + chave + '_' + (CU?.uid || '')) === '1'; }
  catch (_) { return false; }
}
function _trialMarcar(chave) {
  try { localStorage.setItem('md_' + chave + '_' + (CU?.uid || ''), '1'); } catch (_) {}
}

function _trialModal({ emoji, titulo, corpo, botao, aoConfirmar, secundario }) {
  document.querySelector('.trial-modal-bg')?.remove();

  const bg = document.createElement('div');
  bg.className = 'trial-modal-bg';
  bg.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.72);backdrop-filter:blur(6px);' +
    'display:flex;align-items:center;justify-content:center;z-index:9998;padding:20px;';

  bg.innerHTML =
    '<div style="background:#14141c;border:1px solid rgba(255,255,255,.1);border-radius:20px;max-width:440px;' +
    'width:100%;padding:30px 28px;box-shadow:0 30px 80px rgba(0,0,0,.6);font-family:Inter,sans-serif;text-align:center;">' +
      '<div style="font-size:2.6rem;line-height:1;margin-bottom:14px;">' + emoji + '</div>' +
      '<h3 style="margin:0 0 12px;font-family:Syne,sans-serif;font-size:1.35rem;color:#f5f5f7;">' + titulo + '</h3>' +
      '<div style="font-size:.87rem;color:rgba(245,245,247,.66);line-height:1.65;margin-bottom:24px;">' + corpo + '</div>' +
      '<button id="trial-ok" style="width:100%;background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff;' +
        'border:none;border-radius:11px;padding:13px;font-size:.9rem;font-weight:700;cursor:pointer;' +
        'font-family:inherit;box-shadow:0 6px 22px rgba(99,102,241,.35);">' + botao + '</button>' +
      (secundario ? '<button id="trial-depois" style="width:100%;margin-top:9px;background:none;border:none;' +
        'color:rgba(245,245,247,.42);font-size:.8rem;cursor:pointer;font-family:inherit;padding:8px;">' +
        secundario + '</button>' : '') +
    '</div>';

  document.body.appendChild(bg);
  const fechar = () => bg.remove();
  bg.querySelector('#trial-ok').addEventListener('click', () => { fechar(); if (aoConfirmar) aoConfirmar(); });
  bg.querySelector('#trial-depois')?.addEventListener('click', fechar);
  bg.addEventListener('click', e => { if (e.target === bg) fechar(); });
}

/* Chamado depois que o plano carrega. Decide qual aviso (se algum) mostrar. */
function checarPeriodoDeTeste() {
  if (!CU?.uid || window.authState?.isAdmin) return;
  if (isPremium()) return;

  const fim = _trialFimMs();
  if (!fim) return;   // sem data de criação (sessão demo) — nada a fazer

  if (isInTrial()) {
    if (_trialMarcado('trial_ini')) return;
    _trialMarcar('trial_ini');
    if (window.mdTrack) mdTrack('trial_inicio');
    const dias = trialDiasRestantes();
    _trialModal({
      emoji: '🎁',
      titulo: 'Seus ' + TRIAL_DIAS + ' dias começaram!',
      corpo: 'Até <b style="color:#a5b4fc;">' + new Date(fim).toLocaleDateString(_appLocale()) +
             '</b> você usa o MyDesk inteiro, sem limite: notas ilimitadas, CRM Financeiro, ' +
             'workspaces de grupo — tudo liberado.<br><br>' +
             'Passados os ' + TRIAL_DIAS + ' dias, esses recursos voltam a ser exclusivos do Premium ' +
             'e será preciso assinar para continuar usando. Suas notas não somem: ficam todas aqui.',
      botao: 'Aproveitar meus ' + dias + (dias === 1 ? ' dia' : ' dias'),
    });
    return;
  }

  // Fora do teste e sem assinatura: acabou. Avisa uma vez.
  if (Date.now() >= fim && !_trialMarcado('trial_fim')) {
    _trialMarcar('trial_fim');
    if (window.mdTrack) mdTrack('trial_fim');
    _trialModal({
      emoji: '⏳',
      titulo: 'Seu teste de ' + TRIAL_DIAS + ' dias terminou',
      corpo: 'A partir de agora, o CRM Financeiro e os workspaces de grupo pedem Premium, ' +
             'e a criação de notas volta ao limite de ' + PLAN_FREE_LIMIT + ' por mês.<br><br>' +
             '<b style="color:#a5b4fc;">Nada foi apagado</b> — tudo o que você criou continua aí. ' +
             'São R$ 19,99 por mês ou R$ 199,99 por ano em uma assinatura segura pela Stripe, ' +
             'com gerenciamento e cancelamento pelo Portal do Cliente.',
      botao: 'Assinar Premium',
      secundario: 'Continuar no plano gratuito',
      aoConfirmar: () => { if (typeof showPremiumModal === 'function') showPremiumModal(); },
    });
  }
}


/* ═══════════════════════════════════════════════════════════════════
   RESPOSTAS DE FORMULÁRIO → FICHA DO CLIENTE
   ═══════════════════════════════════════════════════════════════════
   O formulário já pergunta CPF, nascimento, CEP, município — os mesmos
   campos que a ficha do cliente guarda. Sem esta ponte a pessoa lia a
   resposta na nota e redigitava tudo no cadastro.

   Duas saídas, porque são dois casos diferentes: quem respondeu é gente
   nova (vira cliente, com o cadastro já preenchido para conferir antes
   de salvar) ou é cliente que já existe (a resposta se ANEXA à ficha).
   No anexo, campo que já tem valor nunca é sobrescrito — quem preencheu
   o formulário pode ter errado o próprio telefone, e o dado conferido
   por quem usa o app vale mais que o que chegou de fora. O que sempre
   acumula são as anotações e os arquivos, que são histórico. */
const CRM_MAPA_FORM = {
  email: 'email', telefone: 'phone', cpf: 'cpf', cnpj: 'cpf',
  nascimento: 'birthDate', escolaridade: 'education', estado_civil: 'maritalStatus',
  cep: 'cep', estado: 'uf', municipio: 'city',
};
const CRM_ROTULO_FICHA = {
  name: 'Nome', email: 'E-mail', phone: 'Telefone', cpf: 'CPF/CNPJ',
  birthDate: 'Nascimento', education: 'Escolaridade', maritalStatus: 'Estado civil',
  cep: 'CEP', city: 'Município', uf: 'Estado',
};
const CRM_CAMPOS_FICHA = Object.keys(CRM_ROTULO_FICHA);

/* Traduz uma resposta para o vocabulário da ficha. O que não tem lugar no
   cadastro (texto longo, seleção, data solta) não se perde: vira anotação. */
function _crmDadosDaResposta(campos, resp, tituloForm, nicho) {
  const valores = resp.valores || {};
  const preenchido = c => String(valores[c.id] == null ? '' : valores[c.id]).trim();
  const dados = {}, anotacoes = [];

  /* Formulário montado a partir de um modelo de nicho: cada campo criado por
     ele carrega a chave da ficha no id (prefixo n_), então o que o cliente
     preencheu entra direto no campo certo — que é o ponto de ligar as duas
     coisas. A ficha nasce já com o modelo e com as etapas do trabalho. */
  const modelo = (window.MD_NICHOS && nicho) ? MD_NICHOS.porChave[nicho] : null;
  if (modelo) {
    dados.template = modelo.key;
    dados.campos = {};
    dados.checklist = MD_NICHOS.checklistInicial(modelo.key);
    modelo.campos.forEach(c => {
      const bruto = valores['n_' + c.k];
      const v = String(bruto == null ? '' : bruto).trim();
      if (!v) return;
      // Campo com etiqueta: o que o cliente escolheu É a etiqueta de estado.
      if (c.selo && c.selo.includes(v)) dados.campos[c.k + '__selo'] = v;
      else dados.campos[c.k] = v;
    });
  }

  /* O nome do cliente é o único campo que o formulário não marca com um tipo
     próprio: sai de um "texto curto". Prefere o que o rótulo indica ser nome;
     não havendo, o primeiro texto curto — que é onde ele costuma estar. */
  const textos = (campos || []).filter(c => c.tipo === 'texto' && preenchido(c));
  const campoNome = textos.find(c => /nome|cliente|raz[ãa]o\s*social|empresa/i.test(c.rotulo || ''))
                 || textos[0] || null;

  (campos || []).forEach(c => {
    const v = preenchido(c);
    if (!v) return;
    if (modelo && String(c.id).startsWith('n_')) return;   // já foi para a ficha
    if (campoNome && c.id === campoNome.id) { dados.name = v.slice(0, 120); return; }
    const destino = CRM_MAPA_FORM[c.tipo];
    if (destino && !dados[destino]) {
      dados[destino] = destino === 'uf' ? v.toUpperCase() : v;
      return;
    }
    // Segundo e-mail, segundo telefone, texto livre: a ficha só tem uma casa
    // para cada um, então o excedente é registrado em vez de descartado.
    anotacoes.push((c.rotulo || c.id) + ': ' + v);
  });

  const quando = resp.ts ? new Date(resp.ts).toLocaleDateString('pt-BR') : '';
  /* Procedência sempre no fim. O travessão só entra quando há linha antes: a
     descrição aparece resumida na tabela de clientes, e "— via formulário…"
     abrindo a linha ficava com cara de texto cortado. */
  const procedencia = 'via formulário "' + (tituloForm || 'sem título') + '"' + (quando ? ' em ' + quando : '');
  anotacoes.push((anotacoes.length ? '— ' : '') + procedencia);
  dados.description = anotacoes.join('\n');

  if (resp.arquivo && resp.arquivo.dataUrl) {
    dados.documents = [{
      name: resp.arquivo.name || 'anexo do formulário',
      size: Math.round(String(resp.arquivo.dataUrl).length * 0.75),
      type: resp.arquivo.type || '',
      dataUrl: resp.arquivo.dataUrl,
    }];
  }
  /* A foto entra pelo mesmo campo que o cadastro já usa para adotar imagem
     antiga: o modal a mostra e, ao salvar, ela vai para o IndexedDB e não
     para o banco (`photo: ''` + `photoLocal`). Nenhum caminho novo. */
  if (typeof resp.foto === 'string' && resp.foto) dados.photo = resp.foto;
  return dados;
}

/* Marca a resposta com o cliente que recebeu os dados, para a próxima abertura
   mostrar "já foi para a ficha de fulano". Falhar aqui não desfaz a importação:
   a ficha já foi gravada, e a marca é só memória da tela. */
function _crmMarcarRespostaImportada(formId, rid, rec) {
  if (!formId || !rid || !rec) return Promise.resolve();
  return fbSet('forms/' + formId + '/respostas/' + rid + '/crm',
               { rec: rec.id, nome: String(rec.name || '').slice(0, 120), ts: Date.now() })
    .catch(() => {});
}

async function _crmAnexarResposta(formId, resp, dados, recId) {
  const rec = _records.find(r => r.id === recId);
  if (!rec) { toast('⚠', _appText('app.clientNotInList', 'Esse cliente não está mais na lista.')); return; }

  const mudancas = {}, preenchidos = [];
  CRM_CAMPOS_FICHA.forEach(k => {
    if (!dados[k]) return;
    if (String(rec[k] == null ? '' : rec[k]).trim()) return;   // já tem: não mexe
    mudancas[k] = dados[k];
    preenchidos.push(CRM_ROTULO_FICHA[k]);
  });
  if (dados.description) {
    mudancas.description = [String(rec.description || '').trim(), dados.description]
      .filter(Boolean).join('\n\n');
  }
  if (dados.documents && dados.documents.length) {
    mudancas.documents = (rec.documents || []).concat(dados.documents);
  }

  const salvo = await updateRecord(recId, mudancas);
  if (!salvo) return;
  await _crmMarcarRespostaImportada(formId, resp.rid, rec);
  toast('📎', preenchidos.length
    ? 'Anexado a ' + rec.name + ' · ' + preenchidos.join(', ')
    : 'Anexado a ' + rec.name + ' · anotações e anexos (os campos já tinham dado).');
  if (typeof renderRecordsTable === 'function') renderRecordsTable();
}

function abrirImportarRespostasCRM() {
  if (!CU || !_fbReady) { toast('⚠', 'Entre na sua conta para trazer respostas.'); return; }

  const formularios = (typeof notes !== 'undefined' ? notes : [])
    .filter(n => n._isFormNote && n._formId)
    .map(n => ({ id: n._formId, titulo: n.title || 'Formulário' }));

  document.querySelector('.fr-bg')?.remove();
  const bg = document.createElement('div');
  bg.className = 'fr-bg';
  bg.dataset.importar = '1';
  bg.innerHTML = `
    <div class="fr-card">
      <div class="fr-cab">
        <div class="fr-tit">Respostas para a ficha do cliente</div>
        <button class="fr-x" title="Fechar">✕</button>
      </div>
      <div class="fr-corpo">
        <select class="fr-sel fr-sel-form" id="fi-form">
          ${formularios.map(f => `<option value="${xe(f.id)}">${xe(f.titulo)}</option>`).join('')}
        </select>
        <div id="fi-lista"></div>
      </div>
    </div>`;
  document.body.appendChild(bg);

  const fechar = () => bg.remove();
  bg.querySelector('.fr-x').addEventListener('click', fechar);
  bg.addEventListener('click', e => { if (e.target === bg) fechar(); });
  document.addEventListener('keydown', function esc(e) {
    if (e.key === 'Escape') { document.removeEventListener('keydown', esc); fechar(); }
  });

  const seletor = bg.querySelector('#fi-form');
  if (!formularios.length) {
    seletor.remove();
    bg.querySelector('#fi-lista').innerHTML =
      '<div class="fr-vazio">Nenhum formulário neste quadro.<br>' +
      'Crie um em <b>Nova nota → Formulário</b>, envie o link e as respostas aparecem aqui ' +
      'prontas para virar cliente.</div>';
    return;
  }
  seletor.addEventListener('change', () => _fiPintar(bg, seletor.value));
  _fiPintar(bg, seletor.value);
}

async function _fiPintar(bg, formId) {
  const lista = bg.querySelector('#fi-lista');
  const titulo = bg.querySelector('#fi-form')?.selectedOptions[0]?.textContent || _appText('app.formDefaultTitle', 'Formulário');
  lista.innerHTML = '<div class="fr-vazio">Carregando respostas…</div>';

  let form = null;
  try { form = await fbGet('forms/' + formId); } catch (_) {}
  if (bg.querySelector('#fi-form')?.value !== formId) return;   // trocou enquanto carregava
  if (!form) {
    lista.innerHTML = '<div class="fr-vazio">' + xe(_appText('app.formReadError', 'Não consegui ler este formulário.')) + '</div>';
    return;
  }

  const campos = form.campos || [];
  const itens = Object.keys(form.respostas || {})
    .map(rid => Object.assign({ rid }, form.respostas[rid]))
    .sort((a, b) => (b.ts || 0) - (a.ts || 0));

  lista.innerHTML = '';
  if (!itens.length) {
    lista.innerHTML = '<div class="fr-vazio">' + xe(_appText('app.formNoResponsesYet', 'Este formulário ainda não recebeu respostas.')) + '</div>';
    return;
  }

  itens.forEach(resp => {
    const dados = _crmDadosDaResposta(campos, resp, titulo, form.nicho);
    const cartao = document.createElement('div');
    cartao.className = 'fr-item';

    const cab = document.createElement('div');
    cab.className = 'fr-item-cab';
    cab.textContent = resp.ts
      ? new Date(resp.ts).toLocaleString('pt-BR', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' })
      : 'sem data';
    if (resp.crm && resp.crm.nome) {
      const marca = document.createElement('span');
      marca.className = 'fi-marca';
      marca.textContent = _appText('app.alreadySentTo', 'já foi para {name}', { name: resp.crm.nome });
      cab.appendChild(marca);
    }
    cartao.appendChild(cab);

    // A prévia mostra a ficha COMO VAI FICAR, não a resposta crua: é isso que a
    // pessoa precisa conferir antes de mandar para o cadastro.
    const tabela = document.createElement('div');
    tabela.className = 'fr-tabela';
    const linha = (rot, val) => {
      if (!val) return;
      const l = document.createElement('div');
      l.className = 'fr-linha';
      const k = document.createElement('span');
      k.className = 'fr-k'; k.textContent = rot;
      const v = document.createElement('span');
      v.className = 'fr-v'; v.textContent = val;   // texto de quem respondeu, sem conta
      l.appendChild(k); l.appendChild(v);
      tabela.appendChild(l);
    };
    CRM_CAMPOS_FICHA.forEach(k => linha(CRM_ROTULO_FICHA[k], dados[k]));
    linha('Anotações', dados.description);
    if (dados.documents) linha('Anexo', dados.documents[0].name);
    cartao.appendChild(tabela);

    const acoes = document.createElement('div');
    acoes.className = 'fr-acoes';

    const novo = document.createElement('button');
    novo.className = 'fr-b';
    novo.textContent = 'Criar cliente';
    novo.addEventListener('click', () => {
      // Abre o cadastro preenchido em vez de gravar direto: valor e vencimento
      // não vêm do formulário, e é a hora de conferir o que chegou de fora. A
      // marca só entra se o cadastro for mesmo salvo — cancelar não importa nada.
      _openRecordModal(null, dados, async criado => {
        await _crmMarcarRespostaImportada(formId, resp.rid, criado);
        _fiPintar(bg, formId);
      });
    });
    acoes.appendChild(novo);

    const alvo = document.createElement('select');
    alvo.className = 'fr-sel';
    alvo.innerHTML = '<option value="">Anexar a um cliente…</option>' +
      _records.map(r => `<option value="${xe(r.id)}">${xe(r.name || 'sem nome')}</option>`).join('');
    acoes.appendChild(alvo);

    const anexar = document.createElement('button');
    anexar.className = 'fr-b';
    anexar.textContent = 'Anexar';
    anexar.disabled = true;
    alvo.addEventListener('change', () => { anexar.disabled = !alvo.value; });
    anexar.addEventListener('click', async () => {
      anexar.disabled = true;
      anexar.textContent = 'Anexando…';
      await _crmAnexarResposta(formId, resp, dados, alvo.value);
      anexar.textContent = 'Anexar';
      _fiPintar(bg, formId);
    });
    acoes.appendChild(anexar);

    cartao.appendChild(acoes);
    lista.appendChild(cartao);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('crm-btn-respostas')?.addEventListener('click', abrirImportarRespostasCRM);
});


/* ═══════════════════════════════════════════════════════════════════
   RELATÓRIO FINANCEIRO — números
   ═══════════════════════════════════════════════════════════════════
   Uma função só calcula tudo, e a tela e o PDF consomem o mesmo
   resultado — senão os dois versões do mesmo relatório divergem. */
function _relatorioDados() {
  const hoje = new Date();
  const atrasadoQ = r => r.status !== 'paid' && r.dueDate && new Date(r.dueDate + 'T23:59:59') < hoje;

  const financeiros = _registrosFinanceiros();
  /* Cada registro é dividido entre o que entrou e o que falta — um parcial
     de 300 num contrato de 1.000 soma 300 em pago e 700 no lado que ainda
     deve. Jogar o valor cheio num balde só, como antes, inflava um dos dois
     e fazia a taxa de recebimento mentir. */
  let pago = 0, pendente = 0, atrasado = 0, nAtraso = 0;
  financeiros.forEach(r => {
    const recebido = _crmRecebido(r);
    const falta    = _crmAReceber(r);
    pago += recebido;
    if (falta > 0) {
      if (atrasadoQ(r)) { atrasado += falta; nAtraso++; }
      else pendente += falta;
    }
  });
  const total = pago + pendente + atrasado;

  const meses = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(hoje.getFullYear(), hoje.getMonth() - i, 1);
    meses.push({
      chave: d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'),
      // "Fev 2026" — o formato com ano junto vira "fev. de 2026" em pt-BR, e o
      // "de" no meio ficava capitalizado ("Fev De 2026") na tabela.
      rotulo: d.toLocaleDateString(_appLocale(), { month: 'short' }).replace(/\.$/, '')
                .replace(/^./, c => c.toUpperCase()) + ' ' + d.getFullYear(),
      total: 0, pago: 0,
    });
  }
  financeiros.forEach(r => {
    const m = meses.find(x => x.chave === _crmRecMonth(r));
    if (!m) return;
    m.total += Number(r.value) || 0;
    m.pago  += _crmRecebido(r);
  });
  const maiorMes = Math.max(1, ...meses.map(m => m.total));

  const ordenados = [...financeiros].sort((a, b) => (Number(b.value) || 0) - (Number(a.value) || 0));
  const maior = ordenados[0] || null;

  return {
    hoje, atrasadoQ, pago, pendente, atrasado, total, nAtraso, meses, maiorMes, ordenados, maior,
    taxa: total ? pago / total : 0,
    ticket: financeiros.length ? total / financeiros.length : 0,
    referencia: 'MD-' + hoje.toISOString().slice(0, 10).replace(/-/g, '') + '-' +
                String(financeiros.length).padStart(3, '0'),
  };
}

/* Cores de estado. Passaram no validador de paleta (separação sob daltonismo
   e piso de croma); o amarelo fica abaixo de 3:1 no branco, e por isso todo
   segmento carrega rótulo visível — cor nunca é o único sinal. */
const REL_COR = {
  pago:     '#0F7A52',
  // Verde-azulado: parente do verde de "pago" porque parte do dinheiro entrou,
  // e distinto o bastante para nao se confundir com ele numa impressao P&B.
  parcial:  '#0E7490',
  pendente: '#C98A04',
  atraso:   '#B3261E',
  barra:    '#4F46E5',
  tinta:    '#14141C',
  fraca:    '#6B6B7B',
  linha:    '#E4E4EA',
};

/* ═══════════════════════════════════════════════════════════════════
   RELATÓRIO NA TELA
   ═══════════════════════════════════════════════════════════════════ */
function abrirRelatorioCRM() {
  if (!hasFullAccess()) {
    toast('⭐', _appText('app.reportPremiumOnly', 'O relatório financeiro é exclusivo do Premium.'));
    if (typeof showPremiumModal === 'function') showPremiumModal();
    return;
  }
  if (!_records.length) { toast('ℹ️', _appText('app.addClientsFirst', 'Cadastre clientes antes de gerar o relatório.')); return; }

  /* No modelo de recrutamento a folha é outra: funil, vagas e candidatos, em
     vez de recebido e a receber. Sai por impressão — o gerador de PDF próprio
     é escrito à mão para o layout financeiro. */
  if (crmModeloRH()) {
    if (!MD_RH.candidatos(_records).length) {
      toast('ℹ️', _appText('rh.addCandidatesFirst',
        'Cadastre candidatos antes de gerar o relatório.'));
      return;
    }
    MD_RH.relatorio(_records);
    return;
  }

  const d = _relatorioDados();
  const pct = v => d.total ? (v / d.total * 100) : 0;
  const fmtPct = v => pct(v).toFixed(pct(v) >= 10 ? 0 : 1).replace('.', ',') + '%';

  // Barra de composição: os três estados em uma linha, com 2px de folga
  // entre os pedaços e rótulo em cada um.
  const segmentos = [
    { k: 'pago',     rot: 'Recebido',  v: d.pago },
    { k: 'pendente', rot: 'A receber', v: d.pendente },
    { k: 'atraso',   rot: 'Atrasado',  v: d.atrasado },
  ].filter(s => s.v > 0);

  const host = document.getElementById('crm-relatorio');
  host.innerHTML = `
    <div class="rel-folha">
      <header class="rel-masthead">
        <div>
          <div class="rel-eyebrow">Relatório financeiro</div>
          <h1>${xe(CU?.name || CU?.username || '')}</h1>
          <div class="rel-meta">
            <span>${d.hoje.toLocaleDateString(_appLocale(), { day: '2-digit', month: 'long', year: 'numeric' })}</span>
            <span>${d.ordenados.length} ${d.ordenados.length === 1 ? 'cliente' : 'clientes'}</span>
            <span class="rel-ref">${d.referencia}</span>
          </div>
        </div>
        <div class="rel-logo">MyDesk</div>
      </header>

      <section class="rel-hero">
        <div class="rel-hero-rot">Total em carteira</div>
        <div class="rel-hero-num">${fmtBRL(d.total)}</div>

        <div class="rel-comp" role="img" aria-label="Composição da carteira">
          ${segmentos.map(s => `<span class="rel-comp-seg s-${s.k}" style="flex:${s.v}"></span>`).join('')}
        </div>
        <div class="rel-comp-leg">
          ${segmentos.map(s => `
            <div class="rel-comp-item">
              <i class="s-${s.k}"></i>
              <b>${s.rot}</b>
              <span>${fmtBRL(s.v)} · ${fmtPct(s.v)}</span>
            </div>`).join('')}
        </div>
      </section>

      <section class="rel-kpis">
        <div class="rel-kpi"><span>Taxa de recebimento</span><b>${(d.taxa * 100).toFixed(0)}%</b></div>
        <div class="rel-kpi"><span>Ticket médio</span><b>${fmtBRL(d.ticket)}</b></div>
        <div class="rel-kpi"><span>Maior cliente</span><b>${d.maior ? xe(d.maior.name || '—') : '—'}</b>
          <em>${d.maior ? fmtBRL(Number(d.maior.value) || 0) : ''}</em></div>
        <div class="rel-kpi ${d.nAtraso ? 'alerta' : ''}"><span>Em atraso</span><b>${d.nAtraso}</b>
          <em>${d.nAtraso ? fmtBRL(d.atrasado) : 'nenhum'}</em></div>
      </section>

      <section>
        <h2>Últimos seis meses</h2>
        <table class="rel-tab">
          <thead><tr>
            <th>Mês</th><th class="rel-w">Volume</th>
            <th class="num">Previsto</th><th class="num">Recebido</th><th class="num">A receber</th>
          </tr></thead>
          <tbody>
            ${d.meses.map(m => `<tr>
              <td class="rel-mes">${xe(m.rotulo)}</td>
              <td class="rel-w">${m.total > 0
                ? `<span class="rel-minibar" style="width:${(m.total / d.maiorMes * 100).toFixed(1)}%"></span>`
                : ''}</td>
              <td class="num">${fmtBRL(m.total)}</td>
              <td class="num">${fmtBRL(m.pago)}</td>
              <td class="num">${fmtBRL(m.total - m.pago)}</td>
            </tr>`).join('')}
          </tbody>
          <tfoot><tr>
            <td colspan="2">Total do período</td>
            <td class="num">${fmtBRL(d.meses.reduce((a, m) => a + m.total, 0))}</td>
            <td class="num">${fmtBRL(d.meses.reduce((a, m) => a + m.pago, 0))}</td>
            <td class="num">${fmtBRL(d.meses.reduce((a, m) => a + m.total - m.pago, 0))}</td>
          </tr></tfoot>
        </table>
      </section>

      <section>
        <h2>Clientes <span class="rel-cont">${d.ordenados.length}</span></h2>
        <table class="rel-tab rel-zebra">
          <thead><tr>
            <th>Cliente</th><th>Status</th><th>Vencimento</th><th class="num">Valor</th>
          </tr></thead>
          <tbody>
            ${d.ordenados.map(r => {
              const pago2 = r.status === 'paid', atras = d.atrasadoQ(r);
              const parc  = r.status === 'partial';
              const k = pago2 ? 'pago' : atras ? 'atraso' : parc ? 'parcial' : 'pendente';
              const rot = pago2 ? 'Pago' : atras ? 'Atrasado' : parc ? 'Parcial' : 'Pendente';
              return `<tr>
                <td>${xe(r.name || '—')}${r.description ? `<em>${xe(String(r.description).slice(0, 46))}</em>` : ''}${
                  parc ? `<em>recebido ${xe(fmtBRL(_crmRecebido(r)))} · falta ${xe(fmtBRL(_crmAReceber(r)))}</em>` : ''}</td>
                <td><span class="rel-pill s-${k}">${rot}</span></td>
                <td class="rel-venc">${r.dueDate ? xe(_crmFmtDate(r.dueDate)) : '—'}</td>
                <td class="num">${fmtBRL(Number(r.value) || 0)}</td>
              </tr>`;
            }).join('')}
          </tbody>
          <tfoot><tr><td colspan="3">Total</td><td class="num">${fmtBRL(d.total)}</td></tr></tfoot>
        </table>
      </section>

      <footer class="rel-rodape">
        <span>Documento gerado automaticamente pelo MyDesk</span>
        <span>${d.hoje.toLocaleString(_appLocale())} · ${d.referencia}</span>
      </footer>

      <!-- As ações ficam DENTRO da folha, no fim do documento. Como barra
           sobreposta na base da tela, elas cobriam uma linha da tabela de
           clientes enquanto se rolava — e, numa captura de página inteira,
           ficavam atravessadas no meio do relatório. Aqui não cobrem nada:
           são o fim do documento, e quem chega ao fim já leu o resto. -->
      <div class="rel-acoes">
        <button id="rel-imprimir">${xe(_appText('app.print', 'Imprimir'))}</button>
        <!-- O PowerPoint fica ao lado do PDF, e nao dentro de um menu: sao
             dois documentos para duas situacoes — o PDF se arquiva e se
             anexa, a apresentacao vai para a reuniao e la alguem vai querer
             apagar um slide ou trocar a cor de uma barra. -->
        <button id="rel-pptx">${xe(_appText('app.downloadPptx', 'Baixar PowerPoint'))}</button>
        <button id="rel-pdf" class="primario">${xe(_appText('app.downloadPdf', 'Baixar PDF'))}</button>
      </div>
    </div>

    <!-- Fechar continua ao alcance a qualquer momento, mas como botão pequeno
         no canto, sobre o fundo escurecido — fora da folha, sem tapar texto. -->
    <button class="rel-x" id="rel-fechar" title="${sanitizeAttr(_appText('app.closeEsc', 'Fechar (Esc)'))}" aria-label="${sanitizeAttr(_appText('app.closeReport', 'Fechar relatório'))}">✕</button>`;

  host.classList.add('aberto');
  const fechar = () => host.classList.remove('aberto');
  host.querySelector('#rel-fechar').addEventListener('click', fechar);
  document.addEventListener('keydown', function esc(e) {
    if (e.key === 'Escape') { document.removeEventListener('keydown', esc); fechar(); }
  });
  host.querySelector('#rel-imprimir').addEventListener('click', () => window.print());
  host.querySelector('#rel-pdf').addEventListener('click', () => baixarRelatorioCRMemPDF());
  host.querySelector('#rel-pptx').addEventListener('click', () => baixarRelatorioCRMemPPTX());
  if (window.mdTrack) mdTrack('crm_relatorio_aberto', { clientes: _records.length });
}

document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('crm-btn-relatorio')?.addEventListener('click', abrirRelatorioCRM);
  document.getElementById('crm-btn-fluxo')?.addEventListener('click', crmAbrirFluxo);
  document.getElementById('crm-btn-despesas')?.addEventListener('click', crmAbrirDespesas);
  document.getElementById('crm-btn-google-sheets')?.addEventListener('click', exportClientsToGoogleSheets);
});


/* ═══════════════════════════════════════════════════════════════════
   LEMBRETES POR E-MAIL (Premium) — só o interruptor mora aqui
   ═══════════════════════════════════════════════════════════════════
   Quem manda o e-mail é o cron diário em api/reminders.js. O app só grava
   a preferência em users/{uid}/private/notif, que apenas o dono lê e
   escreve — o servidor lê pela service account na hora de enviar. */
let _prefLembrete = { email: false, diasAntes: 3 };

async function carregarPrefLembrete() {
  if (!_fbReady || !CU?.uid) return;
  try {
    const p = await fbGet('users/' + CU.uid + '/private/notif');
    _prefLembrete = { email: !!(p && p.email), diasAntes: (p && p.diasAntes) || 3 };
  } catch (_) { /* sem permissão ou offline: fica no padrão */ }
  _pintarPrefLembrete();

  /* A agenda e a preferência chegam por caminhos independentes, e a ordem entre
     elas não é garantida. Quando a agenda vencia a corrida, o app ainda não
     sabia que os lembretes estavam ligados e pulava a fila — o compromisso era
     salvo e nenhum aviso era agendado. Por isso a sincronização é disparada
     também aqui, do lado que só termina depois de conhecer a preferência. */
  if (_prefLembrete.email) {
    if (!(_agenda || []).length) await _carregarAgenda();
    _sincronizarFilaLembretes();
  }
}

function _pintarPrefLembrete() {
  const sw  = document.getElementById('ev-lembrete-sw');
  const sub = document.getElementById('ev-lembrete-sub');
  if (!sw) return;
  const ligado = _prefLembrete.email && hasFullAccess();
  sw.classList.toggle('on', ligado);
  sw.setAttribute('aria-checked', ligado ? 'true' : 'false');
  if (sub) {
    // O texto tem de descrever o que o servidor faz de verdade. Prometer seis
    // avisos e entregar um é pior do que não prometer nada.
    // O texto tem de descrever o que o servidor faz de verdade. Prometer seis
    // avisos e entregar dois é pior do que não prometer nada.
    sub.textContent = !hasFullAccess()
      ? 'E-mail um dia antes e no dia do compromisso · Premium'
      : ligado
        ? 'Ligado · e-mail um dia antes e no dia do compromisso'
        : 'Desligado · ligue para receber os avisos por e-mail';
  }
}

async function alternarPrefLembrete() {
  if (!hasFullAccess()) {
    toast('⭐', _appText('app.remindersPremiumOnly', 'Lembretes por e-mail são exclusivos do Premium.'));
    if (typeof showPremiumModal === 'function') showPremiumModal();
    return;
  }
  if (!_fbReady || !CU?.uid) { toast('⚠', 'Entre na sua conta para configurar.'); return; }

  _prefLembrete.email = !_prefLembrete.email;
  _pintarPrefLembrete();
  try {
    await fbUpdate('users/' + CU.uid + '/private/notif', {
      email: _prefLembrete.email,
      diasAntes: _prefLembrete.diasAntes,
    });
    // Ligar recria a fila com o que ainda está por vir; desligar marca tudo.
    if (_prefLembrete.email) await _sincronizarFilaLembretes(true);
    else await _marcarFilaLembretes(false);
    toast(_prefLembrete.email ? '📬' : '🔕',
      _prefLembrete.email ? 'Você receberá os lembretes por e-mail.' : 'Lembretes por e-mail desligados.');
    if (window.mdTrack) mdTrack('lembrete_email', { ligado: _prefLembrete.email ? 1 : 0 });
  } catch (e) {
    _prefLembrete.email = !_prefLembrete.email;   // desfaz na tela se não gravou
    _pintarPrefLembrete();
    toast('⚠', _appText('app.savePreferenceError', 'Não foi possível salvar a preferência.'));
  }
}

document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('ev-lembrete-sw')?.addEventListener('click', alternarPrefLembrete);
});

/* ═══════════════════════════════════════════════════════════════════
   GERADOR DE PDF — mínimo, sem biblioteca
   ═══════════════════════════════════════════════════════════════════
   PDF é um formato de texto: dá para montar o arquivo à mão com umas
   poucas dezenas de linhas. Foi o caminho escolhido porque:
     · uma lib (jsPDF, pdfmake) custaria centenas de KB para um botão;
     · html2canvas rasterizaria a página — texto vira imagem, não dá para
       selecionar nem pesquisar, e fica borrado ao ampliar;
     · a CSP do site só aceita script do próprio domínio.
   Usa as fontes-padrão Helvetica (todo leitor de PDF tem), texto em
   WinAnsi — que cobre acento do português — e escreve o xref na mão. */
const _PDF_L = 595.28, _PDF_A = 841.89;   // A4 em pontos

function _pdfEscapa(s) {
  /* Só o escape exigido pelo formato PDF. A troca dos caracteres que não
     cabem na fonte é feita na escrita dos bytes (ver EQUIV em bytes()) —
     fazer nos dois lugares deixaria duas listas para manter em sincronia. */
  return String(s).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
}

/* Largura do texto: mede no canvas com a mesma fonte. Serve para alinhar
   número à direita sem precisar embutir a tabela de métricas da Helvetica. */
let _pdfCtx = null;
function _pdfLargura(txt, tam, negrito, espaco) {
  const extra = (espaco || 0) * String(txt).length;   // o Tc do PDF soma após cada glifo
  try {
    // Criado só no primeiro uso, e dentro de try: medir largura não pode ser
    // capaz de derrubar o carregamento do app inteiro.
    if (!_pdfCtx) _pdfCtx = document.createElement('canvas').getContext('2d');
    _pdfCtx.font = (negrito ? 'bold ' : '') + tam + 'px Helvetica, Arial, sans-serif';
    return _pdfCtx.measureText(String(txt)).width + extra;
  } catch (_) {
    return String(txt).length * tam * 0.5 + extra;   // estimativa boa o bastante
  }
}

function _pdfNovoDoc() {
  const paginas = [];
  const imagens = [];        // { dados: Uint8Array (JPEG), larg, alt }
  let ops = null;

  const doc = {
    novaPagina() { ops = []; paginas.push(ops); return doc; },
    /* y é medido de cima para baixo (o PDF conta de baixo para cima). */
    /* o.espaco: espaçamento entre letras (operador Tc). Serve aos rótulos
       pequenos em maiúsculas de documento — sem folga eles ficam apertados e é
       justamente esse detalhe que separa um papel impresso de um rascunho. O Tc
       faz parte do estado de texto e sobrevive ao ET, então vai escrito em toda
       chamada, mesmo quando é zero. */
    texto(x, y, txt, o) {
      o = o || {};
      const tam = o.tam || 10, cor = o.cor || [0, 0, 0], espaco = o.espaco || 0;
      let px = x;
      if (o.alinhar === 'dir') px = x - _pdfLargura(txt, tam, o.negrito, espaco);
      else if (o.alinhar === 'centro') px = x - _pdfLargura(txt, tam, o.negrito, espaco) / 2;
      ops.push(`BT ${cor[0]} ${cor[1]} ${cor[2]} rg /${o.negrito ? 'F2' : 'F1'} ${tam} Tf ` +
               `${espaco} Tc ` +
               `1 0 0 1 ${px.toFixed(2)} ${(_PDF_A - y).toFixed(2)} Tm (${_pdfEscapa(txt)}) Tj ET`);
      return doc;
    },
    linha(x1, y1, x2, y2, o) {
      o = o || {};
      const cor = o.cor || [0.85, 0.85, 0.88];
      ops.push(`${cor[0]} ${cor[1]} ${cor[2]} RG ${(o.esp || 0.6)} w ` +
               `${x1.toFixed(2)} ${(_PDF_A - y1).toFixed(2)} m ${x2.toFixed(2)} ${(_PDF_A - y2).toFixed(2)} l S`);
      return doc;
    },
    retangulo(x, y, w, h, o) {
      o = o || {};
      if (o.preenche) {
        const c = o.preenche;
        ops.push(`${c[0]} ${c[1]} ${c[2]} rg ${x.toFixed(2)} ${(_PDF_A - y - h).toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re f`);
      }
      if (o.borda) {
        const c = o.borda;
        ops.push(`${c[0]} ${c[1]} ${c[2]} RG 0.6 w ${x.toFixed(2)} ${(_PDF_A - y - h).toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re S`);
      }
      return doc;
    },
    /* Desenha uma imagem JPEG. O PDF lê JPEG sem conversão (/DCTDecode), o
       que evita ter de compactar pixel a pixel sem uma biblioteca. Como JPEG
       não guarda transparência e a folha é clara, quem chama converte com
       fundo branco — sobre papel o resultado é o mesmo de transparente. */
    imagem(jpegBytes, x, y, w, h) {
      const id = imagens.length;
      imagens.push(jpegBytes);
      ops.push(`q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${x.toFixed(2)} ${(_PDF_A - y - h).toFixed(2)} cm /Im${id} Do Q`);
      return doc;
    },
    /* Monta o arquivo: objetos, tabela xref e trailer. */
    bytes() {
      const objs = [];
      const fluxosBin = {};                        // id do objeto -> bytes crus
      const nPag = paginas.length;
      const idConteudo = i => 5 + nPag + i;        // 1 catálogo, 2 pages, 3-4 fontes
      const idImagem   = k => 5 + nPag * 2 + k;

      objs[1] = '<< /Type /Catalog /Pages 2 0 R >>';
      objs[2] = `<< /Type /Pages /Kids [${paginas.map((_, i) => `${5 + i} 0 R`).join(' ')}] /Count ${nPag} >>`;
      objs[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
      objs[4] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';

      const recursoImgs = imagens.length
        ? ' /XObject << ' + imagens.map((_, k) => `/Im${k} ${idImagem(k)} 0 R`).join(' ') + ' >>'
        : '';
      paginas.forEach((_, i) => {
        objs[5 + i] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${_PDF_L} ${_PDF_A}] ` +
                      `/Resources << /Font << /F1 3 0 R /F2 4 0 R >>${recursoImgs} >> /Contents ${idConteudo(i)} 0 R >>`;
      });
      paginas.forEach((o, i) => {
        const fluxo = o.join('\n');
        objs[idConteudo(i)] = `<< /Length ${fluxo.length} >>\nstream\n${fluxo}\nendstream`;
      });
      imagens.forEach((img, k) => {
        const id = idImagem(k);
        objs[id] = `<< /Type /XObject /Subtype /Image /Width ${img.larg} /Height ${img.alt} ` +
                   `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${img.dados.length} >>`;
        fluxosBin[id] = img.dados;                 // escrito byte a byte lá embaixo
      });

      // WinAnsi ≈ Latin-1 para o que usamos; fora disso, vira '?'
      const bytes = [];
      /* Caractere acima de 0xFF não cabe na tabela WinAnsi da fonte embutida.
         Este era o ponto onde tudo virava "?" — inclusive o travessão de um
         endereço, que num recibo estraga o documento. Agora os tipográficos
         mais comuns (os que o Word e o teclado do celular produzem) são
         trocados por equivalentes que existem na tabela, e o "?" fica só para
         o que realmente não tem substituto. */
      const EQUIV = {
        0x2014: '-', 0x2013: '-', 0x2212: '-',        // travessão, meia-risca, menos
        0x2018: "'", 0x2019: "'", 0x201A: "'",        // aspas simples curvas
        0x201C: '"', 0x201D: '"', 0x201E: '"',        // aspas duplas curvas
        0x2026: '...',                                 // reticências
        0x00A0: ' ', 0x2009: ' ', 0x202F: ' ', 0x200B: '',  // espaços especiais
        0x2022: '-', 0x00B7: '-', 0x25CF: '-',        // marcadores
        0x2044: '/', 0x2215: '/',                      // barras de fração
        0x20AC: 'EUR', 0x2122: 'TM',
      };
      const escreve = txt => {
        for (const ch of txt) {
          const c = ch.codePointAt(0);
          if (c <= 0xFF) { bytes.push(c); continue; }
          const sub = EQUIV[c];
          if (sub === undefined) { bytes.push(63); continue; }
          for (const s of sub) bytes.push(s.codePointAt(0));
        }
      };

      escreve('%PDF-1.4\n');
      const offsets = [];
      for (let i = 1; i < objs.length; i++) {
        if (!objs[i]) continue;
        offsets[i] = bytes.length;
        if (fluxosBin[i]) {
          // Fluxo binário (JPEG): o dicionário vai por escreve(), mas os bytes
          // da imagem entram crus — passá-los por escreve() os corromperia.
          escreve(`${i} 0 obj\n${objs[i]}\nstream\n`);
          for (const b of fluxosBin[i]) bytes.push(b);
          escreve('\nendstream\nendobj\n');
        } else {
          escreve(`${i} 0 obj\n${objs[i]}\nendobj\n`);
        }
      }
      const inicioXref = bytes.length;
      escreve(`xref\n0 ${objs.length}\n0000000000 65535 f \n`);
      for (let i = 1; i < objs.length; i++) {
        escreve(String(offsets[i]).padStart(10, '0') + ' 00000 n \n');
      }
      escreve(`trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${inicioXref}\n%%EOF`);
      return new Uint8Array(bytes);
    },
  };
  return doc.novaPagina();
}

function _pdfBaixar(bytes, nome) {
  const url = URL.createObjectURL(new Blob([bytes], { type: 'application/pdf' }));
  const a = document.createElement('a');
  a.href = url; a.download = nome;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

/* ═══════════════════════════════════════════════════════════════════════
   RECIBO EM PDF  ·  Premium
   ═══════════════════════════════════════════════════════════════════════
   Um recibo é documento com valor probatório: serve de prova de pagamento
   para os dois lados e pode ir para a contabilidade ou para um processo.
   Por isso ele não é gerado com o que "dá para adivinhar" — o formulário
   pede o que falta e nada é preenchido por suposição.

   O que a lei brasileira espera de um recibo (art. 320 do Código Civil):
   o valor, a que se refere a dívida, quem pagou, quem recebeu, e a data.
   Nome e documento das duas partes são o que permite identificá-las.

   Os dados do emitente ficam guardados em users/{uid}/personal/emitente e
   vêm preenchidos nas próximas vezes — ninguém digita o próprio CPF toda
   semana. Os do cliente saem do cadastro do CRM quando existirem.
   ═══════════════════════════════════════════════════════════════════════ */

/* Valor por extenso. Um recibo sem isso é aceito, mas a praxe pede — e é o
   que dificulta adulteração do algarismo depois de assinado. */
const _EXT_UNI = ['', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove',
  'dez', 'onze', 'doze', 'treze', 'catorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
const _EXT_DEZ = ['', '', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
const _EXT_CEM = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos',
  'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];

function _extensoAte999(n) {
  if (n === 0) return '';
  if (n === 100) return 'cem';
  const partes = [];
  const c = Math.floor(n / 100), resto = n % 100;
  if (c) partes.push(_EXT_CEM[c]);
  if (resto < 20) { if (resto) partes.push(_EXT_UNI[resto]); }
  else {
    const d = Math.floor(resto / 10), u = resto % 10;
    partes.push(_EXT_DEZ[d]);
    if (u) partes.push(_EXT_UNI[u]);
  }
  return partes.join(' e ');
}

function valorPorExtenso(valor) {
  const total = Math.round(Number(valor) * 100);
  const reais = Math.floor(total / 100), centavos = total % 100;
  if (!reais && !centavos) return 'zero real';

  const blocos = [];
  const milhoes = Math.floor(reais / 1000000);
  const milhares = Math.floor((reais % 1000000) / 1000);
  const unidades = reais % 1000;

  if (milhoes) blocos.push(_extensoAte999(milhoes) + (milhoes === 1 ? ' milhão' : ' milhões'));
  if (milhares) blocos.push(milhares === 1 ? 'mil' : _extensoAte999(milhares) + ' mil');
  if (unidades) blocos.push(_extensoAte999(unidades));

  let texto = '';
  if (reais) {
    /* A conjunção antes do último bloco NÃO é livre em português:
         "mil e duzentos"              (último bloco redondo)
         "mil duzentos e trinta e quatro"  (último bloco composto → sem 'e')
         "cento e um"                  (último bloco menor que cem)
       A regra é: entra 'e' quando o último bloco é menor que cem ou é uma
       centena exata. Nos demais casos os blocos ficam justapostos. */
    if (blocos.length > 1) {
      const ultimo = blocos[blocos.length - 1];
      // Sem unidades, o último bloco é o de milhar e ele sempre leva 'e'
      // ("um milhão e quinhentos mil"). Com unidades, vale a regra do
      // último bloco: menor que cem ou centena exata.
      const cabeE = unidades === 0 || unidades < 100 || unidades % 100 === 0;
      texto = blocos.slice(0, -1).join(' ') + (cabeE ? ' e ' : ' ') + ultimo;
    } else {
      texto = blocos[0] || '';
    }
    // "um milhão DE reais" quando o valor é milhão redondo; nos demais,
    // "reais" vem direto ("um milhão e quinhentos mil reais").
    const milhaoRedondo = reais >= 1000000 && reais % 1000000 === 0;
    texto += milhaoRedondo ? ' de reais' : (reais === 1 ? ' real' : ' reais');
  }
  if (centavos) {
    if (texto) texto += ' e ';
    texto += _extensoAte999(centavos) + (centavos === 1 ? ' centavo' : ' centavos');
  }
  return texto;
}

/* Formata CPF/CNPJ só quando o número tem o tamanho certo — máscara aplicada
   a um número incompleto vira documento inválido no papel. */
function _formataDoc(v) {
  const d = String(v || '').replace(/\D/g, '');
  if (d.length === 11) return d.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
  if (d.length === 14) return d.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, '$1.$2.$3/$4-$5');
  return String(v || '').trim();
}

async function _carregarEmitente() {
  if (!CU?.uid || !_fbReady) return {};
  try { return (await fbGet(_personalPath('emitente'))) || {}; } catch (_) { return {}; }
}
async function _salvarEmitente(dados) {
  if (!CU?.uid || !_fbReady) return;
  await fbSet(_personalPath('emitente'), dados).catch(() => {});
}

/* Prepara a imagem da assinatura para o papel.

   O que faz, e por quê:
   1. RECORTA o espaço vazio em volta. Uma foto de assinatura costuma ter a
      folha inteira em volta do traço; sem recortar, a assinatura sairia
      minúscula no meio de um retângulo branco.
   2. LIMPA o fundo. Foto de papel nunca é branco puro — tem sombra e
      amarelado. Tudo que é claro vira branco e o traço é escurecido, o que
      dá o mesmo resultado visual de "fundo removido" sobre uma folha clara.
   3. Exporta em JPEG, que é o formato que o PDF lê sem conversão.

   Não uso transparência de propósito: PNG com alfa exigiria compactar os
   pixels à mão, e como o recibo é impresso sobre fundo claro, branco e
   transparente ficam idênticos no papel. */
function _limparAssinatura(arquivo) {
  return new Promise((ok, falha) => {
    const leitor = new FileReader();
    leitor.onerror = falha;
    leitor.onload = () => {
      const img = new Image();
      img.onerror = falha;
      img.onload = () => {
        // Trabalha numa resolução moderada: assinatura não precisa de mais
        // que isso, e mantém o PDF leve.
        const MAXL = 900;
        const escala = Math.min(1, MAXL / img.width);
        const L = Math.max(1, Math.round(img.width * escala));
        const A = Math.max(1, Math.round(img.height * escala));

        const cv = document.createElement('canvas');
        cv.width = L; cv.height = A;
        const ctx = cv.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(img, 0, 0, L, A);

        const dados = ctx.getImageData(0, 0, L, A);
        const px = dados.data;

        // Limiar relativo ao pixel mais claro: uma foto escura não perde o
        // traço, e uma digitalização clara não fica com fundo sujo.
        let maisClaro = 0;
        for (let i = 0; i < px.length; i += 4) {
          const lum = (px[i] * 0.299 + px[i + 1] * 0.587 + px[i + 2] * 0.114);
          if (lum > maisClaro) maisClaro = lum;
        }
        const corte = Math.max(120, maisClaro * 0.72);

        let minX = L, minY = A, maxX = -1, maxY = -1;
        for (let y = 0; y < A; y++) {
          for (let x = 0; x < L; x++) {
            const i = (y * L + x) * 4;
            const lum = px[i] * 0.299 + px[i + 1] * 0.587 + px[i + 2] * 0.114;
            if (lum >= corte) {
              px[i] = px[i + 1] = px[i + 2] = 255;      // fundo → branco
            } else {
              // Escurece o traço proporcionalmente, preservando a espessura
              // suave das bordas (senão a assinatura fica serrilhada).
              const f = Math.min(1, lum / corte);
              const v = Math.round(f * 90);
              px[i] = px[i + 1] = px[i + 2] = v;
              if (x < minX) minX = x;
              if (x > maxX) maxX = x;
              if (y < minY) minY = y;
              if (y > maxY) maxY = y;
            }
          }
        }
        ctx.putImageData(dados, 0, 0);

        if (maxX < 0) return falha(new Error('imagem sem traço visível'));

        // Recorta com uma folga pequena em volta do traço.
        const folga = Math.round(Math.max(L, A) * 0.02);
        const rx = Math.max(0, minX - folga), ry = Math.max(0, minY - folga);
        const rl = Math.min(L - rx, maxX - minX + 1 + folga * 2);
        const ra = Math.min(A - ry, maxY - minY + 1 + folga * 2);

        const rec = document.createElement('canvas');
        rec.width = rl; rec.height = ra;
        const rctx = rec.getContext('2d');
        rctx.fillStyle = '#fff';
        rctx.fillRect(0, 0, rl, ra);
        rctx.drawImage(cv, rx, ry, rl, ra, 0, 0, rl, ra);

        ok(rec.toDataURL('image/jpeg', 0.92));
      };
      img.src = leitor.result;
    };
    leitor.readAsDataURL(arquivo);
  });
}

/* Do dataURL para os bytes do JPEG, com as dimensões lidas do próprio
   arquivo — o PDF precisa delas no dicionário da imagem. */
function _jpegParaPdf(dataUrl) {
  const b64 = String(dataUrl).split(',')[1];
  if (!b64) return null;
  const bruto = atob(b64);
  const dados = new Uint8Array(bruto.length);
  for (let i = 0; i < bruto.length; i++) dados[i] = bruto.charCodeAt(i);

  // Percorre os marcadores do JPEG até o SOF, que carrega altura e largura.
  let i = 2, larg = 0, alt = 0;
  while (i < dados.length - 9) {
    if (dados[i] !== 0xFF) { i++; continue; }
    const marca = dados[i + 1];
    // SOF0..SOF15, menos DHT(C4), JPG(C8) e DAC(CC)
    if (marca >= 0xC0 && marca <= 0xCF && marca !== 0xC4 && marca !== 0xC8 && marca !== 0xCC) {
      alt  = (dados[i + 5] << 8) | dados[i + 6];
      larg = (dados[i + 7] << 8) | dados[i + 8];
      break;
    }
    i += 2 + ((dados[i + 2] << 8) | dados[i + 3]);
  }
  if (!larg || !alt) return null;
  return { dados, larg, alt };
}

async function abrirReciboCRM(recId) {
  if (!hasFullAccess()) {
    toast('⭐', _appText('app.receiptPremiumOnly', 'O recibo em PDF é exclusivo do Premium.'));
    if (typeof showPremiumModal === 'function') showPremiumModal();
    return;
  }
  const rec = _records.find(r => r.id === recId);
  if (!rec) { toast('⚠', _appText('app.recordNotFound', 'Registro não encontrado.')); return; }

  const em = await _carregarEmitente();
  const hoje = new Date().toISOString().slice(0, 10);

  document.querySelector('.recibo-bg')?.remove();
  const bg = document.createElement('div');
  bg.className = 'modal-bg recibo-bg';
  bg.innerHTML = `
    <div class="modal recibo-modal">
      <div class="m-h1">Emitir recibo</div>
      <div class="m-sub">Um recibo é prova de pagamento. Confira cada campo — nada é preenchido por suposição.</div>

      <div class="recibo-secao">Quem recebeu <span>(você)</span></div>
      <div class="recibo-linha">
        <div><div class="m-lbl">Nome ou razão social *</div>
          <input class="m-inp" id="rc-em-nome" maxlength="120" value="${xe(em.nome || CU?.name || '')}"></div>
        <div><div class="m-lbl">CPF ou CNPJ *</div>
          <input class="m-inp" id="rc-em-doc" maxlength="20" inputmode="numeric" value="${xe(em.doc || '')}"></div>
      </div>
      <div class="recibo-linha">
        <div><div class="m-lbl">Endereço</div>
          <input class="m-inp" id="rc-em-end" maxlength="160" value="${xe(em.endereco || '')}"></div>
        <div><div class="m-lbl">Registro profissional</div>
          <input class="m-inp" id="rc-em-reg" maxlength="40" placeholder="ex.: OAB/MA 12345" value="${xe(em.registro || '')}"></div>
      </div>
      <!-- PARA ONDE A VIA ASSINADA VOLTA. O remetente do e-mail é um endereço
           de sistema que não lê resposta nenhuma; sem este campo, "responda a
           este e-mail" mandava o cliente escrever para o vazio. E ele não pode
           ser adivinhado da conta: o e-mail de login do MyDesk não é
           necessariamente o e-mail de trabalho de quem presta o serviço. -->
      <div><div class="m-lbl">E-mail para receber a via assinada</div>
        <input class="m-inp" id="rc-em-email" type="email" maxlength="160"
          placeholder="${sanitizeAttr(_appText('app.receiptReplyToPh', 'o seu e-mail de trabalho — é para cá que o cliente devolve o recibo assinado'))}"
          value="${xe(em.email || CU?.email || '')}"></div>

      <div class="recibo-secao">Quem pagou <span>(cliente)</span></div>
      <div class="recibo-linha">
        <div><div class="m-lbl">Nome ou razão social *</div>
          <input class="m-inp" id="rc-cl-nome" maxlength="120" value="${xe(rec.name || '')}"></div>
        <div><div class="m-lbl">CPF ou CNPJ</div>
          <input class="m-inp" id="rc-cl-doc" maxlength="20" inputmode="numeric" value="${xe(rec.cpf || '')}"></div>
      </div>
      <div class="recibo-linha">
        <div><div class="m-lbl">Endereço do cliente</div>
          <input class="m-inp" id="rc-cl-end" maxlength="160"></div>
        <!-- O e-mail entra AQUI, e não só na ficha. Ele é o que decide se dá
             para mandar o recibo para o cliente assinar a via dele, e mandar a
             pessoa sair desta tela, abrir "Editar", preencher e voltar é
             transformar um campo que falta em quatro cliques. O que for
             digitado aqui é gravado na ficha — o servidor lê o destinatário de
             lá, e essa trava não se afrouxa por comodidade. -->
        <div><div class="m-lbl">E-mail do cliente</div>
          <input class="m-inp" id="rc-cl-email" type="email" maxlength="160"
            placeholder="${sanitizeAttr(_appText('app.receiptEmailPh', 'para enviar o recibo'))}"
            value="${xe(rec.email || '')}"></div>
      </div>

      <div class="recibo-secao">O pagamento</div>
      <div class="recibo-linha">
        <div><div class="m-lbl">Valor recebido (R$) *</div>
          <input class="m-inp" id="rc-valor" type="number" step="0.01" min="0" value="${Number(rec.value) || 0}"></div>
        <div><div class="m-lbl">Data do pagamento *</div>
          <input class="m-inp" id="rc-data" type="date" value="${xe(hoje)}"></div>
      </div>
      <div><div class="m-lbl">Referente a *</div>
        <textarea class="m-inp" id="rc-ref" rows="2" maxlength="400"
          placeholder="${sanitizeAttr(_appText('app.receiptDescPlaceholder', 'ex.: honorários advocatícios referentes ao processo nº …'))}">${xe(rec.description || '')}</textarea></div>
      <div class="recibo-linha">
        <div><div class="m-lbl">Forma de pagamento</div>
          <select class="m-inp" id="rc-forma">
            <option value="">não especificar</option>
            <option value="Pix">Pix</option>
            <option value="dinheiro">dinheiro</option>
            <option value="transferência bancária">transferência bancária</option>
            <option value="cartão de débito">cartão de débito</option>
            <option value="cartão de crédito">cartão de crédito</option>
            <option value="boleto">boleto</option>
            <option value="cheque">cheque</option>
          </select></div>
        <div><div class="m-lbl">Cidade *</div>
          <input class="m-inp" id="rc-cidade" maxlength="60" value="${xe(em.cidade || '')}"></div>
      </div>
      <div class="recibo-secao">Assinatura <span>(fica guardada para as próximas)</span></div>
      <div class="recibo-assin" id="rc-assin-area">
        <div class="recibo-assin-previa" id="rc-assin-previa"></div>
        <div class="recibo-assin-acoes">
          <label class="recibo-assin-btn">Enviar imagem
            <input type="file" id="rc-assin-inp" accept="image/*"></label>
          <button type="button" class="recibo-assin-limpar" id="rc-assin-limpar" hidden>Remover</button>
        </div>
        <div class="recibo-assin-dica">Foto ou digitalização da assinatura em papel branco. O fundo é removido automaticamente.</div>
      </div>

      <label class="recibo-check">
        <input type="checkbox" id="rc-parcial">
        <span>Pagamento parcial — o recibo dirá que quita apenas esta parte</span>
      </label>

      <div class="campo-erro" id="rc-erro"></div>
      <div class="m-btns">
        <button class="m-cancel" id="rc-cancel">Cancelar</button>
        <button class="m-confirm" id="rc-ok">Gerar recibo</button>
      </div>
    </div>`;
  document.body.appendChild(bg);

  const fechar = () => bg.remove();
  bg.querySelector('#rc-cancel').addEventListener('click', fechar);
  bg.addEventListener('click', e => { if (e.target === bg) fechar(); });

  // ── Assinatura ──
  let assinatura = em.assinatura || null;          // dataURL JPEG, fundo branco
  const previa  = bg.querySelector('#rc-assin-previa');
  const btnLimpar = bg.querySelector('#rc-assin-limpar');
  const mostrarAssin = () => {
    previa.innerHTML = '';
    if (assinatura) {
      const img = document.createElement('img');
      img.src = assinatura;
      img.alt = 'Assinatura';
      previa.appendChild(img);
      btnLimpar.hidden = false;
    } else {
      previa.textContent = 'Nenhuma assinatura enviada';
      previa.className = 'recibo-assin-previa vazia';
      btnLimpar.hidden = true;
    }
  };
  mostrarAssin();

  bg.querySelector('#rc-assin-inp').addEventListener('change', async e => {
    const arq = e.target.files?.[0];
    if (!arq) return;
    try {
      assinatura = await _limparAssinatura(arq);
      previa.className = 'recibo-assin-previa';
      mostrarAssin();
    } catch (_) {
      toast('⚠', _appText('app.imageReadError', 'Não foi possível ler essa imagem.'));
    }
    e.target.value = '';
  });
  btnLimpar.addEventListener('click', () => { assinatura = null; mostrarAssin(); });

  bg.querySelector('#rc-ok').addEventListener('click', async () => {
    const v = id => (bg.querySelector('#' + id)?.value || '').trim();
    const erro = bg.querySelector('#rc-erro');

    const dados = {
      emNome: v('rc-em-nome'), emDoc: v('rc-em-doc'), emEnd: v('rc-em-end'), emReg: v('rc-em-reg'),
      clNome: v('rc-cl-nome'), clDoc: v('rc-cl-doc'), clEnd: v('rc-cl-end'),
      valor: Number(v('rc-valor')), data: v('rc-data'), referente: v('rc-ref'),
      forma: v('rc-forma'), cidade: v('rc-cidade'),
      parcial: bg.querySelector('#rc-parcial').checked,
    };

    // Estes cinco são o que faz o papel valer como recibo. Sem qualquer um
    // deles o documento não identifica as partes, o valor ou a dívida.
    const faltando = [];
    if (!dados.emNome) faltando.push('seu nome');
    if (!dados.emDoc)  faltando.push('seu CPF/CNPJ');
    if (!dados.clNome) faltando.push('o nome do cliente');
    if (!(dados.valor > 0)) faltando.push('o valor');
    if (!dados.data) faltando.push('a data');
    if (!dados.referente) faltando.push('a que se refere');
    if (!dados.cidade) faltando.push('a cidade');
    if (faltando.length) {
      erro.textContent = 'Falta preencher: ' + faltando.join(', ') + '.';
      return;
    }

    /* Numeração sequencial por emitente. Recibo sem número é o que mais denuncia
       documento improvisado — e, na prática, é o que permite referenciar "o
       recibo nº 12" depois. O contador mora junto dos dados do emitente e sobe
       de um a cada emissão. */
    dados.numero = (Number(em.serie) || 0) + 1;

    // Guarda os dados do emitente para as próximas vezes.
    /* O e-mail de resposta vai junto dos dados do emitente, e o SERVIDOR o lê
       de lá — nunca do corpo do POST. É o mesmo princípio do destinatário:
       endereço que vira cabeçalho de e-mail sai do banco, onde só o dono da
       conta escreve. */
    dados.emEmail = v('rc-em-email');
    if (dados.emEmail && !/^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(dados.emEmail)) {
      erro.textContent = _appText('app.receiptCheckReplyTo',
        'Confira o seu e-mail para a via assinada.');
      return;
    }
    await _salvarEmitente({
      nome: dados.emNome, doc: dados.emDoc, endereco: dados.emEnd,
      registro: dados.emReg, cidade: dados.cidade,
      email: dados.emEmail || '',
      assinatura: assinatura || null,
      serie: dados.numero,
    });
    dados.assinatura = assinatura;

    /* ── UM RECIBO, DOIS DESTINOS ────────────────────────────────────────
       Enquanto ele tinha uma assinatura só, baixar bastava: o papel já estava
       completo ao sair. Com o campo do pagante, ele precisa CHEGAR ao pagante
       — senão a segunda linha nunca é assinada e o campo vira enfeite.

       A escolha não é adivinhada: baixar continua sendo o caminho de quem vai
       imprimir e colher a assinatura na mão, e enviar é o de quem resolve por
       e-mail. Sem endereço na ficha do cliente, só a primeira aparece — e a
       segunda diz por que não está disponível, em vez de sumir sem explicar. */
    /* O e-mail digitado aqui vale, e é GRAVADO NA FICHA antes de qualquer
       envio. O servidor lê o destinatário do banco — é o que garante que só
       dá para mandar recibo para os próprios clientes — então o campo desta
       tela não pode ser um atalho por fora: ele atualiza a ficha, e o envio
       continua saindo de lá. De quebra, quem preenche aqui não precisa
       preencher de novo na próxima vez. */
    const emailDigitado = v('rc-cl-email');
    if (emailDigitado && !/^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(emailDigitado)) {
      erro.textContent = _appText('app.receiptCheckEmail',
        'Confira o e-mail do cliente.');
      return;
    }
    if (emailDigitado && emailDigitado !== String(rec.email || '').trim()) {
      await updateRecord(rec.id, { email: emailDigitado });
    }

    const arquivo = gerarReciboPDF(dados, rec);
    const paraCliente = emailDigitado || String(rec.email || '').trim();
    const escolha = await _escolherCaminho(
      _appText('app.receiptReady', 'Recibo nº {n} pronto', {
        n: String(dados.numero).padStart(4, '0') }),
      _appText('app.receiptReadySub',
        'O recibo tem duas linhas de assinatura: a sua e a de {nome}.',
        { nome: dados.clNome }),
      [
        { valor: 'baixar', titulo: _appText('app.receiptDownload', 'Baixar o PDF'),
          sub: _appText('app.receiptDownloadSub',
            'Para imprimir e colher a assinatura na mão, ou anexar você mesmo.') },
        { valor: 'enviar', titulo: _appText('app.receiptSend', 'Enviar para {nome} assinar',
            { nome: dados.clNome }),
          sub: paraCliente
            ? _appText('app.receiptSendSub', 'Vai anexado para {email}.', { email: paraCliente })
            : _appText('app.receiptNoEmail',
                'Este cliente não tem e-mail na ficha. Informe um em "Editar" para enviar daqui.'),
          desabilitado: !paraCliente },
      ]);
    if (!escolha) return;

    if (escolha === 'baixar') {
      _pdfBaixar(arquivo.bytes, arquivo.nome);
      fechar();
      toast('🧾', _appText('app.receiptDone', 'Recibo gerado.'));
      return;
    }

    const btnOk = bg.querySelector('#rc-ok');
    if (btnOk) btnOk.disabled = true;
    try {
      await crmEnviarReciboPorEmail(rec.id, arquivo, dados);
      fechar();
      toast('✉️', _appText('app.receiptSent', 'Recibo enviado para {email}.',
        { email: paraCliente }));
    } catch (e) {
      erro.textContent = e && e.message
        ? e.message : _appText('app.receiptSendFailed', 'Não consegui enviar agora.');
      if (btnOk) btnOk.disabled = false;
    }
  });
}

/* ── Escolher entre dois caminhos, com o porquê de cada um à vista ────────
   Genérico de propósito: o recibo é o primeiro, e a cobrança e o relatório
   pedem a mesma pergunta. Opção indisponível aparece APAGADA e com o motivo
   escrito — sumir com ela deixaria a pessoa procurando um recurso que existe. */
function _escolherCaminho(titulo, subtitulo, opcoes) {
  return new Promise(resolve => {
    document.querySelector('.pm-bg')?.remove();
    const bg = document.createElement('div');
    bg.className = 'modal-bg pm-bg';
    bg.innerHTML = `
      <div class="modal pm-modal">
        <div class="pm-h1">${xe(titulo)}</div>
        ${subtitulo ? `<div class="pm-sub">${xe(subtitulo)}</div>` : ''}
        ${opcoes.map(o => `
          <button type="button" class="pm-opt${o.desabilitado ? ' pm-opt-off' : ''}"
                  data-op="${sanitizeAttr(o.valor)}"${o.desabilitado ? ' disabled' : ''}>
            <span class="pm-opt-txt">
              <b>${xe(o.titulo)}</b>
              <i>${xe(o.sub || '')}</i>
            </span>
          </button>`).join('')}
        <button type="button" class="pm-cancelar">${
          xe(_appText('common.cancel', 'Cancelar'))}</button>
      </div>`;
    document.body.appendChild(bg);
    const sair = v => { bg.remove(); resolve(v); };
    bg.querySelectorAll('[data-op]').forEach(b =>
      b.addEventListener('click', () => sair(b.dataset.op)));
    bg.querySelector('.pm-cancelar').addEventListener('click', () => sair(null));
    bg.addEventListener('click', ev => { if (ev.target === bg) sair(null); });
  });
}

/* O anexo vai do navegador para o e-mail sem passar pelo banco: guardá-lo
   seria acumular megabytes por recibo emitido. O DESTINATÁRIO continua saindo
   da ficha no servidor — daqui vai o id do registro e o arquivo. */
async function crmEnviarReciboPorEmail(recId, arquivo, dados) {
  const fbUser = window._fbAuth?.currentUser;
  if (!fbUser) throw new Error(_appText('app.signInFirst', 'Faça login primeiro.'));
  let bruto = '';
  for (let i = 0; i < arquivo.bytes.length; i++) bruto += String.fromCharCode(arquivo.bytes[i]);
  const resp = await fetch(VERCEL_API + '/api/form', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json',
               'Authorization': 'Bearer ' + await fbUser.getIdToken() },
    body: JSON.stringify({
      acao: 'enviarRecibo',
      cliente: recId,
      destino: _fmCrmDestinoAtual(),
      idioma: _appLocale().slice(0, 2),
      numero: dados.numero,
      valor: dados.valor,
      referente: dados.referente,
      emitente: dados.emNome,
      arquivo: { nome: arquivo.nome, dataUrl: 'data:application/pdf;base64,' + btoa(bruto) },
    }),
  });
  const r = await resp.json().catch(() => ({}));
  if (!resp.ok) throw new Error(r.error || _appText('app.receiptSendFailed',
    'Não consegui enviar agora.'));
  return true;
}

function gerarReciboPDF(d, rec) {
  const hex = h => [parseInt(h.slice(1, 3), 16) / 255, parseInt(h.slice(3, 5), 16) / 255, parseInt(h.slice(5, 7), 16) / 255];
  const TINTA = hex('#14141c'), FRACA = hex('#6b6b7b'), LINHA = hex('#d8d8e0'), MARCA = hex('#4f46e5');

  const M = 56, DIR = _PDF_L - M, LARG = DIR - M;
  const doc = _pdfNovoDoc();
  let y = 0;

  const dataBR = iso => {
    const [a, m, dd] = String(iso).split('-');
    return `${dd}/${m}/${a}`;
  };
  const porExtensoData = iso => {
    const meses = ['janeiro','fevereiro','março','abril','maio','junho','julho',
                   'agosto','setembro','outubro','novembro','dezembro'];
    const [a, m, dd] = String(iso).split('-').map(Number);
    return `${dd} de ${meses[m - 1]} de ${a}`;
  };

  /* Quebra o texto na largura da folha. O gerador escreve linha a linha e não
     sabe quebrar sozinho — sem isto o parágrafo sairia da margem direita. */
  const quebrar = (txt, tam, largura) => {
    const palavras = String(txt).split(/\s+/);
    const linhas = [];
    let atual = '';
    palavras.forEach(p => {
      const teste = atual ? atual + ' ' + p : p;
      if (_pdfLargura(teste, tam) > largura && atual) { linhas.push(atual); atual = p; }
      else atual = teste;
    });
    if (atual) linhas.push(atual);
    return linhas;
  };
  const paragrafo = (txt, tam, cor, entrelinha) => {
    quebrar(txt, tam, LARG).forEach(l => { doc.texto(M, y, l, { tam, cor }); y += entrelinha || tam + 6; });
  };

  /* Rótulo pequeno de documento: maiúsculas, cinza e com folga entre letras.
     É o que dá ao papel o ar de formulário impresso em vez de texto corrido. */
  const rotulo = (x, yy, txt, alinhar) =>
    doc.texto(x, yy, txt, { tam: 6.8, negrito: true, cor: FRACA, espaco: 1.15, alinhar });

  // ── Timbre: quem emite à esquerda, o documento à direita ──
  // Um recibo se identifica pelo emitente, não pela palavra "recibo": o nome de
  // quem recebeu o dinheiro é a informação que abre o papel.
  doc.texto(M, 66, d.emNome, { tam: 13, negrito: true, cor: TINTA });
  let yl = 80;
  [d.emReg, _formataDoc(d.emDoc), d.emEnd].filter(Boolean).forEach(linha => {
    doc.texto(M, yl, linha, { tam: 8.5, cor: FRACA });
    yl += 12;
  });

  doc.texto(DIR, 68, 'RECIBO', { tam: 23, negrito: true, cor: TINTA, espaco: 2, alinhar: 'dir' });
  const serie = d.numero
    ? 'Nº ' + String(d.numero).padStart(4, '0') + '/' + String(d.data).slice(0, 4)
    : '';
  if (serie) doc.texto(DIR, 86, serie, { tam: 9.5, cor: TINTA, alinhar: 'dir' });
  rotulo(DIR, 100, 'VIA DO PAGANTE', 'dir');

  y = Math.max(yl + 8, 114);
  doc.linha(M, y, DIR, y, { cor: TINTA, esp: 1.4 });

  // ── Valor: a informação que se procura primeiro ──
  y += 26;
  const caixaAlt = 58;
  doc.retangulo(M, y, LARG, caixaAlt, { preenche: [0.969, 0.969, 0.98] });
  doc.retangulo(M, y, 3.2, caixaAlt, { preenche: MARCA });   // filete de cor, sem colorir o bloco
  rotulo(M + 18, y + 21, 'VALOR RECEBIDO');
  doc.texto(M + 18, y + 45, fmtBRL(d.valor), { tam: 21, negrito: true, cor: TINTA });
  const extensoCaixa = valorPorExtenso(d.valor);
  if (_pdfLargura(extensoCaixa, 8.5) < LARG - 230) {
    doc.texto(DIR - 18, y + 45, '(' + extensoCaixa + ')', { tam: 8.5, cor: FRACA, alinhar: 'dir' });
  }
  y += caixaAlt + 30;

  // ── Corpo, na forma consagrada de recibo ──
  const extenso = valorPorExtenso(d.valor);
  const quemPagou = d.clNome + (d.clDoc ? ', inscrito(a) no CPF/CNPJ sob o nº ' + _formataDoc(d.clDoc) : '')
    + (d.clEnd ? ', com endereço em ' + d.clEnd : '');
  const forma = d.forma ? ', pago(a) por ' + d.forma : '';
  const quita = d.parcial
    ? 'dando quitação apenas quanto à importância ora recebida, permanecendo devido o saldo remanescente.'
    : 'dando plena, geral e irrevogável quitação quanto à importância recebida.';

  paragrafo(
    `Recebi de ${quemPagou} a importância de ${fmtBRL(d.valor)} (${extenso})${forma}, ` +
    `referente a ${d.referente}, ${quita}`,
    11, TINTA, 18);

  /* ── Detalhamento em grade de duas colunas ──
     A lista antiga era rótulo à esquerda e valor a 130pt de distância, o que
     abria um vão enorme no meio da folha. Em grade, cada dado fica sob o próprio
     rótulo e as duas colunas fecham a largura da página. */
  y += 26;
  rotulo(M, y, 'DETALHAMENTO DO PAGAMENTO');
  y += 8;
  doc.linha(M, y, DIR, y, { cor: TINTA, esp: 0.9 });
  y += 24;

  const colL = M, colR = M + LARG / 2 + 6, largCol = LARG / 2 - 10;
  const celula = (x, yy, rot, val) => {
    if (!val) return;
    rotulo(x, yy, rot);
    let texto = String(val);
    while (_pdfLargura(texto, 10) > largCol && texto.length > 6) texto = texto.slice(0, -2);
    if (texto !== String(val)) texto += '…';
    doc.texto(x, yy + 15, texto, { tam: 10, cor: TINTA });
  };
  const grade = [
    ['PAGANTE', d.clNome, 'CPF / CNPJ DO PAGANTE', d.clDoc ? _formataDoc(d.clDoc) : '—'],
    ['DATA DO PAGAMENTO', dataBR(d.data), 'FORMA DE PAGAMENTO', d.forma || 'não especificada'],
    ['QUITAÇÃO', d.parcial ? 'Parcial' : 'Integral', 'VALOR', fmtBRL(d.valor)],
  ];
  grade.forEach(([r1, v1, r2, v2]) => {
    celula(colL, y, r1, v1);
    celula(colR, y, r2, v2);
    y += 34;
  });
  if (d.clEnd) { celula(colL, y, 'ENDEREÇO DO PAGANTE', d.clEnd); y += 34; }

  y += 2;
  doc.linha(M, y, DIR, y, { cor: LINHA });

  // ── Local, data e assinatura ──
  y += 26;
  doc.texto(DIR, y, `${d.cidade}, ${porExtensoData(d.data)}.`, { tam: 10, cor: TINTA, alinhar: 'dir' });

  /* ── AS DUAS ASSINATURAS ────────────────────────────────────────────────
     A quitação do art. 320 é declaração de QUEM RECEBE, e a assinatura dele
     basta para o recibo valer. A do pagante não é requisito — mas é praxe
     corrente, e tem serventia própria: ela registra que a outra parte recebeu
     a via e concorda com o que está escrito (o valor, a data, a que se
     refere). Num acerto que depois vira discussão, é a diferença entre "eu
     declaro que recebi" e "nós dois concordamos com o que aconteceu".

     Ficam LADO A LADO, do mesmo tamanho. Uma embaixo da outra faria a de
     baixo parecer secundária, e num documento de duas partes nenhuma das duas
     é o rodapé da outra. */
  y += 74;
  const colEsq = M + LARG * 0.25;
  const colDir = M + LARG * 0.75;
  const meiaLinha = Math.min(160, LARG * 0.42);

  /* A assinatura digitalizada vai ACIMA da linha, como numa folha assinada à
     mão — e é desenhada antes dela para que o traço possa cruzar o risco, que
     é o que acontece de verdade quando alguém assina. */
  const assin = d.assinatura ? _jpegParaPdf(d.assinatura) : null;
  if (assin) {
    const larguraMax = meiaLinha - 10, alturaMax = 54;
    const proporcao = assin.larg / assin.alt;
    let w = larguraMax, h = w / proporcao;
    if (h > alturaMax) { h = alturaMax; w = h * proporcao; }
    doc.imagem(assin, colEsq - w / 2, y - h + 6, w, h);
  }

  /* Os dois rótulos de pé ficam na MESMA altura, mesmo quando um dos lados
     tem uma linha a mais (o emitente costuma ter registro profissional e o
     pagante não). Desencontrados, o papel parece ter sido montado torto. */
  const alturaDe = (docto, extra) => 15 + (docto ? 13 : 0) + (extra ? 12 : 0) + 13;
  const yRotulo = y + Math.max(alturaDe(d.emDoc, d.emReg), alturaDe(d.clDoc, ''));

  const bloco = (centro, nome, docto, extra, rotuloPe) => {
    doc.linha(centro - meiaLinha / 2, y, centro + meiaLinha / 2, y, { cor: TINTA });
    let yb = y + 15;
    const posto = (txt, tam, negrito, cor) => {
      doc.texto(centro, yb, txt, { tam, negrito, cor, alinhar: 'centro' });
    };
    posto(nome || '—', 10, true, TINTA);
    if (docto) { yb += 13; posto(_formataDoc(docto), 8.5, false, FRACA); }
    if (extra) { yb += 12; posto(extra, 8.5, false, FRACA); }
    doc.texto(centro, yRotulo, rotuloPe, { tam: 7, cor: FRACA, espaco: .9, alinhar: 'centro' });
  };

  bloco(colEsq, d.emNome, d.emDoc, d.emReg, 'Assinatura de quem recebeu');
  bloco(colDir, d.clNome, d.clDoc, '', 'Assinatura do pagante');
  y = yRotulo;

  /* ── FUNDAMENTO LEGAL ───────────────────────────────────────────────────
     O que dá respaldo a um recibo não é a palavra "recibo" no alto: é ele
     reunir o que o art. 320 do Código Civil exige. Escrever isso no próprio
     papel muda como ele é lido — por quem recebe, por um contador e por um
     juiz. E não é enfeite: a citação diz exatamente quais requisitos o
     documento cumpre, e o leitor confere um a um logo acima.

     O texto do artigo vai LITERAL, entre aspas. Parafrasear lei num documento
     que serve de prova é o tipo de liberdade que estraga o efeito de citá-la.

     A nota final existe porque a segunda assinatura levanta a pergunta: a do
     pagante não é exigida por lei, e é melhor o papel dizer o que ela é do
     que deixar alguém supor que sem ela o recibo não vale. */
  /* A folga acima encolhe quando o corpo do recibo foi longo: o fundamento é a
     última coisa da folha, e um "referente a" de quatro linhas não pode
     empurrá-lo por cima do rodapé. */
  y += Math.max(14, Math.min(34, (_PDF_A - 70) - 66 - y));
  doc.linha(M, y, DIR, y, { cor: LINHA });
  y += 15;
  rotulo(M, y, 'FUNDAMENTO LEGAL');
  y += 14;
  const legal = [
    'Quitação emitida nos termos dos arts. 319 e 320 da Lei nº 10.406/2002 (Código Civil).',
    'Art. 320. "A quitação, que sempre poderá ser dada por instrumento particular, designará o '
      + 'valor e a espécie da dívida quitada, o nome do devedor, ou quem por este pagou, o tempo '
      + 'e o lugar do pagamento, com a assinatura do credor, ou do seu representante."',
    d.parcial
      ? 'A quitação aqui dada alcança apenas a importância recebida, permanecendo devido o saldo '
        + 'remanescente. A assinatura do pagante não é exigida por lei: ela registra o recebimento '
        + 'desta via e a concordância com os termos acima.'
      : 'Este documento reúne esses requisitos e serve de prova de pagamento para as duas partes. '
        + 'A assinatura do pagante não é exigida por lei: ela registra o recebimento desta via e a '
        + 'concordância com os termos acima.',
  ];
  legal.forEach(txt => {
    quebrar(txt, 7.4, LARG).forEach(l => {
      doc.texto(M, y, l, { tam: 7.4, cor: FRACA });
      y += 10;
    });
    y += 3;
  });

  // ── Rodapé ──
  doc.linha(M, _PDF_A - 58, DIR, _PDF_A - 58, { cor: LINHA });
  const emitidoEm = new Date().toLocaleString('pt-BR', {
    day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  doc.texto(M, _PDF_A - 44,
            (serie ? 'Recibo ' + serie + ' · e' : 'E') + 'mitido em ' + emitidoEm + ' pelo MyDesk',
            { tam: 7.5, cor: FRACA });
  doc.texto(DIR, _PDF_A - 44, 'Documento gerado eletronicamente',
            { tam: 7.5, cor: FRACA, alinhar: 'dir' });

  const nomeArq = 'recibo-' + (d.numero ? String(d.numero).padStart(4, '0') + '-' : '')
    + (d.clNome || 'cliente').toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40)
    + '-' + d.data + '.pdf';
  /* Devolve o arquivo em vez de baixá-lo direto: o mesmo recibo agora tem dois
     destinos — o disco de quem emitiu e a caixa de entrada de quem pagou, que
     precisa recebê-lo para assinar a via dele. Quem chama decide. */
  return { bytes: doc.bytes(), nome: nomeArq };
}

/* ═══════════════════════════════════════════════════════════════════
   DESPESAS DO QUADRO — O QUE FALTAVA PARA EXISTIR RESULTADO
   ═══════════════════════════════════════════════════════════════════
   O financeiro só tinha o que ENTRA. Um relatório sem saída mostra
   faturamento e nunca resultado, e faturamento alto com margem negativa é
   exatamente o retrato que quebra empresa sem ninguém ver chegando.

   POR QUE NÃO REAPROVEITAR AS DESPESAS DO PAINEL PESSOAL. Elas existem, em
   users/{uid}/personal/expenses, e a tentação era ligar as duas pontas. Mas
   elas são de OUTRA natureza e de outro dono: são as despesas da PESSOA
   (mercado, transporte, assinaturas), guardadas por usuário, não por quadro.
   Puxá-las para cá faria duas coisas erradas de uma vez — misturaria a conta
   de casa com a do negócio, e num quadro de grupo mostraria os gastos
   pessoais de quem criou para todos os sócios. O invariante do app é que
   quadro pessoal nunca se mistura com grupo ou 1:1, e ele vale aqui.

   Então a despesa do quadro é entidade própria, no mesmo nó dos registros —
   como vaga, talento e colaborador. Cada quadro tem as suas.
   ═══════════════════════════════════════════════════════════════════ */

const DESPESA_CATEGORIAS = [
  { key: 'pessoal',    i18n: 'app.expCatPeople',   pt: 'Pessoal e encargos' },
  { key: 'estrutura',  i18n: 'app.expCatOffice',   pt: 'Estrutura e aluguel' },
  { key: 'ferramenta', i18n: 'app.expCatTools',    pt: 'Ferramentas e assinaturas' },
  { key: 'imposto',    i18n: 'app.expCatTax',      pt: 'Impostos e taxas' },
  { key: 'marketing',  i18n: 'app.expCatMarketing', pt: 'Marketing' },
  { key: 'terceiro',   i18n: 'app.expCatOutsourced', pt: 'Terceiros e fornecedores' },
  { key: 'outros',     i18n: 'app.expCatOther',    pt: 'Outros' },
];

let _despesas = [];

function _ehDespesa(r) { return !!(r && r.type === 'despesa'); }

function crmDespesas() { return _despesas; }

function _despesaCategoria(key) {
  const c = DESPESA_CATEGORIAS.find(x => x.key === key);
  return c ? _appText(c.i18n, c.pt) : _appText('app.expCatOther', 'Outros');
}

function _despesaNormalizar(d) {
  return {
    descricao: String(d.descricao || '').trim().slice(0, 160),
    valor: Math.max(0, Number(d.valor) || 0),
    categoria: DESPESA_CATEGORIAS.some(c => c.key === d.categoria) ? d.categoria : 'outros',
    data: /^\d{4}-\d{2}-\d{2}$/.test(String(d.data || '')) ? d.data : _crmTodayLocalIso(),
    fornecedor: String(d.fornecedor || '').trim().slice(0, 120),
    /* Recorrente aqui é só uma ETIQUETA, e não gera lançamentos: uma despesa
       fixa que se repete sozinha viraria dezenas de linhas que ninguém
       conferiu, e despesa não conferida é pior do que despesa não lançada. */
    fixa: !!d.fixa,
    observacao: String(d.observacao || '').trim().slice(0, 400),
  };
}

async function criarDespesa(dados) {
  if (!CU) return null;
  const check = _crmCanCreate();
  if (!check.ok) {
    toast('🔒', _appText('app.itemsLimitReached',
      'Limite de {limit} itens atingido. Faça upgrade!', { limit: check.limit }));
    if (typeof showPremiumModal === 'function') showPremiumModal();
    return null;
  }
  const campos = _despesaNormalizar(dados);
  if (!campos.descricao || campos.valor <= 0) {
    toast('⚠', _appText('app.expNeedsBoth', 'A despesa precisa de descrição e valor.'));
    return null;
  }
  const now = Date.now();
  const d = {
    id: 'crm_desp_' + now + '_' + Math.random().toString(36).slice(2, 7),
    type: 'despesa',
    ...campos,
    createdAt: now, updatedAt: now, createdBy: CU.username || '',
  };
  if (!_crmDB()) { _despesas.push(d); return d; }
  try {
    await _crmSet(_recBasePath() + '/' + d.id, d);
    return d;
  } catch (e) {
    console.error('[despesas] criar:', e);
    toast('❌', _appText('app.expSaveError', 'Erro ao salvar a despesa.'));
    return null;
  }
}

async function atualizarDespesa(id, mudancas) {
  const atual = _despesas.find(d => String(d.id) === String(id));
  if (!atual || !CU) return null;
  const atualizada = Object.assign({}, atual,
    _despesaNormalizar(Object.assign({}, atual, mudancas)), { updatedAt: Date.now() });
  if (!atualizada.descricao || atualizada.valor <= 0) return null;
  if (!_crmDB()) {
    const i = _despesas.findIndex(d => String(d.id) === String(id));
    if (i !== -1) _despesas[i] = atualizada;
    return atualizada;
  }
  try {
    await _crmSet(_recBasePath() + '/' + id, atualizada);
    const i = _despesas.findIndex(d => String(d.id) === String(id));
    if (i !== -1) _despesas[i] = atualizada;
    return atualizada;
  } catch (e) { console.error('[despesas] atualizar:', e); return null; }
}

async function excluirDespesa(id) {
  if (!CU) return false;
  if (!_crmDB()) {
    _despesas = _despesas.filter(d => String(d.id) !== String(id));
    return true;
  }
  try { await _crmRemove(_recBasePath() + '/' + id); return true; }
  catch (e) { console.error('[despesas] excluir:', e); return false; }
}

/* Despesas de um mês aaaa-mm. O mês é do LANÇAMENTO, e não da criação: uma
   conta de julho lançada em agosto pertence a julho, e é assim que ela tem de
   entrar no resultado de julho. */
function _despesasDoMes(mes) {
  return _despesas.filter(d => String(d.data || '').slice(0, 7) === mes);
}

function _despesaTotalDoMes(mes) {
  return _despesasDoMes(mes).reduce((s, d) => s + (Number(d.valor) || 0), 0);
}

/* Receita RECEBIDA no mês, para o resultado. É o que entrou, e não o que foi
   contratado: resultado com receita a receber é lucro que ainda não existe. */
function _receitaRecebidaNoMes(mes) {
  return _registrosFinanceiros().reduce((s, r) => {
    if (_crmRecMonth(r) !== mes) return s;
    return s + _crmRecebido(r);
  }, 0);
}

/* ── A TELA DAS DESPESAS ────────────────────────────────────────────────
   Ela abre num mês e mostra três números no alto: entrou, saiu, sobrou. É a
   ordem em que a pergunta se faz, e "sobrou" é o único dos três que não
   existia em lugar nenhum do app até agora.

   O mês é navegável porque despesa se lança depois: a conta de julho chega
   em agosto, e quem lança precisa voltar para o mês a que ela pertence. */
let _despMes = null;

function crmAbrirDespesas() {
  _despMes = _despMes || _crmTodayLocalIso().slice(0, 7);
  document.querySelector('.dsp-bg')?.remove();
  const bg = document.createElement('div');
  bg.className = 'modal-bg dsp-bg';
  bg.innerHTML = `
    <div class="modal dsp-modal">
      <div class="flx-cab">
        <div>
          <div class="m-h1">${xe(_appText('app.expTitle', 'Despesas do quadro'))}</div>
          <div class="m-sub">${xe(_appText('app.expSub',
            'O que sai — para o relatório mostrar resultado, e não só faturamento.'))}</div>
        </div>
        <button class="flx-x" id="dsp-fechar"
                aria-label="${sanitizeAttr(_appText('common.close', 'Fechar'))}">✕</button>
      </div>
      <div id="dsp-corpo"></div>
    </div>`;
  document.body.appendChild(bg);
  bg.querySelector('#dsp-fechar').addEventListener('click', () => bg.remove());
  bg.addEventListener('click', e => { if (e.target === bg) bg.remove(); });
  _pintarDespesas();
}

function _despMesRotulo(mes) {
  const [a, m] = String(mes).split('-').map(Number);
  const d = new Date(Date.UTC(a, m - 1, 1));
  const nome = d.toLocaleDateString(_appLocale(), { month: 'long', timeZone: 'UTC' });
  return nome.charAt(0).toUpperCase() + nome.slice(1) + ' ' + a;
}

function _despMover(passo) {
  const [a, m] = _despMes.split('-').map(Number);
  const t = (m - 1) + passo;
  const ano = a + Math.floor(t / 12);
  const mes = ((t % 12) + 12) % 12;
  _despMes = ano + '-' + String(mes + 1).padStart(2, '0');
  _pintarDespesas();
}

function _pintarDespesas() {
  const host = document.getElementById('dsp-corpo');
  if (!host) return;
  const mes = _despMes;
  const lista = _despesasDoMes(mes).slice()
    .sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : 0));
  const saiu = _despesaTotalDoMes(mes);
  const entrou = _receitaRecebidaNoMes(mes);
  const sobrou = entrou - saiu;

  /* Por categoria, do maior para o menor. É a pergunta seguinte a "quanto
     saiu": onde. Uma lista de lançamentos em ordem de data não responde. */
  const porCat = {};
  lista.forEach(d => { porCat[d.categoria] = (porCat[d.categoria] || 0) + (Number(d.valor) || 0); });
  const cats = Object.keys(porCat).sort((a, b) => porCat[b] - porCat[a]);
  const maiorCat = Math.max(1, ...cats.map(c => porCat[c]));

  host.innerHTML = `
    <div class="dsp-mes">
      <button class="dsp-nav" id="dsp-ant" aria-label="${
        sanitizeAttr(_appText('app.prevMonth', 'Mês anterior'))}">‹</button>
      <b>${xe(_despMesRotulo(mes))}</b>
      <button class="dsp-nav" id="dsp-prox" aria-label="${
        sanitizeAttr(_appText('app.nextMonth', 'Próximo mês'))}">›</button>
    </div>

    <div class="flx-kpis">
      <div><span>${xe(_appText('app.expIn', 'ENTROU'))}</span>
        <b>${xe(fmtBRL(entrou))}</b></div>
      <div><span>${xe(_appText('app.expOut', 'SAIU'))}</span>
        <b class="flx-vermelho">${xe(fmtBRL(saiu))}</b></div>
      <div><span>${xe(_appText('app.expLeft', 'SOBROU'))}</span>
        <b class="${sobrou < 0 ? 'flx-vermelho' : 'dsp-verde'}">${xe(fmtBRL(sobrou))}</b></div>
      <div><span>${xe(_appText('app.expMargin', 'MARGEM'))}</span>
        <b class="${sobrou < 0 ? 'flx-vermelho' : ''}">${
          entrou > 0 ? xe((sobrou / entrou * 100).toFixed(1).replace('.', ',') + '%') : '—'}</b></div>
    </div>

    ${cats.length ? `<div class="dsp-cats">${cats.map(c => `
      <div class="dsp-cat">
        <span class="dsp-cat-nome">${xe(_despesaCategoria(c))}</span>
        <span class="dsp-cat-barra"><i style="width:${porCat[c] / maiorCat * 100}%"></i></span>
        <span class="dsp-cat-val">${xe(fmtBRL(porCat[c]))}</span>
      </div>`).join('')}</div>` : ''}

    <div class="dsp-nova">
      <input class="m-inp" id="dsp-desc" maxlength="160"
             placeholder="${sanitizeAttr(_appText('app.expWhat', 'O que foi'))}">
      <input class="m-inp" id="dsp-valor" type="number" min="0" step="0.01"
             placeholder="${sanitizeAttr(_appText('app.expHowMuch', 'Quanto'))}">
      <select class="m-inp" id="dsp-cat">
        ${DESPESA_CATEGORIAS.map(c => `<option value="${c.key}">${
          xe(_appText(c.i18n, c.pt))}</option>`).join('')}
      </select>
      <input class="m-inp" id="dsp-data" type="date" value="${
        xe(mes + '-' + String(Math.min(Number(_crmTodayLocalIso().slice(8)), 28)).padStart(2, '0'))}"
        style="color-scheme:dark;">
      <button class="m-confirm" id="dsp-add">${xe(_appText('app.expAdd', 'Lançar'))}</button>
    </div>

    ${lista.length ? `<div class="dsp-lista">${lista.map(d => `
      <div class="dsp-item" data-id="${sanitizeAttr(d.id)}">
        <span class="dsp-item-data">${xe(_crmFmtDate(d.data))}</span>
        <span class="dsp-item-desc">${xe(d.descricao)}
          ${d.fixa ? `<i>${xe(_appText('app.expFixed', 'fixa'))}</i>` : ''}</span>
        <span class="dsp-item-cat">${xe(_despesaCategoria(d.categoria))}</span>
        <span class="dsp-item-val">${xe(fmtBRL(d.valor))}</span>
        <button class="dsp-x" data-del="${sanitizeAttr(d.id)}"
                aria-label="${sanitizeAttr(_appText('app.delete', 'Excluir'))}">✕</button>
      </div>`).join('')}</div>`
    : `<div class="dsp-vazio">${xe(_appText('app.expEmpty',
        'Nenhuma despesa lançada em {mes}.', { mes: _despMesRotulo(mes) }))}</div>`}`;

  host.querySelector('#dsp-ant').addEventListener('click', () => _despMover(-1));
  host.querySelector('#dsp-prox').addEventListener('click', () => _despMover(1));
  host.querySelector('#dsp-add').addEventListener('click', async () => {
    const criada = await criarDespesa({
      descricao: host.querySelector('#dsp-desc').value,
      valor: parseFloat(host.querySelector('#dsp-valor').value) || 0,
      categoria: host.querySelector('#dsp-cat').value,
      data: host.querySelector('#dsp-data').value,
    });
    if (criada) _pintarDespesas();
  });
  host.querySelectorAll('[data-del]').forEach(b => {
    b.addEventListener('click', async () => {
      if (await excluirDespesa(b.dataset.del)) _pintarDespesas();
    });
  });
}

/* ═══════════════════════════════════════════════════════════════════
   FLUXO DE CAIXA PROJETADO
   ═══════════════════════════════════════════════════════════════════
   "A receber" era um número só: R$ 48.200. Ele responde "quanto me devem"
   e não responde a pergunta que se faz de verdade — "dá para pagar as
   contas em setembro?". Dois clientes de R$ 24 mil vencendo em novembro e
   dois vencendo semana que vem dão o mesmo número e são situações opostas.

   O QUE JÁ VENCEU ENTRA NA PRIMEIRA COLUNA, e não some da conta. Uma
   projeção que só olha para a frente é otimista por construção: esquece
   justamente o dinheiro que está mais difícil de entrar.

   E É PROJEÇÃO, não previsão. O app não sabe quem vai pagar — sabe o que
   está combinado. A diferença aparece na tela, escrita, porque quem lê um
   gráfico de barras assume que o número vai acontecer.
   ═══════════════════════════════════════════════════════════════════ */

/* ── EM QUE PASSO OLHAR O CAIXA ─────────────────────────────────────────
   Doze semanas fixas respondiam bem a uma pergunta só: "as próximas semanas
   apertam?". Quem tem contrato de dois anos precisa da outra — "como fica o
   ano que vem?" — e ali a semana é ruído: cem colunas de uma semana cada não
   se leem, e o que se quer ver é a curva.

   O passo é escolhido, e o alcance vem junto: mês a mês por um ano, trimestre
   a trimestre por três. Não é o mesmo gráfico esticado — é a mesma pergunta
   feita na escala em que ela faz sentido. */
const FLUXO_PASSOS = [
  { key: 'semanal',    i18n: 'app.cashStepWeek',    pt: 'Semanal',    n: 12, dias: 7 },
  { key: 'mensal',     i18n: 'app.cashStepMonth',   pt: 'Mensal',     n: 12, meses: 1 },
  { key: 'bimestral',  i18n: 'app.cashStepBiMonth', pt: 'Bimestral',  n: 12, meses: 2 },
  { key: 'trimestral', i18n: 'app.cashStepQuarter', pt: 'Trimestral', n: 12, meses: 3 },
  { key: 'semestral',  i18n: 'app.cashStepHalf',    pt: 'Semestral',  n: 10, meses: 6 },
  { key: 'anual',      i18n: 'app.cashStepYear',    pt: 'Anual',      n: 8,  meses: 12 },
];
let _fluxoPasso = 'mensal';
const FLUXO_SEMANAS = 12;

/* Segunda-feira da semana de uma data aaaa-mm-dd. Tudo em texto: o Date de
   uma string sem hora nasce em UTC e no Brasil recua um dia — a última
   segunda cairia no domingo anterior. */
function _fluxoSegundaDe(iso) {
  const [a, m, d] = String(iso).split('-').map(Number);
  if (!a) return '';
  const t = Date.UTC(a, m - 1, d);
  const dow = new Date(t).getUTCDay();          // 0 = domingo
  const recuo = (dow + 6) % 7;                  // segunda = 0
  const dt = new Date(t - recuo * 86400000);
  return [dt.getUTCFullYear(),
    String(dt.getUTCMonth() + 1).padStart(2, '0'),
    String(dt.getUTCDate()).padStart(2, '0')].join('-');
}

function _fluxoMaisDias(iso, n) {
  const [a, m, d] = String(iso).split('-').map(Number);
  const dt = new Date(Date.UTC(a, m - 1, d) + n * 86400000);
  return [dt.getUTCFullYear(),
    String(dt.getUTCMonth() + 1).padStart(2, '0'),
    String(dt.getUTCDate()).padStart(2, '0')].join('-');
}

/* As doze semanas a partir da atual, com o que cada uma tem para receber.
   `vencido` é separado de `aReceber` de propósito: são dinheiros com
   probabilidades diferentes, e somá-los numa barra só faria a primeira
   semana parecer a melhor do trimestre. */
/* Primeiro dia do mês de uma data, em texto. */
function _fluxoPrimeiroDoMes(iso) {
  return String(iso).slice(0, 7) + '-01';
}

/* As faixas do período escolhido. Semanal conta de segunda a domingo; os
   demais vão de primeiro a último dia do mês, porque é assim que se fecha um
   mês — e uma faixa "mensal" que começasse no dia 5 nunca casaria com o que
   o contador chama de agosto. */
function _fluxoFaixas(hoje) {
  const passo = FLUXO_PASSOS.find(p => p.key === _fluxoPasso) || FLUXO_PASSOS[1];
  const faixas = [];
  if (passo.dias) {
    const inicio = _fluxoSegundaDe(hoje);
    for (let i = 0; i < passo.n; i++) {
      const de = _fluxoMaisDias(inicio, i * passo.dias);
      faixas.push({ de, ate: _fluxoMaisDias(de, passo.dias - 1) });
    }
    return { faixas, passo };
  }
  const base = _fluxoPrimeiroDoMes(hoje);
  for (let i = 0; i < passo.n; i++) {
    const de = _crmSomarPeriodo(base, 'mensal', i * passo.meses);
    const proxima = _crmSomarPeriodo(base, 'mensal', (i + 1) * passo.meses);
    faixas.push({ de, ate: _fluxoMaisDias(proxima, -1) });
  }
  return { faixas, passo };
}

function _fluxoProjetado() {
  const hoje = _crmTodayLocalIso();
  const { faixas, passo } = _fluxoFaixas(hoje);
  const inicio = faixas[0].de;
  const semanas = faixas.map(f => ({ de: f.de, ate: f.ate, aReceber: 0, vencido: 0, itens: [] }));
  const fim = semanas[semanas.length - 1].ate;

  let semData = 0, depois = 0;
  _registrosFinanceiros().forEach(r => {
    const falta = _crmAReceber(r);
    if (falta <= 0) return;
    const venc = /^\d{4}-\d{2}-\d{2}$/.test(String(r.dueDate || '')) ? r.dueDate : '';
    /* Sem vencimento não é zero: é dinheiro que ninguém sabe quando entra, e
       esconder isso faria a soma das barras não bater com "a receber". */
    if (!venc) { semData += falta; return; }
    if (venc > fim) { depois += falta; return; }
    /* O que venceu antes desta semana cai na primeira coluna: some da conta
       seria fingir que não existe. */
    const alvo = venc < inicio ? semanas[0]
      : semanas.find(s => venc >= s.de && venc <= s.ate);
    if (!alvo) return;
    if (venc < hoje) alvo.vencido += falta; else alvo.aReceber += falta;
    alvo.itens.push({ nome: r.name || '—', valor: falta, venc, atrasado: venc < hoje });
  });

  let acumulado = 0;
  semanas.forEach(s => { acumulado += s.aReceber + s.vencido; s.acumulado = acumulado; });

  return { semanas, semData, depois, total: acumulado, inicio, fim, passo };
}

/* O rótulo muda com o passo: dia/mês numa semana, mês/ano num mês, e só o
   ano quando a coluna é o ano inteiro. Repetir "01/01–31/12" em oito colunas
   seria escrever muito para dizer pouco. */
function _fluxoRotuloSemana(s) {
  const dia = iso => String(iso).slice(8) + '/' + String(iso).slice(5, 7);
  const mesCurto = iso => {
    const [a, m] = String(iso).split('-').map(Number);
    const d = new Date(Date.UTC(a, m - 1, 1));
    return d.toLocaleDateString(_appLocale(), { month: 'short', timeZone: 'UTC' })
      .replace(/\.$/, '');
  };
  if (_fluxoPasso === 'semanal') return dia(s.de) + '–' + dia(s.ate);
  if (_fluxoPasso === 'anual') return String(s.de).slice(0, 4);
  if (_fluxoPasso === 'mensal') return mesCurto(s.de) + '/' + String(s.de).slice(2, 4);
  return mesCurto(s.de) + '–' + mesCurto(s.ate) + '/' + String(s.ate).slice(2, 4);
}

function crmAbrirFluxo() {
  if (!_registrosFinanceiros().length) {
    toast('ℹ️', _appText('app.addClientsFirst', 'Cadastre clientes antes de gerar o relatório.'));
    return;
  }
  document.querySelector('.flx-bg')?.remove();
  const bg = document.createElement('div');
  bg.className = 'modal-bg flx-bg';
  bg.innerHTML = `
    <div class="modal flx-modal">
      <div class="flx-cab">
        <div>
          <div class="m-h1">${xe(_appText('app.cashTitle', 'Fluxo de caixa projetado'))}</div>
          <div class="m-sub">${xe(_appText('app.cashSubGeneric',
            'O que está combinado para entrar, no passo que você escolher.'))}</div>
        </div>
        <button class="flx-x" id="flx-fechar"
                aria-label="${sanitizeAttr(_appText('common.close', 'Fechar'))}">✕</button>
      </div>
      <div class="flx-passos" id="flx-passos">
        ${FLUXO_PASSOS.map(p => `<button type="button" data-passo="${p.key}"${
          p.key === _fluxoPasso ? ' class="sel"' : ''}>${
          xe(_appText(p.i18n, p.pt))}</button>`).join('')}
      </div>
      <div id="flx-corpo"></div>
    </div>`;
  document.body.appendChild(bg);
  bg.querySelectorAll('[data-passo]').forEach(b => {
    b.addEventListener('click', () => {
      _fluxoPasso = b.dataset.passo;
      bg.querySelectorAll('[data-passo]').forEach(x =>
        x.classList.toggle('sel', x.dataset.passo === _fluxoPasso));
      _pintarFluxo();
    });
  });
  bg.querySelector('#flx-fechar').addEventListener('click', () => bg.remove());
  bg.addEventListener('click', e => { if (e.target === bg) bg.remove(); });
  _pintarFluxo();
}

function _pintarFluxo() {
  const host = document.getElementById('flx-corpo');
  if (!host) return;
  const d = _fluxoProjetado();
  const maior = Math.max(1, ...d.semanas.map(s => s.aReceber + s.vencido));

  const barras = d.semanas.map((s, i) => {
    const soma = s.aReceber + s.vencido;
    const hV = (s.vencido / maior) * 100;
    const hR = (s.aReceber / maior) * 100;
    return `
      <div class="flx-col" title="${sanitizeAttr(_fluxoRotuloSemana(s) + ' · ' + fmtBRL(soma))}">
        <div class="flx-val">${soma > 0 ? xe(_crmValorCurto(soma)) : ''}</div>
        <div class="flx-pilha">
          ${hR > 0 ? `<span class="flx-b flx-b-receber" style="height:${hR}%"></span>` : ''}
          ${hV > 0 ? `<span class="flx-b flx-b-vencido" style="height:${hV}%"></span>` : ''}
        </div>
        <div class="flx-rot${i === 0 ? ' agora' : ''}">${xe(_fluxoRotuloSemana(s))}</div>
      </div>`;
  }).join('');

  /* Semana vazia é informação, e não ausência dela: doze semanas com barra
     em três é o retrato de um caixa que depende de poucos meses. */
  const vazias = d.semanas.filter(s => s.aReceber + s.vencido === 0).length;

  host.innerHTML = `
    <div class="flx-kpis">
      <div><span>${xe(_appText('app.cashInRange', 'NO PERÍODO'))}</span>
        <b>${xe(fmtBRL(d.total))}</b></div>
      <div><span>${xe(_appText('app.cashLate', 'JÁ VENCIDO'))}</span>
        <b class="flx-vermelho">${xe(fmtBRL(d.semanas.reduce((t, s) => t + s.vencido, 0)))}</b></div>
      <div><span>${xe(_appText('app.cashNoDate', 'SEM VENCIMENTO'))}</span>
        <b>${xe(fmtBRL(d.semData))}</b></div>
      <div><span>${xe(_appText('app.cashAfter', 'DEPOIS'))}</span>
        <b>${xe(fmtBRL(d.depois))}</b></div>
    </div>

    <div class="flx-grafico">${barras}</div>

    <div class="flx-legenda">
      <span><i class="flx-b-receber"></i>${xe(_appText('app.cashToCome', 'A receber'))}</span>
      <span><i class="flx-b-vencido"></i>${xe(_appText('app.cashOverdue', 'Vencido e não pago'))}</span>
    </div>

    <div class="flx-notas">
      ${vazias ? `<p>${xe(_appText('app.cashEmptyRanges',
        '{n} de {total} colunas não têm nada combinado para entrar.',
        { n: vazias, total: d.semanas.length }))}</p>` : ''}
      ${d.semData > 0 ? `<p>${xe(_appText('app.cashNoDateNote',
        '{valor} não têm data de vencimento e por isso não aparecem em semana nenhuma.',
        { valor: fmtBRL(d.semData) }))}</p>` : ''}
      <p class="flx-aviso">${xe(_appText('app.cashDisclaimer',
        'Isto é o que está combinado, não o que vai acontecer: o app não sabe quem vai pagar.'))}</p>
    </div>`;
}

/* Valor curto para o topo da barra: "R$ 12,4 mil" cabe onde o valor cheio
   não cabe, e numa coluna de 40px o número inteiro vira borrão. */
function _crmValorCurto(v) {
  const n = Math.abs(Number(v) || 0);
  if (n >= 1e6) return 'R$ ' + (Math.round(n / 1e5) / 10).toString().replace('.', ',') + ' mi';
  if (n >= 1e3) return 'R$ ' + (Math.round(n / 100) / 10).toString().replace('.', ',') + ' mil';
  return 'R$ ' + Math.round(n);
}

/* ═══════════════════════════════════════════════════════════════════
   RECORRÊNCIA — O CONTRATO QUE SE REPETE
   ═══════════════════════════════════════════════════════════════════
   Um cliente de mensalidade obrigava a criar doze registros à mão, um por
   mês, cada um com o vencimento certo. Quem não fazia isso punha o contrato
   inteiro num registro só — e aí a taxa de recebimento passava a mentir: um
   contrato anual de R$ 12.000 aparecia como R$ 12.000 "a receber" no mês em
   que foi assinado, e o mês seguinte nascia vazio.

   As parcelas são REGISTROS DE VERDADE, e não uma regra que o app expande na
   hora de mostrar. Cada uma vence, atrasa, recebe pagamento parcial, gera
   recibo e entra no relatório como qualquer outra — porque é isso que elas
   são no mundo. Uma "regra" seria menos linhas aqui e um monte de exceções
   em todo lugar que lê dinheiro.

   O TETO É 60. Não é limite de negócio: é trava contra o dedo escorregar na
   data e o app criar oitocentos registros que alguém vai apagar um por um.
   ═══════════════════════════════════════════════════════════════════ */

const RECORRENCIA_MAX = 60;
function _repeatLabel(tipo) {
  const o = RECORRENCIA_OPCOES.find(x => x.key === tipo);
  return o ? _appText(o.i18n, o.pt) : String(tipo || '');
}
const RECORRENCIA_OPCOES = [
  { key: '', i18n: 'app.repeatNone', pt: 'Não se repete' },
  { key: 'semanal', i18n: 'app.repeatWeekly', pt: 'Toda semana' },
  { key: 'quinzenal', i18n: 'app.repeatBiweekly', pt: 'A cada 15 dias' },
  { key: 'mensal', i18n: 'app.repeatMonthly', pt: 'Todo mês' },
  { key: 'bimestral', i18n: 'app.repeatBimonthly', pt: 'A cada 2 meses' },
  { key: 'trimestral', i18n: 'app.repeatQuarterly', pt: 'A cada 3 meses' },
  { key: 'anual', i18n: 'app.repeatYearly', pt: 'Todo ano' },
];

/* Soma um período a uma data aaaa-mm-dd, em texto. Sem `new Date(iso)`: ele
   nasce em UTC e no Brasil recua um dia — a segunda parcela cairia no dia 30
   quando a primeira foi no 31.

   O DIA DO MÊS É PRESERVADO. Vencimento no dia 31 em mês de 30 cai no último
   dia daquele mês, e não escorrega para o dia 1 do seguinte: quem combinou
   "todo dia 31" não combinou "todo dia 1". */
function _crmSomarPeriodo(iso, tipo, n) {
  const [a, m, d] = String(iso).split('-').map(Number);
  if (!a || !m || !d) return '';
  if (tipo === 'semanal' || tipo === 'quinzenal') {
    const passo = tipo === 'semanal' ? 7 : 15;
    const t = Date.UTC(a, m - 1, d) + passo * n * 86400000;
    const dt = new Date(t);
    return [dt.getUTCFullYear(),
      String(dt.getUTCMonth() + 1).padStart(2, '0'),
      String(dt.getUTCDate()).padStart(2, '0')].join('-');
  }
  const meses = tipo === 'mensal' ? 1 : tipo === 'bimestral' ? 2
    : tipo === 'trimestral' ? 3 : tipo === 'anual' ? 12 : 0;
  if (!meses) return '';
  const total = (m - 1) + meses * n;
  const ano = a + Math.floor(total / 12);
  const mes = ((total % 12) + 12) % 12;
  const ultimoDia = new Date(Date.UTC(ano, mes + 1, 0)).getUTCDate();
  return [ano, String(mes + 1).padStart(2, '0'),
    String(Math.min(d, ultimoDia)).padStart(2, '0')].join('-');
}

/* Quantas parcelas cabem entre a primeira e o fim, incluindo as duas pontas. */
function _crmContarParcelas(inicio, fim, tipo) {
  if (!inicio || !fim || !tipo || fim < inicio) return 0;
  let n = 0;
  while (n < RECORRENCIA_MAX) {
    const d = _crmSomarPeriodo(inicio, tipo, n);
    if (!d || d > fim) break;
    n++;
  }
  return n;
}

/* Cria as parcelas 2..N a partir de um registro que já existe. A primeira é o
   próprio registro — ela já foi salva pelo caminho normal, com tudo o que a
   pessoa preencheu, e recriá-la aqui seria manter dois lugares que montam a
   mesma coisa. */
async function _crmGerarParcelas(base, tipo, ate) {
  const total = _crmContarParcelas(base.dueDate, ate, tipo);
  if (total < 2) return 0;

  const serieId = 'ser_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  await updateRecord(base.id, {
    serieId, serieTipo: tipo, serieAte: ate, serieN: 1, serieDe: total,
  });

  let criadas = 0;
  for (let i = 1; i < total; i++) {
    /* O teto do plano vale para cada parcela. Parar no meio é melhor do que
       recusar tudo: as que couberam são contratos reais e já valem. */
    const pode = _crmCanCreate();
    if (!pode.ok) {
      toast('🔒', _appText('app.repeatHitLimit',
        'Criei {n} de {total} parcelas — o limite do plano foi atingido.',
        { n: criadas + 1, total }));
      break;
    }
    const nova = await createRecord({
      name: base.name, email: base.email, phone: base.phone, cpf: base.cpf,
      description: base.description, color: base.color,
      value: Number(base.value) || 0,
      /* Cada parcela nasce EM ABERTO. Copiar o status da primeira faria doze
         meses nascerem pagos porque a entrada foi quitada. */
      status: 'pending', paidAmount: 0,
      dueDate: _crmSomarPeriodo(base.dueDate, tipo, i),
      template: base.template || '', campos: base.campos || {},
      serieId, serieTipo: tipo, serieAte: ate, serieN: i + 1, serieDe: total,
    });
    if (!nova) break;
    criadas++;
  }
  return criadas;
}

/* Todas as parcelas de uma série que ainda não venceram nem foram pagas —
   é o que faz sentido apagar quando um contrato é cancelado no meio. */
function _crmParcelasDaSerie(serieId, apartirDe) {
  if (!serieId) return [];
  return _records.filter(r => r.serieId === serieId &&
    (!apartirDe || Number(r.serieN || 0) >= apartirDe));
}

/* ═══════════════════════════════════════════════════════════════════
   COBRAR — O AVISO QUE O APP JÁ SABIA FAZER E NÃO FAZIA
   ═══════════════════════════════════════════════════════════════════
   O MyDesk sabe quem deve, quanto, desde quando e há quantos dias. Isso
   aparecia na tabela, no painel e no relatório — e morria ali. Quem cobra
   ainda precisava abrir o e-mail, procurar o cliente, lembrar o valor,
   conferir a data e escrever tudo à mão, uma vez por devedor. É o trabalho
   que um financeiro existe para tirar da mesa.

   O TEXTO É FIRME E EDUCADO, e não um pedido de desculpas nem uma ameaça.
   Uma cobrança que se desculpa por existir não é levada a sério; uma que
   ameaça queima o cliente por uma fatura. O que ela faz é dizer o que está
   em aberto, desde quando, e para onde pagar — e deixa o resto para a
   pessoa escrever no recado, quando quiser.

   NÃO EXISTE COBRANÇA AUTOMÁTICA aqui, e é decisão, não falta de tempo:
   mandar e-mail sozinho para o cliente de alguém é o tipo de recurso que,
   no dia em que erra, erra em nome de quem confiou no app. Cada envio sai
   de um clique.
   ═══════════════════════════════════════════════════════════════════ */

/* Dias de atraso de um registro, ou 0 quando ainda está no prazo. Data em
   texto, sem passar por fuso: `new Date('2026-08-04')` nasce em UTC e no
   Brasil recua um dia — um vencimento de hoje apareceria como atrasado. */
function _crmDiasDeAtraso(rec) {
  const venc = String(rec && rec.dueDate || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(venc)) return 0;
  const hoje = _crmTodayLocalIso();
  if (venc >= hoje) return 0;
  const p = s => { const [a, m, d] = s.split('-').map(Number); return Date.UTC(a, m - 1, d); };
  return Math.round((p(hoje) - p(venc)) / 86400000);
}

/* O texto da cobrança, pronto para copiar ou para virar corpo de e-mail.
   Sai do MESMO lugar nos dois casos: um texto na tela e outro no e-mail
   seria a pessoa mandar uma coisa achando que mandou outra. */
function _crmTextoDaCobranca(rec, recado) {
  const falta = _crmAReceber(rec);
  const dias = _crmDiasDeAtraso(rec);
  const recebido = _crmRecebido(rec);
  const linhas = [];

  linhas.push(_appText('app.dunHi', 'Olá, {nome}!', { nome: rec.name || '' }));
  linhas.push('');
  if (dias > 0) {
    linhas.push(_appText('app.dunOverdue',
      'Passando para lembrar de {valor}, com vencimento em {data} — {dias} dias atrás.',
      { valor: fmtBRL(falta), data: _crmFmtDate(rec.dueDate), dias }));
  } else if (rec.dueDate) {
    linhas.push(_appText('app.dunDue',
      'Passando para lembrar de {valor}, com vencimento em {data}.',
      { valor: fmtBRL(falta), data: _crmFmtDate(rec.dueDate) }));
  } else {
    linhas.push(_appText('app.dunNoDate',
      'Passando para lembrar de {valor}, ainda em aberto.', { valor: fmtBRL(falta) }));
  }
  /* Quando já entrou parte, o texto DIZ isso. Cobrar o valor cheio de quem
     já pagou metade é o erro que faz o cliente parar de responder. */
  if (recebido > 0) {
    linhas.push(_appText('app.dunPartial',
      'Deste contrato de {total}, já recebemos {pago} — resta o valor acima.',
      { total: fmtBRL(Number(rec.value) || 0), pago: fmtBRL(recebido) }));
  }
  if (rec.description) {
    linhas.push(_appText('app.dunAbout', 'Referente a: {ref}', { ref: rec.description }));
  }
  if (String(recado || '').trim()) {
    linhas.push('');
    linhas.push(String(recado).trim());
  }
  linhas.push('');
  linhas.push(_appText('app.dunClose',
    'Se já tiver sido pago, é só desconsiderar e me avisar. Qualquer dúvida, estou à disposição.'));
  return linhas.join('\n');
}

async function crmCobrarCliente(recId) {
  const rec = _records.find(r => r.id === recId);
  if (!rec) { toast('⚠', _appText('app.recordNotFound', 'Registro não encontrado.')); return; }

  const falta = _crmAReceber(rec);
  if (falta <= 0) {
    /* Nada em aberto não é erro: é a resposta. Abrir uma janela de cobrança
       para quem já pagou seria oferecer o caminho de um constrangimento. */
    toast('✅', _appText('app.dunNothingDue',
      '{nome} não tem valor em aberto.', { nome: rec.name || '—' }));
    return;
  }

  const dias = _crmDiasDeAtraso(rec);
  const jaCobrado = String(rec.cobradoEm || '');
  document.querySelector('.cob-bg')?.remove();
  const bg = document.createElement('div');
  bg.className = 'modal-bg cob-bg';
  bg.innerHTML = `
    <div class="modal cob-modal">
      <div class="m-h1">${xe(_appText('app.dunTitle', 'Cobrar {nome}', { nome: rec.name || '—' }))}</div>
      <div class="m-sub">${xe(dias > 0
        ? _appText('app.dunSubOverdue', 'Em aberto há {dias} dias.', { dias })
        : _appText('app.dunSubOnTime', 'Ainda dentro do prazo — este é um lembrete.'))}</div>

      <div class="cob-resumo">
        <div><span>${xe(_appText('app.dunAmount', 'EM ABERTO'))}</span><b>${xe(fmtBRL(falta))}</b></div>
        <div><span>${xe(_appText('app.dunDueDate', 'VENCIMENTO'))}</span><b>${
          xe(rec.dueDate ? _crmFmtDate(rec.dueDate) : _appText('app.noDate', 'Sem data'))}</b></div>
        <div><span>${xe(_appText('app.dunTo', 'PARA'))}</span><b>${
          xe(rec.email || _appText('app.dunNoEmailShort', 'sem e-mail na ficha'))}</b></div>
      </div>

      ${jaCobrado ? `<div class="cob-aviso">${xe(_appText('app.dunLastSent',
        'A última cobrança deste registro saiu em {data}.',
        { data: _crmFmtDate(jaCobrado) }))}</div>` : ''}

      <!-- O e-mail se preenche aqui, como no recibo: mandar a pessoa sair da
           tela para preencher a ficha e voltar é transformar um campo que
           falta em quatro cliques. O que for digitado é gravado na ficha. -->
      <div><div class="m-lbl">${xe(_appText('app.dunClientEmail', 'E-mail do cliente'))}</div>
        <input class="m-inp" id="cob-email" type="email" maxlength="160"
          value="${sanitizeAttr(rec.email || '')}"></div>

      <div><div class="m-lbl">${xe(_appText('app.dunNote', 'Recado (opcional)'))}</div>
        <textarea class="m-inp" id="cob-recado" rows="2" maxlength="600"
          placeholder="${sanitizeAttr(_appText('app.dunNotePh',
            'ex.: combinamos o pagamento para esta semana — consegue confirmar?'))}"></textarea></div>

      <div class="m-lbl" style="margin-top:12px">${
        xe(_appText('app.dunPreview', 'O que vai ser enviado'))}</div>
      <pre class="cob-previa" id="cob-previa"></pre>

      <div class="campo-erro" id="cob-erro"></div>
      <!-- As classes sao as do resto dos modais (m-btns/m-cancel/m-confirm).
           Inventar nomes novos aqui foi o que deixou os tres botoes crus na
           tela: sem regra de CSS, o navegador desenha o botao padrao dele. -->
      <div class="m-btns">
        <button class="m-cancel" id="cob-cancelar">${
          xe(_appText('common.cancel', 'Cancelar'))}</button>
        <button class="m-cancel" id="cob-copiar">${
          xe(_appText('app.dunCopy', 'Copiar o texto'))}</button>
        <button class="m-confirm" id="cob-enviar">${
          xe(_appText('app.dunSend', 'Enviar por e-mail'))}</button>
      </div>
    </div>`;
  document.body.appendChild(bg);

  const fechar = () => bg.remove();
  bg.querySelector('#cob-cancelar').addEventListener('click', fechar);
  bg.addEventListener('click', e => { if (e.target === bg) fechar(); });

  const erro = bg.querySelector('#cob-erro');
  const previa = bg.querySelector('#cob-previa');
  const recado = bg.querySelector('#cob-recado');
  const campoEmail = bg.querySelector('#cob-email');
  /* A prévia acompanha o recado enquanto se digita: quem manda uma cobrança
     quer LER a cobrança antes, e não descobrir o texto depois de enviado. */
  const repintar = () => { previa.textContent = _crmTextoDaCobranca(rec, recado.value); };
  recado.addEventListener('input', repintar);
  repintar();

  bg.querySelector('#cob-copiar').addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(_crmTextoDaCobranca(rec, recado.value));
      toast('📋', _appText('app.dunCopied', 'Texto copiado.'));
    } catch (_) {
      erro.textContent = _appText('app.dunCopyFailed',
        'O navegador não deixou copiar. Selecione o texto acima e copie à mão.');
    }
  });

  bg.querySelector('#cob-enviar').addEventListener('click', async () => {
    const email = campoEmail.value.trim();
    if (!/^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(email)) {
      erro.textContent = _appText('app.dunCheckEmail', 'Confira o e-mail do cliente.');
      campoEmail.focus();
      return;
    }
    if (email !== String(rec.email || '').trim()) {
      await updateRecord(rec.id, { email });
    }
    const btn = bg.querySelector('#cob-enviar');
    btn.disabled = true;
    btn.textContent = _appText('app.sending', 'Enviando…');
    try {
      await crmEnviarCobrancaPorEmail(rec.id, recado.value);
      /* A data fica na ficha: sem ela, ninguém sabe se já cobrou — e cobrar
         a mesma pessoa duas vezes no mesmo dia é o que faz um cliente bom
         deixar de responder. */
      await updateRecord(rec.id, { cobradoEm: _crmTodayLocalIso() });
      fechar();
      toast('✉️', _appText('app.dunSent', 'Cobrança enviada para {email}.', { email }));
    } catch (e) {
      erro.textContent = e && e.message
        ? e.message : _appText('app.dunFailed', 'Não consegui enviar agora.');
      btn.disabled = false;
      btn.textContent = _appText('app.dunSend', 'Enviar por e-mail');
    }
  });
}

async function crmEnviarCobrancaPorEmail(recId, recado) {
  const fbUser = window._fbAuth?.currentUser;
  if (!fbUser) throw new Error(_appText('app.signInFirst', 'Faça login primeiro.'));
  const resp = await fetch(VERCEL_API + '/api/form', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json',
               'Authorization': 'Bearer ' + await fbUser.getIdToken() },
    body: JSON.stringify({
      acao: 'cobrarCliente',
      cliente: recId,
      destino: _fmCrmDestinoAtual(),
      idioma: _appLocale().slice(0, 2),
      recado: String(recado || '').slice(0, 600),
    }),
  });
  const r = await resp.json().catch(() => ({}));
  if (!resp.ok) throw new Error(r.error || _appText('app.dunFailed',
    'Não consegui enviar agora.'));
  return true;
}

/* ═══════════════════════════════════════════════════════════════════
   O RELATÓRIO EM POWERPOINT
   ═══════════════════════════════════════════════════════════════════
   As contas saem de `_relatorioDados()` — as MESMAS do relatório na tela e
   do PDF. Não existe uma segunda apuração aqui: dois cálculos para o mesmo
   número acabam divergindo, e ninguém percebe até alguém comparar dois
   documentos numa reunião.

   O que este bloco acrescenta são recortes que a apresentação pede e o PDF
   não tinha: a idade da inadimplência, a concentração da carteira, os
   vencimentos das próximas semanas e a entrada de clientes por mês.
   ═══════════════════════════════════════════════════════════════════ */

/* Número curto para eixo de gráfico. "R$ 1.240.000,00" num rótulo de régua
   ocupa mais espaço que a barra que ele mede. */
function _pptCurto(v) {
  const n = Math.abs(Number(v) || 0);
  const sinal = (Number(v) || 0) < 0 ? '-' : '';
  const corta = (x, suf) => sinal + 'R$ ' +
    (Math.round(x * 10) / 10).toString().replace('.', ',') + suf;
  if (n >= 1e6) return corta(n / 1e6, ' mi');
  if (n >= 1e3) return corta(n / 1e3, ' mil');
  return sinal + 'R$ ' + Math.round(n);
}

/* Dias entre duas datas em aaaa-mm-dd, sem passar por fuso: o Date de uma
   string sem hora nasce em UTC e no Brasil recua um dia. */
function _pptDias(deIso, ateIso) {
  const p = s => { const [a, m, d] = String(s).split('-').map(Number); return Date.UTC(a, m - 1, d); };
  return Math.round((p(ateIso) - p(deIso)) / 86400000);
}

function _relatorioExtras(d) {
  const hojeIso = _crmTodayLocalIso();
  const financeiros = _registrosFinanceiros();

  /* ── Composição: cada real da carteira em UM estado só ────────────────
     Um registro parcial entra nos dois lados — o que entrou em "recebido",
     o que falta em "em aberto" ou "atrasado". Somar o valor cheio num balde
     só inflaria um deles, e foi o que já fez a taxa de recebimento mentir. */
  let recebido = 0, parcialAberto = 0, aberto = 0, vencido = 0;
  let nPago = 0, nParcial = 0, nAberto = 0, nVencido = 0;
  financeiros.forEach(r => {
    const pago = _crmRecebido(r), falta = _crmAReceber(r);
    recebido += pago;
    if (r.status === 'paid') nPago++;
    else if (r.status === 'partial') nParcial++;
    if (falta > 0) {
      if (d.atrasadoQ(r)) { vencido += falta; nVencido++; }
      else if (r.status === 'partial') { parcialAberto += falta; }
      else { aberto += falta; nAberto++; }
    }
  });

  /* ── Idade da inadimplência ───────────────────────────────────────────
     "R$ 12 mil atrasados" e "R$ 12 mil atrasados há mais de noventa dias"
     são situações diferentes, e a primeira frase esconde a segunda. */
  const faixas = [
    { rot: _appText('app.aging30', 'até 30 dias'), lim: 30, valor: 0, n: 0, cor: 'E0A33C' },
    { rot: _appText('app.aging60', '31 a 60 dias'), lim: 60, valor: 0, n: 0, cor: 'D08A2E' },
    { rot: _appText('app.aging90', '61 a 90 dias'), lim: 90, valor: 0, n: 0, cor: 'C25A32' },
    { rot: _appText('app.aging90mais', 'mais de 90 dias'), lim: Infinity, valor: 0, n: 0, cor: 'B3261E' },
  ];
  let pior = null;
  financeiros.forEach(r => {
    if (!d.atrasadoQ(r)) return;
    const falta = _crmAReceber(r);
    if (falta <= 0) return;
    const dias = _pptDias(r.dueDate, hojeIso);
    const faixa = faixas.find(f => dias <= f.lim) || faixas[faixas.length - 1];
    faixa.valor += falta;
    faixa.n++;
    if (!pior || dias > pior.dias) pior = { dias, nome: r.name || '—', valor: falta };
  });

  /* ── Concentração ─────────────────────────────────────────────────────
     Quanto da carteira depende dos cinco maiores. É o número que diz se
     perder um cliente é um susto ou um problema — e nenhum outro indicador
     do relatório responde a isso. */
  const porCliente = [...financeiros]
    .map(r => ({ nome: r.name || '—', valor: Number(r.value) || 0 }))
    .sort((a, b) => b.valor - a.valor);
  const somaTudo = porCliente.reduce((s, x) => s + x.valor, 0);
  const top5 = porCliente.slice(0, 5).reduce((s, x) => s + x.valor, 0);
  const pctTop5 = somaTudo ? Math.round(top5 / somaTudo * 100) : 0;

  /* ── Vencimentos das próximas semanas ─────────────────────────────────
     Inclui o que já venceu e não foi pago: ele continua sendo dinheiro a
     entrar, e some de uma lista que só olha para a frente. */
  const limite = new Date(Date.now() + 45 * 86400000);
  const limiteIso = _crmTodayLocalIso.call(null) && [
    limite.getFullYear(), String(limite.getMonth() + 1).padStart(2, '0'),
    String(limite.getDate()).padStart(2, '0')].join('-');
  const vencimentos = financeiros
    .filter(r => _crmAReceber(r) > 0 && /^\d{4}-\d{2}-\d{2}$/.test(r.dueDate || '')
                 && r.dueDate <= limiteIso)
    .sort((a, b) => a.dueDate < b.dueDate ? -1 : 1)
    .map(r => {
      const dias = _pptDias(hojeIso, r.dueDate);
      return {
        quando: _crmFmtDate(r.dueDate),
        nome: r.name || '—',
        valor: _crmAReceber(r),
        situacao: dias < 0
          ? _appText('app.lateByDays', 'venceu há {n} dias', { n: -dias })
          : dias === 0 ? _appText('app.dueToday', 'vence hoje')
          : _appText('app.dueInDays', 'em {n} dias', { n: dias }),
        cor: dias < 0 ? 'B3261E' : dias <= 7 ? 'C98A04' : '6B6B7B',
      };
    });

  /* ── Entrada de clientes por mês ──────────────────────────────────── */
  const novos = d.meses.map(m => ({ rotulo: m.rotulo, chave: m.chave, n: 0 }));
  financeiros.forEach(r => {
    const t = Number(r.createdAt) || 0;
    if (!t) return;
    const dt = new Date(t);
    const chave = dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0');
    const alvo = novos.find(x => x.chave === chave);
    if (alvo) alvo.n++;
  });

  return {
    recebido, parcialAberto, aberto, vencido,
    nPago, nParcial, nAberto, nVencido,
    faixas, pior, porCliente, somaTudo, pctTop5, vencimentos, novos,
    total: financeiros.length,
  };
}

/* Frases da última página. Cada uma sai de um número que está nas páginas
   anteriores — nenhuma é opinião, e nenhuma existe quando o número que a
   sustenta não existe. Relatório que "conclui" o que não mediu é o que faz
   ninguém confiar no resto. */
function _pptLeitura(d, e) {
  const linhas = [];
  const pct = v => (v * 100).toFixed(1).replace('.', ',') + '%';
  if (d.total > 0) {
    linhas.push({
      titulo: _appText('app.readCollection', 'Recebimento em {pct}', { pct: pct(d.taxa) }),
      texto: _appText('app.readCollectionSub',
        'De {total} em contratos, {pago} entrou e {falta} continua em aberto.',
        { total: fmtBRL(d.total), pago: fmtBRL(d.pago), falta: fmtBRL(d.pendente + d.atrasado) }),
      cor: d.taxa >= 0.8 ? '0F7A52' : d.taxa >= 0.5 ? 'C98A04' : 'B3261E',
    });
  }
  if (d.atrasado > 0) {
    linhas.push({
      titulo: _appText('app.readOverdue', '{n} em atraso, somando {valor}',
        { n: d.nAtraso, valor: fmtBRL(d.atrasado) }),
      texto: e.pior
        ? _appText('app.readOverdueSub',
            'O mais antigo é de {nome}, vencido há {dias} dias.',
            { nome: e.pior.nome, dias: e.pior.dias })
        : '',
      cor: 'B3261E',
    });
  }
  if (e.somaTudo > 0 && e.porCliente.length >= 2) {
    linhas.push({
      titulo: _appText('app.readConcentration', 'Os cinco maiores são {pct} da carteira',
        { pct: e.pctTop5 + '%' }),
      texto: e.pctTop5 >= 60
        ? _appText('app.readConcentrationHigh',
            'Concentração alta: perder um deles muda o mês inteiro.')
        : _appText('app.readConcentrationOk',
            'Carteira distribuída — nenhum cliente sozinho decide o mês.'),
      cor: e.pctTop5 >= 60 ? 'C98A04' : '0F7A52',
    });
  }
  if (e.vencimentos.length) {
    const soma = e.vencimentos.reduce((s, v) => s + v.valor, 0);
    linhas.push({
      titulo: _appText('app.readNext', '{valor} a receber nas próximas semanas',
        { valor: fmtBRL(soma) }),
      texto: _appText('app.readNextSub', '{n} vencimentos até {data}.',
        { n: e.vencimentos.length,
          data: _crmFmtDate(e.vencimentos[e.vencimentos.length - 1].quando) ||
                e.vencimentos[e.vencimentos.length - 1].quando }),
      cor: '4F46E5',
    });
  }
  if (d.ticket > 0) {
    linhas.push({
      titulo: _appText('app.readTicket', 'Ticket médio de {valor}',
        { valor: fmtBRL(d.ticket) }),
      texto: _appText('app.readTicketSub', 'Sobre {n} registros no período.',
        { n: e.total }),
      cor: '6B6B7B',
    });
  }
  return linhas;
}

async function baixarRelatorioCRMemPPTX() {
  if (!hasFullAccess()) {
    toast('⭐', _appText('app.reportPremiumOnly', 'O relatório financeiro é exclusivo do Premium.'));
    if (typeof showPremiumModal === 'function') showPremiumModal();
    return;
  }
  if (!_registrosFinanceiros().length) {
    toast('ℹ️', _appText('app.addClientsFirst', 'Cadastre clientes antes de gerar o relatório.'));
    return;
  }
  if (!window.MD_RELATORIO_PPTX) {
    toast('⚠', _appText('app.pptUnavailable',
      'O gerador de apresentação não carregou. Recarregue a página.'));
    return;
  }

  const d = _relatorioDados();
  const e = _relatorioExtras(d);
  const hojeTxt = _crmFmtDate(_crmTodayLocalIso());

  const dados = {
    titulo: _appText('app.pptTitle', 'Relatório financeiro'),
    subtitulo: (CU && (CU.name || CU.username)) || '',
    periodo: _appText('app.pptPeriod', 'Últimos 6 meses · posição em {data}', { data: hojeTxt }),
    emitido: _appText('app.pptIssued', 'Gerado pelo MyDesk em {data}', { data: hojeTxt }),
    referencia: d.referencia,
    rodape: _appText('app.pptFooter', 'Relatório financeiro · {data}', { data: hojeTxt }),
    fmt: fmtBRL,
    fmtCurto: _pptCurto,
    totalCarteira: fmtBRL(d.total),

    kpis: [
      { rot: _appText('app.pptReceived', 'RECEBIDO'), valor: fmtBRL(d.pago),
        pe: _appText('app.pptOfTotal', '{pct} do total', {
          pct: (d.taxa * 100).toFixed(1).replace('.', ',') + '%' }), cor: '0F7A52' },
      { rot: _appText('app.pptOpen', 'EM ABERTO'), valor: fmtBRL(d.pendente),
        pe: _appText('app.pptOnTime', 'dentro do prazo'), cor: 'C98A04' },
      { rot: _appText('app.pptOverdue', 'EM ATRASO'), valor: fmtBRL(d.atrasado),
        pe: _appText('app.pptOverdueN', '{n} registros', { n: d.nAtraso }), cor: 'B3261E' },
      { rot: _appText('app.pptContracted', 'CONTRATADO'), valor: fmtBRL(d.total),
        pe: _appText('app.pptInPeriod', 'soma da carteira'), cor: '4F46E5' },
      { rot: _appText('app.pptTicket', 'TICKET MÉDIO'), valor: fmtBRL(d.ticket),
        pe: _appText('app.pptPerRecord', 'por registro'), cor: '0E7490' },
      { rot: _appText('app.pptClients', 'REGISTROS'), valor: String(e.total),
        pe: _appText('app.pptClientsSub', 'na carteira'), cor: '6B6B7B' },
    ],
    meses: d.meses,
    composicao: [
      { rot: _appText('app.pptPaid', 'Recebido'), valor: e.recebido, cor: '0F7A52',
        detalhe: _appText('app.pptNPaid', '{n} quitados', { n: e.nPago }) },
      { rot: _appText('app.pptPartialOpen', 'Saldo de parciais'), valor: e.parcialAberto,
        cor: '0E7490',
        detalhe: _appText('app.pptNPartial', '{n} com entrada', { n: e.nParcial }) },
      { rot: _appText('app.pptOpenLabel', 'Em aberto no prazo'), valor: e.aberto,
        cor: 'C98A04',
        detalhe: _appText('app.pptNOpen', '{n} a vencer', { n: e.nAberto }) },
      { rot: _appText('app.pptOverdueLabel', 'Vencido'), valor: e.vencido, cor: 'B3261E',
        detalhe: _appText('app.pptNOverdue', '{n} em atraso', { n: e.nVencido }) },
    ],
    aging: e.faixas.map(f => ({
      rot: f.rot, valor: f.valor, cor: f.cor,
      detalhe: _appText('app.pptNRecords', '{n} registros', { n: f.n }),
    })),
    piorAtraso: e.pior
      ? _appText('app.pptWorst', '{nome} — {valor}, vencido há {dias} dias.',
          { nome: e.pior.nome, valor: fmtBRL(e.pior.valor), dias: e.pior.dias })
      : '',
    maiores: e.porCliente.slice(0, 8).map(c => ({
      nome: c.nome, valor: c.valor,
      pct: e.somaTudo ? (c.valor / e.somaTudo * 100).toFixed(1).replace('.', ',') + '%' : '—',
    })),
    concentracao: e.somaTudo
      ? _appText('app.pptTop5', 'Os cinco maiores clientes somam {pct} de tudo o que foi contratado.',
          { pct: e.pctTop5 + '%' })
      : '',
    vencimentos: e.vencimentos,
    novos: e.novos,
    kpisBase: [
      { rot: _appText('app.pptNewTotal', 'ENTRARAM NO PERÍODO'),
        valor: String(e.novos.reduce((s, m) => s + m.n, 0)),
        pe: _appText('app.pptNewSub', 'registros criados'), cor: '4F46E5', tam: 22 },
      { rot: _appText('app.pptAvgTicket', 'TICKET MÉDIO'), valor: fmtBRL(d.ticket),
        pe: _appText('app.pptPerRecord', 'por registro'), cor: '0E7490', tam: 18 },
    ],
    leitura: _pptLeitura(d, e),
    aviso: _appText('app.pptDisclaimer',
      'Os números saem dos registros cadastrados no MyDesk na data de emissão. Documento de gestão, sem valor contábil ou fiscal.'),
    t: {
      resumo: _appText('app.pptS2', 'Os números do período'),
      resumoSub: _appText('app.pptS2Sub', 'Posição da carteira na data de emissão.'),
      evolucao: _appText('app.pptS3', 'Evolução dos últimos 6 meses'),
      evolucaoSub: _appText('app.pptS3Sub', 'O que foi contratado em cada mês e quanto disso entrou.'),
      faturado: _appText('app.pptContractedLabel', 'Contratado'),
      recebido: _appText('app.pptReceivedLabel', 'Recebido'),
      composicao: _appText('app.pptS4', 'Composição da carteira'),
      composicaoSub: _appText('app.pptS4Sub', 'Cada real em um estado só — parcial entra dos dois lados.'),
      total: _appText('app.pptTotalLabel', 'contratado'),
      atraso: _appText('app.pptS5', 'Inadimplência por idade'),
      atrasoSub: _appText('app.pptS5Sub', 'Há quanto tempo cada real em atraso está parado.'),
      piorAtraso: _appText('app.pptOldest', 'O MAIS ANTIGO'),
      clientes: _appText('app.pptS6', 'Maiores clientes'),
      clientesSub: _appText('app.pptS6Sub', 'Por valor contratado no período.'),
      concentracao: _appText('app.pptConcentrationLabel', 'CONCENTRAÇÃO'),
      vencimentos: _appText('app.pptS7', 'Próximos vencimentos'),
      vencimentosSub: _appText('app.pptS7Sub', 'O que há para entrar nas próximas semanas, e o que já venceu.'),
      colData: _appText('app.pptColDate', 'VENCIMENTO'),
      colCliente: _appText('app.pptColClient', 'CLIENTE'),
      colSituacao: _appText('app.pptColStatus', 'SITUAÇÃO'),
      colValor: _appText('app.pptColValue', 'A RECEBER'),
      semVencimentos: _appText('app.pptNoDue', 'Nenhum vencimento nas próximas semanas.'),
      base: _appText('app.pptS8', 'Base de clientes'),
      baseSub: _appText('app.pptS8Sub', 'Quantos registros entraram em cada mês.'),
      leitura: _appText('app.pptS9', 'Leitura do período'),
      leituraSub: _appText('app.pptS9Sub', 'Cada frase abaixo sai de um número das páginas anteriores.'),
    },
  };

  try {
    const bytes = MD_RELATORIO_PPTX.paraUint8(dados);
    const url = URL.createObjectURL(new Blob([bytes], {
      type: 'application/vnd.openxmlformats-officedocument.presentationml.presentation' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'MyDesk-relatorio-' + _crmTodayLocalIso() + '.pptx';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
    if (window.mdTrack) mdTrack('crm_relatorio_pptx', { clientes: e.total });
    toast('📊', _appText('app.pptDone', 'Apresentação gerada.'));
  } catch (err) {
    console.error('[relatório] pptx:', err);
    toast('❌', _appText('app.pptFailed', 'Não consegui gerar a apresentação.'));
  }
}

/* ═══════════════════════════════════════════════════════════════════
   O MESMO RELATÓRIO, EM PDF
   ═══════════════════════════════════════════════════════════════════ */
function baixarRelatorioCRMemPDF() {
  if (!hasFullAccess()) {
    toast('⭐', _appText('app.reportPremiumOnly', 'O relatório financeiro é exclusivo do Premium.'));
    if (typeof showPremiumModal === 'function') showPremiumModal();
    return;
  }
  if (!_records.length) { toast('ℹ️', _appText('app.addClientsFirst', 'Cadastre clientes antes de gerar o relatório.')); return; }

  const d = _relatorioDados();
  const hex = h => [parseInt(h.slice(1, 3), 16) / 255, parseInt(h.slice(3, 5), 16) / 255, parseInt(h.slice(5, 7), 16) / 255];
  const PAGO = hex(REL_COR.pago), PEND = hex(REL_COR.pendente), ATRA = hex(REL_COR.atraso);
  const PARC = hex(REL_COR.parcial);
  const BARRA = hex(REL_COR.barra), TINTA = hex(REL_COR.tinta), FRACA = hex(REL_COR.fraca);
  const LINHA = hex(REL_COR.linha), ZEBRA = [0.976, 0.976, 0.984];

  const M = 46, DIR = _PDF_L - M, LARG = DIR - M;
  const doc = _pdfNovoDoc();
  let y = 0, pagina = 1;
  const pct = v => d.total ? v / d.total * 100 : 0;

  const rodape = () => {
    doc.linha(M, _PDF_A - 46, DIR, _PDF_A - 46, { cor: LINHA });
    doc.texto(M, _PDF_A - 34, 'Documento gerado automaticamente pelo MyDesk · ' + d.referencia,
              { tam: 7.5, cor: FRACA });
    doc.texto(DIR, _PDF_A - 34, 'Página ' + pagina, { tam: 7.5, cor: FRACA, alinhar: 'dir' });
  };
  const novaFolha = () => { rodape(); doc.novaPagina(); pagina++; y = 58; };

  // ── Masthead ──
  y = 56;
  doc.texto(M, y, 'RELATÓRIO FINANCEIRO', { tam: 7.5, negrito: true, cor: BARRA });
  doc.texto(DIR, y + 2, 'MyDesk', { tam: 13, negrito: true, cor: BARRA, alinhar: 'dir' });
  y += 20;
  doc.texto(M, y, CU?.name || CU?.username || '', { tam: 19, negrito: true, cor: TINTA });
  y += 15;
  doc.texto(M, y, d.hoje.toLocaleDateString(_appLocale(), { day: '2-digit', month: 'long', year: 'numeric' }) +
                  '   ·   ' + _records.length + (_records.length === 1 ? ' cliente' : ' clientes') +
                  '   ·   ' + d.referencia, { tam: 8.5, cor: FRACA });
  y += 10;
  doc.linha(M, y, DIR, y, { cor: TINTA, esp: 1.4 });
  y += 30;

  // ── Hero: total + barra de composição ──
  doc.texto(M, y, 'TOTAL EM CARTEIRA', { tam: 7.5, negrito: true, cor: FRACA });
  y += 26;
  doc.texto(M, y, fmtBRL(d.total), { tam: 27, negrito: true, cor: TINTA });
  y += 16;

  const segs = [
    { v: d.pago, cor: PAGO, rot: 'Recebido' },
    { v: d.pendente, cor: PEND, rot: 'A receber' },
    { v: d.atrasado, cor: ATRA, rot: 'Atrasado' },
  ].filter(s => s.v > 0);
  let x = M;
  segs.forEach((s, i) => {
    // 2pt de folga entre pedaços: sem o vão, dois tons vizinhos se fundem
    const w = (s.v / d.total) * LARG - (i < segs.length - 1 ? 2 : 0);
    doc.retangulo(x, y, Math.max(1, w), 9, { preenche: s.cor });
    x += w + 2;
  });
  y += 24;
  // Rótulo de cada estado: a cor nunca é o único sinal
  let lx = M;
  segs.forEach(s => {
    doc.retangulo(lx, y - 6, 7, 7, { preenche: s.cor });
    doc.texto(lx + 11, y, s.rot, { tam: 8.5, negrito: true, cor: TINTA });
    doc.texto(lx + 11, y + 11, fmtBRL(s.v) + '  ·  ' + pct(s.v).toFixed(0) + '%', { tam: 8.5, cor: FRACA });
    lx += LARG / segs.length;
  });
  y += 34;

  // ── Indicadores ──
  const kpis = [
    ['TAXA DE RECEBIMENTO', (d.taxa * 100).toFixed(0) + '%', ''],
    ['TICKET MÉDIO', fmtBRL(d.ticket), ''],
    ['MAIOR CLIENTE', d.maior ? (d.maior.name || '—') : '—', d.maior ? fmtBRL(Number(d.maior.value) || 0) : ''],
    ['EM ATRASO', String(d.nAtraso), d.nAtraso ? fmtBRL(d.atrasado) : 'nenhum'],
  ];
  const kw = (LARG - 3 * 9) / 4;
  kpis.forEach((k, i) => {
    const kx = M + i * (kw + 9);
    doc.retangulo(kx, y, kw, 52, { preenche: [0.976, 0.976, 0.984] });
    doc.texto(kx + 10, y + 16, k[0], { tam: 6.4, negrito: true, cor: FRACA });
    let val = k[1];
    while (_pdfLargura(val, 12, true) > kw - 20 && val.length > 4) val = val.slice(0, -2);
    if (val !== k[1]) val += '…';
    doc.texto(kx + 10, y + 33, val, { tam: 12, negrito: true, cor: i === 3 && d.nAtraso ? ATRA : TINTA });
    if (k[2]) doc.texto(kx + 10, y + 45, k[2], { tam: 7.5, cor: FRACA });
  });
  y += 78;

  // ── Últimos seis meses ──
  doc.texto(M, y, 'ÚLTIMOS SEIS MESES', { tam: 8, negrito: true, cor: TINTA });
  y += 16;
  const cM = { mes: M, barra: M + 74, prev: DIR - 200, rec: DIR - 100, falta: DIR };
  doc.texto(cM.mes, y, 'MÊS', { tam: 6.6, cor: FRACA });
  doc.texto(cM.barra, y, 'VOLUME', { tam: 6.6, cor: FRACA });
  doc.texto(cM.prev, y, 'PREVISTO', { tam: 6.6, cor: FRACA, alinhar: 'dir' });
  doc.texto(cM.rec, y, 'RECEBIDO', { tam: 6.6, cor: FRACA, alinhar: 'dir' });
  doc.texto(cM.falta, y, 'A RECEBER', { tam: 6.6, cor: FRACA, alinhar: 'dir' });
  y += 6; doc.linha(M, y, DIR, y, { cor: TINTA, esp: 0.9 }); y += 15;

  const larguraBarra = cM.prev - cM.barra - 70;
  d.meses.forEach(m => {
    doc.texto(cM.mes, y, m.rotulo, { tam: 9, cor: TINTA });
    const w = (m.total / d.maiorMes) * larguraBarra;
    if (w > 0.5) doc.retangulo(cM.barra, y - 6, w, 7, { preenche: BARRA });
    doc.texto(cM.prev, y, fmtBRL(m.total), { tam: 9, cor: TINTA, alinhar: 'dir' });
    doc.texto(cM.rec, y, fmtBRL(m.pago), { tam: 9, cor: TINTA, alinhar: 'dir' });
    doc.texto(cM.falta, y, fmtBRL(m.total - m.pago), { tam: 9, cor: TINTA, alinhar: 'dir' });
    y += 7; doc.linha(M, y, DIR, y, { cor: LINHA }); y += 14;
  });
  const somaT = d.meses.reduce((a, m) => a + m.total, 0);
  const somaP = d.meses.reduce((a, m) => a + m.pago, 0);
  doc.texto(cM.mes, y, 'Total do período', { tam: 9, negrito: true, cor: TINTA });
  doc.texto(cM.prev, y, fmtBRL(somaT), { tam: 9, negrito: true, cor: TINTA, alinhar: 'dir' });
  doc.texto(cM.rec, y, fmtBRL(somaP), { tam: 9, negrito: true, cor: TINTA, alinhar: 'dir' });
  doc.texto(cM.falta, y, fmtBRL(somaT - somaP), { tam: 9, negrito: true, cor: TINTA, alinhar: 'dir' });
  y += 40;

  // ── Clientes ──
  const cC = { nome: M, status: M + 240, venc: M + 330, valor: DIR };
  const cabecalho = () => {
    doc.texto(cC.nome, y, 'CLIENTE', { tam: 6.6, cor: FRACA });
    doc.texto(cC.status, y, 'STATUS', { tam: 6.6, cor: FRACA });
    doc.texto(cC.venc, y, 'VENCIMENTO', { tam: 6.6, cor: FRACA });
    doc.texto(cC.valor, y, 'VALOR', { tam: 6.6, cor: FRACA, alinhar: 'dir' });
    y += 6; doc.linha(M, y, DIR, y, { cor: TINTA, esp: 0.9 }); y += 15;
  };
  if (y + 90 > _PDF_A - 70) novaFolha();
  doc.texto(M, y, 'CLIENTES (' + _records.length + ')', { tam: 8, negrito: true, cor: TINTA });
  y += 16;
  cabecalho();

  d.ordenados.forEach((r, i) => {
    if (y + 20 > _PDF_A - 70) { novaFolha(); cabecalho(); }
    if (i % 2 === 1) doc.retangulo(M - 4, y - 10, LARG + 8, 20, { preenche: ZEBRA });
    const pago2 = r.status === 'paid', atras = d.atrasadoQ(r), parc = r.status === 'partial';
    let nome = r.name || '—';
    while (_pdfLargura(nome, 9.5, false) > 220 && nome.length > 4) nome = nome.slice(0, -2);
    if (nome !== (r.name || '—')) nome += '…';
    doc.texto(cC.nome, y, nome, { tam: 9.5, cor: TINTA });
    doc.texto(cC.status, y,
              pago2 ? 'Pago' : atras ? 'Atrasado' : parc ? 'Parcial' : 'Pendente',
              { tam: 8.5, negrito: true,
                cor: pago2 ? PAGO : atras ? ATRA : parc ? PARC : PEND });
    doc.texto(cC.venc, y, r.dueDate ? _crmFmtDate(r.dueDate) : '—', { tam: 9, cor: FRACA });
    doc.texto(cC.valor, y, fmtBRL(Number(r.value) || 0), { tam: 9.5, cor: TINTA, alinhar: 'dir' });
    y += 20;
  });
  doc.linha(M, y - 12, DIR, y - 12, { cor: TINTA, esp: 0.9 });
  doc.texto(cC.nome, y, 'Total', { tam: 10, negrito: true, cor: TINTA });
  doc.texto(cC.valor, y, fmtBRL(d.total), { tam: 10, negrito: true, cor: TINTA, alinhar: 'dir' });

  rodape();
  const nome = 'MyDesk-relatorio-' + d.hoje.toISOString().slice(0, 10) + '.pdf';
  _pdfBaixar(doc.bytes(), nome);
  toast('📄', 'PDF gerado: ' + nome);
  if (window.mdTrack) mdTrack('crm_relatorio_pdf', { clientes: _records.length });
}

/* ═══════════════════════════════════════════════════════════════════
   MANUAL DO MYDESK — boas-vindas de quem acabou de criar a conta
   Aparece uma única vez, no primeiro acesso, e só para conta NOVA. São duas
   travas, porque uma só não basta: a marca de "já viu" mora no localStorage
   por uid (é preferência de exibição, não vale uma escrita no banco a cada
   login — mesma decisão dos avisos do período de teste), mas localStorage
   morre quando a pessoa troca de navegador. Sem a segunda trava, um usuário
   antigo entrando de outro computador levaria as boas-vindas na cara.

   O texto vive aqui, e não no HTML, porque os números do plano (limite de
   notas, dias de teste, meta de indicação) são interpolados das constantes:
   escritos à mão, o manual passaria a mentir no dia em que um deles mudasse.
   ═══════════════════════════════════════════════════════════════════ */
const MANUAL_VERSAO = 1;

const MANUAL_GRUPOS = [
  {
    titulo: 'O básico',
    itens: [
      { icone: '➕', nome: 'Nova nota', texto:
        'Cria uma nota no quadro. Primeiro você escolhe o tipo: <b>Nota Pessoal</b> ' +
        '(texto livre, tarefas, links, arquivos anexados e prazo) ou <b>Nota de Cliente</b> ' +
        '(nome, valor a receber e status de pagamento — essa também aparece na aba Clientes). ' +
        'Depois de criada, arraste a nota para onde quiser e puxe o canto para mudar o tamanho.' },
      { icone: '⚡', nome: 'Reorganizar', texto:
        'Abre o painel de ordenação do quadro: por data de criação, título de A→Z, prazo mais ' +
        'próximo, status ou cor. O botão <b>Resetar</b>, dentro do painel, devolve a ordem original.' },
      { icone: '🗑️', nome: 'Limpar tudo', texto:
        'Apaga todas as notas do workspace em que você está. Não precisa se assustar: logo ao ' +
        'lado aparece o botão verde <b>Restaurar</b>, que traz tudo de volta.' },
      { icone: '🎨', nome: 'Fundo', texto:
        'Troca o fundo do quadro: cores sólidas, gradientes, cenas em <b>pixel art</b> animadas, ' +
        'uma coleção de imagens prontas, vídeos em loop ou uma imagem sua do computador. ' +
        '<b>Restaurar padrão</b> volta para o azul com que a sua conta começou.' },
    ],
  },
  {
    titulo: 'Trabalho e dinheiro',
    itens: [
      { icone: '📊', nome: 'Clientes', texto:
        'Alterna entre o quadro de notas e o <b>CRM Financeiro</b>. Cada cliente vira uma linha ' +
        'com valor, vencimento e status (pago ou pendente), e os cartões do topo somam quanto ' +
        'você tem a receber. Dá para buscar pelo nome e ordenar clicando no cabeçalho da tabela.' },
      { icone: '🔔', nome: 'Eventos', texto:
        'Seu painel de prazos, com as abas <b>Eventos</b>, <b>Orçamento</b>, <b>Despesas</b> e ' +
        '<b>Tarefas</b>, mais um calendário do mês. O número vermelho no botão avisa quando algum ' +
        'compromisso está chegando.' },
      { icone: '📁', nome: 'Workspaces', texto:
        'Quadros compartilhados com outras pessoas — em grupo ou numa conversa de dois. O que ' +
        'você escreve lá <b>nunca</b> se mistura com o seu quadro pessoal.' },
      { icone: '🏷️', nome: 'Seu nome, no canto esquerdo', texto:
        'Clicar no seu nome abre os <b>workspaces pessoais</b>: quadros separados, só seus, para ' +
        'dividir contextos (por exemplo “Trabalho” e “Casa”) sem misturar as notas.' },
    ],
  },
  {
    titulo: 'Pessoas',
    itens: [
      { icone: '👥', nome: 'Amigos', texto:
        'Procure pessoas pelo nome de usuário, mande convite e converse por chat em tempo real. ' +
        'Do próprio chat saem as <b>chamadas de voz e vídeo</b> e o compartilhamento de tela.' },
      { icone: '🎁', nome: 'Convidar', texto:
        'Seu link de indicação. A cada <b>' + INVITE_META + ' amigos</b> que criarem conta por ' +
        'ele, você ganha uma recompensa no seu plano.' },
      { icone: '🚪', nome: 'Sair', texto:
        'Encerra a sessão. Suas notas ficam salvas na sua conta e voltam no próximo login, de ' +
        'qualquer computador.' },
    ],
  },
];

/* A segunda trava. A data de criação vem do Firebase Auth (creationTime), a
   mesma fonte do período de teste: é emitida pelo Auth e o usuário não
   consegue reescrever. Sem data conhecida — sessão demo, por exemplo — não
   dá para afirmar que a conta é nova, então não mostra. */
const MANUAL_JANELA_MS = 24 * 60 * 60 * 1000;

function _contaNova() {
  const criadoEm = window._fbAuth?.currentUser?.metadata?.creationTime;
  const t = criadoEm ? Date.parse(criadoEm) : NaN;
  return !Number.isNaN(t) && (Date.now() - t) < MANUAL_JANELA_MS;
}

function _manualVisto() {
  try { return localStorage.getItem('md_manual_v' + MANUAL_VERSAO + '_' + (CU?.uid || '')) === '1'; }
  catch (_) { return false; }
}
function _manualMarcar() {
  try { localStorage.setItem('md_manual_v' + MANUAL_VERSAO + '_' + (CU?.uid || ''), '1'); } catch (_) {}
}

function abrirManual() {
  document.getElementById('md-manual')?.remove();
  _manualMarcar();

  const corpo = MANUAL_GRUPOS.map(g =>
    '<div class="mn-grupo">' + xe(g.titulo) + '</div>' +
    g.itens.map(i =>
      '<div class="mn-item">' +
        '<div class="mn-icone">' + i.icone + '</div>' +
        '<div><div class="mn-nome">' + xe(i.nome) + '</div>' +
        '<div class="mn-texto">' + i.texto + '</div></div>' +
      '</div>').join('')
  ).join('');

  const overlay = document.createElement('div');
  overlay.id = 'md-manual';
  overlay.innerHTML =
    '<div class="mn-card">' +
      '<div class="mn-head">' +
        '<div><div class="mn-eyebrow">Manual</div>' +
        '<h2 class="mn-title">Bem-vindo ao MyDesk</h2></div>' +
        '<button class="mn-x" id="mn-x" aria-label="Fechar">&#10005;</button>' +
      '</div>' +
      '<div class="mn-body">' +
        '<p class="mn-intro">Cada botão da barra do topo faz uma coisa. Aqui está o que é cada um, ' +
        'para você não precisar descobrir no tato.</p>' +
        corpo +
        '<div class="mn-grupo">Seu plano</div>' +
        '<div class="mn-item"><div class="mn-icone">⭐</div><div>' +
          '<div class="mn-nome">Grátis, Premium e os ' + TRIAL_DIAS + ' dias de teste</div>' +
          '<div class="mn-texto">Sua conta começa com <b>' + TRIAL_DIAS + ' dias de tudo liberado</b>. ' +
          'Depois disso o plano gratuito continua funcionando, com até <b>' + PLAN_FREE_LIMIT +
          ' notas por mês</b>; o CRM Financeiro, os workspaces de grupo, os fundos em vídeo adicionais e as ' +
          'cores de nota em gradiente passam a pedir Premium. ' +
          '<b>Nenhuma nota sua é apagada quando o teste acaba.</b></div>' +
        '</div></div>' +
      '</div>' +
      '<div class="mn-foot"><button class="mn-btn" id="mn-ok">Entendi, começar</button></div>' +
    '</div>';

  const style = document.createElement('style');
  style.textContent =
    '#md-manual{position:fixed;inset:0;z-index:9997;display:flex;align-items:center;justify-content:center;' +
      'background:rgba(0,0,0,.72);backdrop-filter:blur(6px);padding:20px;opacity:0;transition:opacity .3s;}' +
    '#md-manual.show{opacity:1;}' +
    '#md-manual .mn-card{background:#14141c;border:1px solid rgba(255,255,255,.1);border-radius:20px;' +
      'width:100%;max-width:560px;max-height:86vh;display:flex;flex-direction:column;overflow:hidden;' +
      'box-shadow:0 30px 80px rgba(0,0,0,.6);font-family:Inter,sans-serif;transform:translateY(14px);transition:transform .3s;}' +
    '#md-manual.show .mn-card{transform:translateY(0);}' +
    '#md-manual .mn-head{display:flex;align-items:flex-start;gap:12px;padding:24px 26px 16px;' +
      'border-bottom:1px solid rgba(255,255,255,.07);}' +
    '#md-manual .mn-eyebrow{font-size:.68rem;letter-spacing:.14em;text-transform:uppercase;color:#818cf8;font-weight:700;}' +
    '#md-manual .mn-title{margin:4px 0 0;font-family:Syne,sans-serif;font-size:1.42rem;color:#f5f5f7;font-weight:800;}' +
    '#md-manual .mn-x{margin-left:auto;background:none;border:none;color:rgba(245,245,247,.4);font-size:1.05rem;' +
      'cursor:pointer;padding:4px 6px;line-height:1;font-family:inherit;}' +
    '#md-manual .mn-x:hover{color:#f5f5f7;}' +
    '#md-manual .mn-body{overflow-y:auto;padding:18px 26px 8px;}' +
    '#md-manual .mn-intro{margin:0 0 18px;font-size:.86rem;line-height:1.6;color:rgba(245,245,247,.62);}' +
    '#md-manual .mn-grupo{font-size:.68rem;letter-spacing:.13em;text-transform:uppercase;' +
      'color:rgba(245,245,247,.34);font-weight:700;margin:20px 0 10px;}' +
    '#md-manual .mn-item{display:flex;gap:13px;padding:11px 0;border-top:1px solid rgba(255,255,255,.05);}' +
    '#md-manual .mn-icone{font-size:1.18rem;line-height:1.4;flex-shrink:0;width:26px;text-align:center;}' +
    '#md-manual .mn-nome{font-size:.9rem;font-weight:700;color:#f5f5f7;margin-bottom:3px;}' +
    '#md-manual .mn-texto{font-size:.83rem;line-height:1.62;color:rgba(245,245,247,.62);}' +
    '#md-manual .mn-texto b{color:#a5b4fc;font-weight:600;}' +
    '#md-manual .mn-foot{padding:14px 26px 22px;border-top:1px solid rgba(255,255,255,.07);}' +
    '#md-manual .mn-btn{width:100%;background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff;border:none;' +
      'border-radius:11px;padding:13px;font-size:.9rem;font-weight:700;cursor:pointer;font-family:inherit;' +
      'box-shadow:0 6px 22px rgba(99,102,241,.35);}';
  overlay.appendChild(style);

  document.body.appendChild(overlay);
  requestAnimationFrame(() => overlay.classList.add('show'));

  const onEsc = e => { if (e.key === 'Escape') fechar(); };
  const fechar = () => {
    overlay.classList.remove('show');
    document.removeEventListener('keydown', onEsc);
    setTimeout(() => overlay.remove(), 300);
  };
  document.addEventListener('keydown', onEsc);
  overlay.querySelector('#mn-ok').addEventListener('click', fechar);
  overlay.querySelector('#mn-x').addEventListener('click', fechar);
  overlay.addEventListener('click', e => { if (e.target === overlay) fechar(); });

  if (window.mdTrack) mdTrack('manual_aberto');
}

/* Não pode abrir por cima do aviso do período de teste, que nasce logo depois
   do plano carregar e é o mais importante dos dois — por isso espera ele sair
   da tela em vez de disputar espaço. A checagem de conta nova fica aqui dentro,
   e não na hora de agendar, porque no cadastro o currentUser do Auth pode
   ainda não ter assentado quando o app abre. */
function agendarManualPrimeiraVez() {
  if (_manualVisto()) return;
  let tentativas = 0;
  const tick = () => {
    if (_manualVisto()) return;
    if (document.querySelector('.trial-modal-bg')) {
      if (++tentativas > 30) return;   // ~1 min esperando; depois desiste
      return setTimeout(tick, 2000);
    }
    if (!_contaNova()) return;
    abrirManual();
  };
  setTimeout(tick, 3500);
}
